/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20111011-4","meetingId":"h23-c-settlement","date":"2011年10月11日","dateIso":"2011-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後５時２９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開きます。 それでは、平成２２年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開きます。 それでは、平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"先に立会川のことであります。これは、１０月８日、そこに行って写真を撮ってきたんですけれども、浜川砲台、最近、区長いらしてもよかったんですけど、行かれたことある理事者、いらっしゃいますでしょうかね。だけども、私ども品川区議会自民党としては、立会川、坂本龍馬を中心として、羽田空港、京浜急行、それから大井競馬場等の交通要所等、それから観光資源の連携を提案しました。お願いいたします。","respondent":"米田商業・観光課長","answer":"今年度におきましても、地元商店街の振興施策として龍馬と連携したオブジェの建設等を予定しておりまして、観光と商店街振興、うまく絡め合わせました施策を今年度も図っているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"提案","question":"ある程度理解している部分はあるんですけれども、ただ、浜川砲台の跡地は、それは東京都の港湾局の管理になるということは私たちもわかっています。だから、随分前の委員会で提案したのは、それを新浜川公園へ移設をするとか、それから、商店街、近隣の皆様方の理解のもとに、あの立会川から砲台跡までの誘導をしていくとか、やっぱりいろんな具体的なプランを行政は示していく必要があると私は思うんですよ。","respondent":"米田商業・観光課長","answer":"坂本龍馬の盛り上げというようなことで、地元を含め、有志の団体等ございまして、そちら側の意見、あるいは地元商店街等の意見も踏まえ、またよりよい方向性を図っていければというふうに考えてありますので、よろしくお願いいたします。","voiceIndex":6,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"だから、何を言いたいかというと、こういう観光資源、一定の歴史的なものがあるならば、やっぱりそのことを品川区はしっかりとらまえた上で、今の答弁でも理解するところあるんだけれども、では、いつまでにこうするとか、いつまでも検討ばかりしていては物事は進まないわけであって、もう一言、深い希望のあるお話をいただければと思うんですが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういった意味では、１つの観光資源として今後何かしら施策に反映できればというようなことは考えてあります。今の段階でこの時期までにということは大変難しゅうありますが、常に頭の中に置いて今後の対策等を考えてまいりたいと思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"ぜひよろしくお願いします。改めてお願いしておきます。その理由が、東京都財務局が都有地の有効活用策を検討する過程で、東京都のほかの局が合法的に品川区に貸してくれたものについて、それは品川区に都資産有効活用の観点から返しなさいという申し入れがあったと聞きますけれども、その経過が正しいのかどうかということの事実確認をまずお願いします。","respondent":"藤田水とみどりの課長","answer":"マイガーデンの南大井ですが、平成２３年４月に、これまで５７区画だった区画を２７区画に変更しています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、このマイガーデンは、もう担当ですからご存じだと思うんですけど、非常に申し込みの倍率も高くて人気が高いんですよ。当たり前のことじゃないですか。例えば区民が何かしら間違いを起こして使用できなくなったわけではなくて、あくまで行政の都合でそうなってしまったわけだから、やっぱりそのことについては一定の責任で対処すべきと思うんですが、いかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"しかしながら、安全性の問題ですとか、その辺も含めながら、現段階では今２７区画で運用しています。今後も有効な土地があれば活用に向けて検討を進めていきたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"となると、もちろん品川区の責任で探してほしいんだけれども、やっぱりそこに東京都を絡ませることはできないんですか。品川区のレベルでもちろん考えることも必要なんだけども、特にこういうマイガーデンの背景のことを考えれば、品川区と東京都が連携した上で代替地を探していくという、より一体的な方法を考えていくべきと思うんですが、そのことについてのもう１回の答弁をお願いいたします。","respondent":"藤田水とみどりの課長","answer":"これまで豊町の区画等については、東京都の道路用地、この辺の有効活用ということで行ってきてありますので、今後も東京都とはいろいろ話をしながら進めていきたいと考えております。その中で、無償で借りられるということであれば、区としても行っていきたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こちらの考え方は伝わったと思いますので、ぜひ品川区の観点だけではなくて、このマイガーデンに関連しては東京都も関連した話ですから、そのことを踏まえた上での対応をお願いをしておきます。お願いいたします。","respondent":"小川健康課長","answer":"特にペプシノゲンという血液中の消化酵素の量を調べるということと、それから、ピロリ菌というものに感染しているかどうかを調べる検査の２つによって調べることにより、異常の判定などをスクリーニングしながら、その後何も異常がないか。","voiceIndex":16,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういうことをまとめて聞きますけれども、これはすぐに健診につなぐことはないと思うけれども、ただ、二十歳という具体的な大人の入り口に立ったときに、それがその人の生涯にわたる健康につながっていくことを考えていくとするならば、例えば二十歳での唾液の検査とか、そういうことを行って、その方の意識づけ、啓蒙につなげていくべきと考えますが、いかがでしょうか。","respondent":"小川健康課長","answer":"現在、区としましては、成人歯科健診というのは、４０から７０歳までの５歳刻みということで健診をやらせていただいております。ご提案の二十歳の唾液検査ですが、こちらは口腔の健康に対するリスクが高いのか、低いのか、唾液の中の菌などを測定して判定するものです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひ具体的な研究と検討をお願いをしておきます。子宮頸がんに関連してです。これはワクチン摂取で、がん防止につなぐということは、これは一時的に賛成しますし、推進すべきと私も考えております。そういうことを考えていくと、これはやはり品川区での接種については、こういう事例も十分踏まえた上で慎重に対処すべきと考えますが、いかがでしょうか。答弁をお願いいたします。","respondent":"伊津野保健予防課長","answer":"ワクチンの危険性につきましても、先ほど１例死亡例がありましたが、専門家の検討の会議の結果では特に因果関係はないという結論になっております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問","question":"私のほうからは成果報告書の１４５ページ、母子健康診査費、それから１４６ページの母子保健指導事業費についてお尋ねをいたします。妊娠届の時期についてですが、妊婦の方がいつの時点で提出しているか。いわゆる妊娠週数別の届出内訳があれば、平成２２年度で結構ですので、教えてください。","respondent":"小川健康課長、矢野品川保健センター所長","answer":"届出のタイミングですが、妊娠がおわかりになった時点で届出をしていただく、判明した時点でしていただくということになってあります。それによりますと、品川区の場合、大体１１週までに届け出るようになるべくお願いしているところですが、平成２１年度の場合は、総届出数３,６４８件中、３,４０７件で。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鶴委員","kind":"確認","question":"平成２１年ですね。確認です。平成２１年度ということで、大体の方がいわゆる１１週までに届出をしていただいているということがわかりました。外国籍の方は、把握をしていないということですので、品川区、それなりに外国籍の方が結構いらっしゃると思うんですね。ちなみに、外国籍の方に交付する母子健康手帳、現在何カ国語による手帳が用意されているのか、おわかりになりますでしょうか。","respondent":"小川健康課長","answer":"一応８カ国語用意しています。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"８カ国語ですね。ちなみにその言語、わかれば教えていただけますか。","respondent":"小川健康課長","answer":"今ちょっと手元にございませんので、後でご報告します。申しわけございません。","voiceIndex":30,"id":"exchange-012"},{"speaker":"鶴委員","kind":"提案","question":"後ほど教えていただきたいと思います。今お尋ねした外国籍の方に関連する質問ということで、ちょっと今お尋ねいたしましたので、後ほどします。ある自治体では、妊娠週数別に届出の実態把握をしているところもあると思います。先ほどほとんどの方が１１週までというお話ありましたけれども、品川区が目指す子育ての拡充強化の観点からも、こうした妊娠週数別の把握を提案いたしますが、いかがでしょうか。","respondent":"矢野品川保健センター所長","answer":"東京都の母子保健事業報告に載っておりますので、資料というのはあります。事務事業概要に現在載せてないという状況ですので、今後とも、広報あるいはホームページ等で速やかに妊娠届をしてくださいという周知には努めてまいりたいと思います。","voiceIndex":32,"id":"exchange-013"},{"speaker":"鶴委員","kind":"提案","question":"母子健康手帳の内容についてお尋ねをいたします。母親学級の参加者や、先日私も参加をした両親学級、この参加者の声をお聞きすると、母子健康手帳に超音波検査でプリントアウトされたエコー写真、これを張る場所が欲しいという要望がございました。任意記載事項の部分になると思いますけれども、この見開きのマイベイビーのページを増やす形で検討はできないか、提案をいたしますが、いかがでしょうか。","respondent":"矢野品川保健センター所長、小川健康課長","answer":"それ以外にマイベイビーのページなどもありますが、超音波の写真を張る部分については、今後の検討課題とさせていただきたいんですが、例えば品川区ではのびのび子育て応援ガイドというものもございまして。先ほど答弁漏れがございました外国語の母子手帳の８カ国語ですが、英語、中国語、タイ語、スペイン語、インドネシア語、ポルトガル語、タガログ語、ハングル語の８カ国語です。","voiceIndex":34,"id":"exchange-014"},{"speaker":"鶴委員","kind":"質問","question":"それぞれありがとうあります。副教材というか、副読本という言い方をするんでしょうかね、ご答弁いただいたもの。次に、妊婦・産婦歯科健診についてお尋ねをします。品川区が平成７年から実施をしている妊婦歯科健康診査の受診者数を見てみますと、平成２０年が９７０人、平成２１年が８５０人、平成２２年が９０４人で、この過去３年の平均受診率は２４.１％と低い受診率となっていると思います。","respondent":"小川健康課長","answer":"妊婦の通常の健診ですと、かなりの受診をいただくところですが、やはりご指摘のように、歯医者に行かなければならないということが、やはり妊婦、産婦の方の大きなご負担になるのではないかというふうに分析をしておるところですが、こちらとしましては。","voiceIndex":37,"id":"exchange-015"},{"speaker":"鶴委員","kind":"確認","question":"品川区においても、こうした観点から早期から実施をしていただいていると思いますけれども、今ちょっとご答弁ありましたが、もう一度確認の意味で、初産婦の方も、または経産婦の方も、こうした受診率が向上するような工夫が必要かと考えます。その上で、今ちらっとさらっとご答弁いただきましたけれども、もうちょっと具体的な啓発のお考えをお聞きしたいなと思いますので、ご答弁をお願いします。","respondent":"矢野品川保健センター所長","answer":"その数につきましては、１,２３９ということで上げてあります。","voiceIndex":39,"id":"exchange-016"},{"speaker":"鶴委員","kind":"質問・要望","question":"母親学級で１項目設けられているということも今お聞きしました。次に、母子保健指導事業費の健やか親子学習についてお尋ねをします。そこでお尋ねしますが、現在品川区の「二人で子育て」は、土日開催が品川保健センター、荏原保健センターで月１回、午前、午後の開催も含めて、各回２４組で、平日開催が多い保健センターで２カ月に１回で各１２組の開催となっておりますが、この数字でよろしいでしょうか。","respondent":"矢野品川保健センター所長","answer":"それでよろしいです。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鶴委員","kind":"確認","question":"あくまで確認でした。ホームページから確認をさせていただきました。先日私も荏原保健センターで「二人で子育て」に参加をさせていただいて、お父さんの沐浴体験、それから妊婦ジャケット体験など、どれだけ妊婦の方が大変なのか、または出産後、パートナー、つまり夫の協力の重要性を改めて痛感をさせていただきました。ちょっと時間がないので、最後質問だけしますが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"鶴委員","kind":"質問・要望","question":"ないですね。答弁できないですね。なので、ちょっと切らしますが、今後もこうした両親学級等へのパートナーの方の参加向上にもしっかりと啓発をしていただきたい、このようにお願いして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"私からは大きく５項目、１番目に、ページ数、１４９ページ、１５２ページのカラス対策についてと、次が１５１ページ、リサイクルショップ事業について、支援について、それから１４３ページの結核健康診断について、１４４ページの乳がん検診についてと、最後に妊婦への粉ミルク支給、母親への栄養支給が昨年度までやっていたと思うんですが、以上をお尋ねしたいと思います。","respondent":"野呂瀬環境課長、太田品川区清掃事務所長","answer":"カラス対策事業のことです。事項別明細書でいうと１４９ページ、こちらがカラス対策事業ということになっております。１４９ページのカラスの部分というのは、カラスの巣を除去するとか、そういう一般的な対策を実施しています。","voiceIndex":47,"id":"exchange-020"},{"speaker":"向委員","kind":"質問","question":"わかりました。では、それぞれ分かれている理由はわかりまして、そうしますと、防鳥ネットについてなんですけれども、カラスは大変賢い動物というのは皆さんよくご存じだと思いますが、このネットの貸し出しは有料ですか、無料ですか。","respondent":"太田品川区清掃事務所長","answer":"無料で貸し出しをしております。そして、管理についても、皆さんでお願いをしています。","voiceIndex":50,"id":"exchange-021"},{"speaker":"向委員","kind":"質問","question":"続けてカラスに関してなんですが、品川区では大体家庭ごみの回収時間、回収に要する時間というのは大体朝何時から終わるのが何時までで、大体何時間ぐらいかかるんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"燃えるごみの収集と、それから陶器・ガラス・金属ごみの収集です。一般的に８時に事務所を出てまいります。それで、日によって４回から５回ぐらい各地域を回収してもらいます。品川区、燃やすごみについては、各戸収集という２３区にない唯一の収集の仕方をしています。","voiceIndex":52,"id":"exchange-022"},{"speaker":"向委員","kind":"質問","question":"カラス対策は本当に難しい事業というのは、私、よくよく承知しております。このあたりの新しい対策を考えるというか、そういったそのあたりのお考えっていかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"夜間収集については、地域によっては繁華街が多いというところでは、夜間収集をしているというところを承知はしていますが、やはり何といっても費用対効果というものを考えると、現在のところ実施する考えはないです。","voiceIndex":54,"id":"exchange-023"},{"speaker":"向委員","kind":"質問","question":"次にリサイクルショップについてお尋ねします。１５１ページのところで、これは品川区が支援をしていただいて、１,０００万円ぐらい決算に上っていますけれども、このリサイクルショップの支援というのを、運営費の支援の分については、これはリサイクルショップの運営費の大体どのぐらい割合を占めているんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"その前は区の直営といいますか、区が直接設置をして実施をしていたところですけれども、区の条例を設置してやっていた、手数料が一律化するとか、民間のノウハウが必要だというところから、ＮＰＯ法人に自主的に運営をお願いをしたというところから。","voiceIndex":56,"id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"私もリサイクルショップ、よく利用します。区内にも、リボンさん以外にも、自営というか、いろんなところでご自身で経営されているリサイクルショップもかなり増えてきていますけれども、いつまでこの支援は続けていかれるご予定ですか。もうずっと続けていかれるのか。そのあたりをお教えください。","respondent":"太田品川区清掃事務所長","answer":"そういう面で、やはり区が直接従事するよりも、民間のノウハウを活用しながら民間で自主的にやっていただけるような組織がないかということで検討をしていたところ、環境活動推進会議の中、現在あるんですけれども。","voiceIndex":58,"id":"exchange-025"},{"speaker":"向委員","kind":"質問","question":"過去の厚生委員会でも、３０代から４０代の働き盛りの年代にも罹患者がいるので、気をつけていきたいという区のお考え等も、理事者の答弁、私も読みましたけれども、今検診は６５歳以上、もしくはハイリスク患者が無料ということになっているかと思いますが、このあたり、若い年代の方、３０代とか４０代、もっとほかの自治体とか、１８歳から無料という検診を引き続き続けている自治体もあるようなんですが。","respondent":"伊津野保健予防課長","answer":"委員ご指摘のように、若い世代についての、３０代、４０代についての結核も最近になってまた少し増えておりますが、結核の検診につきましては、職域の健康診断の中でのＸ線撮影に置きかえていただくということで、結核検診としましては６５歳以上の対象者を実施しています。","voiceIndex":60,"id":"exchange-026"},{"speaker":"向委員","kind":"質問・要望","question":"そうですね、確かに若い年代も罹患者が増えてきていますので、予防に重点を置くという点で、要望なんですけれども、平成１８年に廃止になった若い方への検診も、いま一度必要性が出てきたら、今後もう一度再開するとか、ご検討いただければと思います。続けて１４４ページの乳がん検診なんですけれども、今、年齢が３４歳以上になっていると思います。","respondent":"小川健康課長","answer":"乳がん検診ですが、あくまでも国のガイドラインとしましては４０歳以上ということになってあります。とはいえ、品川区ではもう少し早めということで、独自に３４歳以上ということで始めたものです。","voiceIndex":62,"id":"exchange-027"},{"speaker":"向委員","kind":"質問・要望","question":"というのも、多分ご存じだと思うんですけれども、２００５年の厚生労働省がカルシウムの食事摂取量を発表している中で、カルシウムとかであれば、妊婦、妊娠をしたからといっても、カルシウムを余計プラスアルファでとらなくてもいいという発表がもう既に２００５年に出ていると思うんですけれども、この粉ミルクをどうして昨年度まで、ことしはもう事業廃止になっていると伺っているんですけれども。","respondent":"小川健康課長","answer":"実際には、乳児用粉ミルク等を支給していたんですけれども、申請者がいなかったということで、平成２２年度につきましても、事務経費のみで、実際には支給は行われてございません。","voiceIndex":64,"id":"exchange-028"},{"speaker":"向委員","kind":"質問","question":"妊婦の方への支給というわけではなくて、乳児用の粉ミルクということであったんでしょうか。私がお尋ねしたいのが妊婦さん用なので、そのあたりお願いします。","respondent":"小川健康課長","answer":"乳児用粉ミルクとともに妊産婦用粉ミルクとあわせましての支給をさせていただいてきたところですが、一応平成２２年度で事業終了ということになりました。","voiceIndex":66,"id":"exchange-029"},{"speaker":"向委員","kind":"質問","question":"これは栄養というのは全面的な補助でしょうか。私が先ほどお尋ねしたカルシウムに特化してとか、何か鉄分とか、そのあたりを詳しくお答えをお願いします。","respondent":"矢野品川保健センター所長","answer":"この母子栄養食品の支給ですが、カルシウムに特化したものではございませんで、全体の栄養というところで低所得者層に対する補助ということで続けていたものです。","voiceIndex":68,"id":"exchange-030"},{"speaker":"向委員","kind":"質問・要望","question":"この栄養の支給ということで、ほかの区でも引き続き続けているような区もあったりとか、自治体とかでも続けているという区はあるんですけれども、実際カルシウムの件は私はちょっと調べたんですが、妊娠中毒症だったりとか、さまざまな経済的な理由で妊婦さんへの補助というのは引き続き別な形でも続けていっていただきたいと思います。これは要望になりますが、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"銭湯の廃業に伴ってお風呂に入れない区民への支援等、公衆浴場の存続と振興に向けた支援強化を求めて伺いたいと思います。浴場組合の方にお話を伺っても、いつ廃業してもおかしくない銭湯はほかに幾つでもあると危機感を募らせていました。具体的に南品川一丁目から六丁目の高齢者にとって、東品川シルバーセンターに歩いて通える距離だと思うのか、伺いたいと思います。","respondent":"小川健康課長","answer":"こちら、区内全域で見ますと、委員ご指摘のとおり、人口割、面積割で見ますと、まだまだ２３区内では平均レベルにあることは間違いございませんが、ご指摘の特定の大井地区等を中心に、やはり歩いていくことが困難な地域が起きてしまっているという事実に関しては。","voiceIndex":72,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"今お話がありましたけれども、確かに平均値で見ると、２３区、東京都を上回っているんだとは思いますけれども、実際はお風呂に入れない区民の家と銭湯との距離、坂、勾配、こういった地域事情をしっかり見ていかないといけないと思うんですけれども、ここをどう考えているのか、改めて伺います。","respondent":"小川健康課長","answer":"これまでの公衆浴場組合とのおつき合いの仕方ですが、例えば公衆衛生上の指導や助言であったりだとか、設備改修時の助成等と、また、あるいは出会いの湯の事業のご協力をいただいたりというような関係ですが、さらにそれに踏み込みまして。","voiceIndex":74,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこをどう考えているのか伺いたいと思います。私は品川区、行政にあると思いますけれども、ここをはっきりとご説明いただきたいと思います。それで具体的な支援策ですけれども、例えば区立の公衆浴場、緊急策として銭湯までの足を確保するコミュニティバスや送迎や、こうした足を確保する、こうしたことを考えていく必要があると思うんですけれども、いかがでしょうか。","respondent":"小川健康課長","answer":"繰り返しのご答弁になりますが、区独自の施策というよりも、今はやはり公衆浴場組合とともにいろいろな方策を考えていきたいということが今の区としてのスタンスです。","voiceIndex":76,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"お風呂に入ることができない区民への支援を重ねて求めます。そして次に、お風呂に入れない区民の支援とあわせて、次に伺いたいのは、今ある銭湯の支援強化です。先日も台風１５号の風の影響で、東京都内ですけれども、煙突が倒れたと。それもこの震災の影響とも伺いました。とりわけ浴場組合の方が話していたのは、煙突が倒れるというのは致命的だと、そう危機感を話しておりましたが、いかがでしょうか。","respondent":"小川健康課長","answer":"ただ、今、区としましても、改修、改築、それぞれの補助金制度があります。都のほうにも制度があります。こちらを抱き合わせで上手に使っていただいて、存続に向けて浴場については支援をしていきたいと考えています。","voiceIndex":78,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に伺いますけれども、公衆浴場への改修や改築の補助金についてですけれども、まず改築ですけれども、東京都は補助対象４分の１で１施設７,５００万円、品川区は補助対象２０分の１で１施設１,０００万円。日常の改修と大震災の被害の改修費合わせて品川区の限度額を引き上げてほしい。煙突も含めて耐震化支援を進めてほしいと思いますけれども、いかがでしょうか。","respondent":"小川健康課長","answer":"耐震ですが、都の制度があります。耐震改修、それから耐震診断についても都の制度がありますので、こちらについて区として改めてということは今は考えてございません。","voiceIndex":80,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"浴場組合の方にお話を伺いましたけれども、３０年以上経過している建物、ボイラー、熱交換機などの整備も、毎年の売り上げ減少のため入れかえも容易でないと。その上にこの大震災の被害です。ぜひ品川区も支援してほしいということですけれども、整備の、設備の、建物の補助とあわせて、こうした事業への支援を進めていただいて、存続や振興を強化していただきたいと思いますが、いかがでしょうか。","respondent":"小川健康課長、米田商業・観光課長","answer":"出会いの湯事業についてですが、こちらはあくまでも区と公衆浴場組合との契約でしているものです。こちらの契約につきましては、これからも公衆浴場組合とお話し合いを続けていく中でいろいろ考えてまいりたいと思います。公衆浴場商業協同組合事業助成補助金というのがあります。そちらの中で、先ほどご指摘のありました、菖蒲湯および友～湯銭湯スタンプラリーにつきましては、一定金額の助成を行っているところです。","voiceIndex":82,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"各種事業についてですけれども、子どもたちに銭湯のよさを知っていただきたい。家族も一緒にということで、新たな顧客もやってきた。いろいろ努力をしているわけですよね。その中で持ち出しが増えているという実情がありますので、ぜひ実態に即して支援を強化していただきたいと改めてお願いしたいと思います。ぜひここを強くお願いをしたいと思いますが、いかがでしょうか。","respondent":"小川健康課長","answer":"区としましても、今の浴場の数を維持していきたいと考えています。","voiceIndex":85,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"１４６ページ、健康づくり支援事業、１５３ページ、景況調査、１５５ページ、プレミアム付商品券、小規模商店街についてお伺いします。区がそのお手伝いをすることはいいんですけれども、ここまで行政としてやることはないんじゃないかというふうに毎回から思って質問させていただいているんですけれども、その辺についていかがでしょうか。","respondent":"小川健康課長","answer":"健康づくり宣言認証制度ですが、詳しい内容については省かせていただきますが、ねらいといたしましては、そういった健康づくりに積極的な方を認証して、周りにも活性化をしていただく、輪を広げていただきたいという思いがあったんですが、ご指摘のとおり。","voiceIndex":88,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと財源がものすごくいろいろ出ていて厳しいということで認識されていると思うんですけれども、私の考えでは、財源が厳しい、だから廃止してくださいというよりも、いつも言っておりますが、民のできる仕事は民、そして行政でする中でも、やっぱりむだ、不要、不急の事業はやらない、そういう考えでこれからの行政も進めていただきたいということを思いつつ、次は、歳入のときも申し上げましたが。","respondent":"米田商業・観光課長","answer":"先日、今年度第１四半期の景況調査が発表されました。品川区内における、特に商業者の景況ですが、前期よりは持ち直しはしているというようなことで、向上の兆しは見られるが、相変わらず厳しい状況が続いているというようなことでの報告をいただいております。","voiceIndex":90,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"厳しい中でも行政がどれだけ景気回復に商店街含めて協力していくかだと思うんですけれども、多分同じ課長の答弁だと思うのでまとめて聞いちゃいますが、プレミアム付商品券の効果についてと、あと、小規模商店街の助成についての効果を教えていただきたいんですけど、小規模に関しては、特に前回、前々回にやった山王商店街、やりましたよね。あの効果も含めて答弁していただけますか。","respondent":"米田商業・観光課長","answer":"貯蓄に回らず、近隣等の商店街にある一定の期間でお金が落ちるというようなことで経済効果が見込めると考えています。小規模商店街の支援ですが、小規模商店街、特に基盤が苦しゅうあります。","voiceIndex":92,"id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"課長、区の行政の仕事なのに、内容聞いているんじゃないじゃないですか。こういう施策をやってどういう効果が出たんですかって聞いているのに、３分も使って内容説明されてどうするんですか、１０分しかないのに。","respondent":"米田商業・観光課長、山田副区長","answer":"その後も含めて、小規模商店街の活性化ということで、続けて再生事業等、取り組んです。その中で、集客効果が見込めた等のご意見も踏まえまして、今後とも小規模商店街の支援、行ってまいりたいというようなことで考えてあります。というのは、品川区から、いわゆる小さい商店街ではあるけれども、区民の皆様方にとっては必要な商店街なんだというところを認識いたしまして、区としては頑張っていただく意味合いでのメッセージをお送りしながら。","voiceIndex":96,"id":"exchange-042"},{"speaker":"藤原委員","kind":"質問・要望","question":"平成２１年が２億円と３億円、あと、３億円、３億円と来ているんですけれども、この効果がある施策に対していつも伺うと、緊急経済対策だからというふうに毎回言われちゃうんですけれども、それはわかります、緊急経済対策。額ですね、今度。見直す。伸ばすというのは、額ですから、５億円、５億円という要望をしますが、それについて、もう内容はいいですから、明確な答弁をいただきたいと思います。","respondent":"米田商業・観光課長","answer":"この間の区内経済状況、あわせかんがみまして、額等も含めて今後検討してまいりたいと、このように考えてあります。","voiceIndex":99,"id":"exchange-043"},{"speaker":"阿久津委員","kind":"確認","question":"本当に区民にとって欠かせない医療サービスになっておりますが、昨日発表の広報しながわに応急診療所の診療日程が載っておりますけれども、確認したところ、毎号これは掲載されていますが、このほかに診療日程や医療機関の周知というのをどのように行われていらっしゃるんでしょうか。","respondent":"小川健康課長","answer":"そういったところで、あらゆる手段を使ってＰＲをさせていただいているところです。","voiceIndex":102,"id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問","question":"あらゆる手段を使ってお知らせいただいているということなんですが、その広報しながわの応急診療所の同じ欄に救急相談センターということで、短縮ダイアル、＃７１１９というものと、また同じく小児救急電話相談、＃８０００番というダイアルが案内されていますが、この２つのダイアルについて、簡単に内容とその違いについて教えていただけますでしょうか。","respondent":"小川健康課長","answer":"ともに東京都の事業です。＃７１１９が２４時間対応ということになっておりまして、それから、＃８０００は、特にお子さんの病気に対して、病院に行ったらいいかどうか迷う場面ということもございまして、そういった場面にご相談いただけるような形になっているものです。","voiceIndex":104,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これを冷蔵庫に張っておけばすぐわかると。電話機に張れるようなシールを、厚生労働省と東京都でやっている電話番号かもしれませんが、広報に関しては品川区もやっていらっしゃるので、ぜひこういうのをつくっていただきたいというご要望があったんですが、要望も含めて、こういう周知方法について検討いただきたいんですが、ご見解を伺いたいと思います。","respondent":"小川健康課長","answer":"先ほどの＃８０００ですが、失礼いたしました、国がやっておりますが、都で運営しているという内容です。訂正します。","voiceIndex":106,"id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これからの研究課題ということで、そういったものが冊子に載っているということですけれども、いざというときに、例えば物を詰まらせちゃったとか、そういったときに、それを引っ張り出す、また広報を探し出すというのはちょっと時間がかかるということで、そういう意味での、目の前に置いてほしいと、そういうご要望でしたので、どうぞよろしくお願いします。","respondent":"工藤生活衛生課長","answer":"猫の不妊・去勢手術費の助成の件につきましてのお尋ねです。平成２２年度の内訳ですけれど、予算上、飼い猫に関しては１９０頭、また飼い主のいない猫につきましては２００頭、合計３９０頭という形に予算書上なってあります。","voiceIndex":108,"id":"exchange-047"},{"speaker":"阿久津委員","kind":"質問","question":"ホームページで見ると、平成２３年度なんですけれども、そのときの手術助成については、４月１日スタートで、予定頭数に達した時点で終了しますという表記があって、予定頭数というのは、オスが６０頭、メスが２００頭、２６０頭とあるんですが、これも以前は年の期限までに申請しなければいけなかったものを、うちの会派からもいろいろ質問しまして、通年でできるようになったということなんですが。","respondent":"工藤生活衛生課長","answer":"平成２２年度のどの時期に予定頭数に達したかということにつきましては、８月に予定頭数を達したということで、飼い猫のほうの部分で予算残がございましたので、そちらを流用して対応したところです。","voiceIndex":110,"id":"exchange-048"},{"speaker":"阿久津委員","kind":"質問・要望","question":"万単位でかかってきます。こういうボランティア、一生懸命不幸な猫を増やさないとか、地域の衛生環境のために頑張っているボランティアのことを考えると、助成をもう少し頑張って増やしていただきたいという思いがあるんですが、その予定はあるんでしょうか。","respondent":"工藤生活衛生課長","answer":"次の質問の今後の助成に関してのいろいろと単価のアップ等につきましてのお尋ねですけれども、私どもも２３区の状況というものはしっかりといろいろと統計値等、調査をしていますけれども、まずは、先ほど申し上げましたように。","voiceIndex":112,"id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問","question":"どうぞよろしくお願いをいたします。私もいろいろお話を伺う中で、ごみのこともあったんですが、やはり顔や頭すれすれにカラスが飛んできて、危うく襲われそうになったというような、何とかしてほしいと、こういうお話、よく受けます。区民相談件数７５０件、巣等の撤去２３９件。この７５０件の相談数というのと２３９件の撤去というのは、平成２２年度１年間の数字ということでいいんでしょうか。","respondent":"野呂瀬環境課長","answer":"７５０件の相談というのは、平成２２年度１年間の数字です。そのうち２３９件、巣の撤去等を行ったです。","voiceIndex":114,"id":"exchange-050"},{"speaker":"阿久津委員","kind":"質問","question":"その中でカラスの相談窓口をわざわざ設置したという記載があったんですけれども、平成２２年度のことなんですが、平成２２年度で終わってしまったのか。これは平成２２年度で終わってしまったのか。もしやっているのであれば、今までとどのように異なるのか、教えてください。こういうのは区報とかケーブルテレビなどで皆さんに周知をされているんでしょうか。","respondent":"野呂瀬環境課長","answer":"区民の方への周知は、主にカラスというのは４月から６月に繁殖期ですので、４月の時点でホームページまたは広報しながわを通じてＰＲをしています。","voiceIndex":116,"id":"exchange-051"},{"speaker":"阿久津委員","kind":"質問・要望","question":"わざわざこの決算書に記載をしてあるということなので、総合窓口があるということで、ホームページ等、また区民の方にご周知をしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-052"},{"speaker":"沢田委員","kind":"質問・要望","question":"各種助成金のところですけれども、医師会１,１２０万円、歯科医師会３９６万円余、環境衛生、食品衛生、薬剤師会等ありますけれども、公衆浴場は設備補助の関係で高額になっておりますが、こういった各種助成金、団体に対する各種助成金の割り振り方というか、総額を割り振っているのか、それとも、各団体の要望の積み上げを公的要素の強い事業に対して結果としてこういう額になっているのか。","respondent":"小川健康課長","answer":"必ず毎年度計画を出していただきまして、それに基づきまして適正な金額と判断し、助成をしているものです。","voiceIndex":122,"id":"exchange-053"},{"speaker":"沢田委員","kind":"質問","question":"薬剤師会が行っている注射針の回収事業について、近年糖尿病の方が増えていたりとか、高齢者の方が増えていて、自分で注射を行う方が大変増えているということで、注射針の回収が大変だというお話をお伺いしました。今東京都の状況どうなっているのか等、関係ありましたら、ご答弁いただければと思います。","respondent":"太田品川区清掃事務所長、小川健康課長","answer":"注射針の回収についてのお尋ねです。委員ご指摘のとおり、実は東京都が２３区、全区的に回収事業を独自に実施をいたしました。協力していただける薬剤店に回収のボックスとのぼりを付与したと。それに伴いまして、薬剤師会から区の支援の要請がございまして、こちらの助成金を平成２０年、平成２１年とそれぞれ１０万円ずつ上乗せをしたという経緯があります。","voiceIndex":124,"id":"exchange-054"},{"speaker":"沢田委員","kind":"質問","question":"特に東京都のほうから廃止された初期事業ということで、その後は各区でそれなりの対応をとってくれというお話なんでしょうか。","respondent":"小川健康課長","answer":"特に東京都からの引き継ぎのようなものはなかったんですけれども、区の独自の判断として、助成金という形で上乗せをさせていただいたというものです。","voiceIndex":127,"id":"exchange-055"},{"speaker":"沢田委員","kind":"質問・要望","question":"わかりました。そういった事業があるということだったのでお伺いさせていただきました。不妊治療のほうに移らさせていただきたいと思います。これからも続けていってほしいと思うこの事業ですけれども、予算も大分増えてきているところです。今後の見通しについてお伺いさせていただければと思います。","respondent":"小川健康課長","answer":"不妊治療の医療費の助成ですが、区独自に一般不妊治療の部分での助成をさせていただいているところです。思いのほか伸びている状況ではありますが、こちらにつきましてはしっかりとやっていきたいと考えています。","voiceIndex":129,"id":"exchange-056"},{"speaker":"沢田委員","kind":"質問","question":"品川区に若い子育て世代が増えていくというのは、品川区政にとっても大変重要だと思いますので、今後の特定不妊治療に対する区としての、厳しいかもしれないですけれども、助成等は考えられるんでしょうか。","respondent":"小川健康課長","answer":"国も努力をしておりますので、引き続きそういったことにつきましては、区としましても特別区課長会等を通じて働きかけていきたいと思います。あわせまして、区独自で特定不妊治療というのは考えてございません。一般につきましても、推移も見はからって考えていきます。","voiceIndex":131,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"成果報告書の１５１ページにあります資源持ち去り防止対策費と成果報告書の１４６ページのすくすく赤ちゃん訪問事業について、またお時間がございましたら、１５５ページのしながわの一番店発見プロジェクトについてお尋ねしていきたいと思います。資源持ち去り防止対策費ですが、どのような対策でしょうか。","respondent":"太田品川区清掃事務所長","answer":"２点目の平成２１年度と平成２２年度の額の違いですが、今申し上げた２人１組でやっていますパトロール隊、平成２１年度は１名非常勤職員を採用して実施をしてまいりましたけれども、やはりもう少しパトロールを強化する必要があるということで。","voiceIndex":134,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"２台で回っていらっしゃるということですけれども、警告書および指導件数が平成２１年度と平成２２年度を比べますと、自転車では約３倍、車両では約２倍、リヤカー、台車、バイクでは約３倍と指導件数が増えておりますけれども、その点をどのようにお考えかということと、町会やシルバーの方々のご協力等をお願いしてはと私は思いますが、それをどのようにお考えかとお伺いしたいです。","respondent":"太田品川区清掃事務所長","answer":"私も区民の方とお話をして、威嚇されたら警察へ電話をすることできませんかというようなお話もさせていただきましたけれども、やはり警察に電話した後に、通報した後に、やはり場所、住所等がわかったときの後の仕返しが怖いというようなこともありまして。","voiceIndex":138,"id":"exchange-059"},{"speaker":"吉田委員","kind":"意見","question":"そう言われちゃいますと先にちょっと進めないんですけどね。では、続きまして、すくすく赤ちゃん訪問事業についてお尋ねしていきます。どのような事業かということと何を目的にしていらっしゃるのか、お教えください。","respondent":"矢野品川保健センター所長","answer":"すくすく赤ちゃん訪問事業ですが、これは平成１９年度より従来この保健所で行ってまいりました新生児訪問指導に加えて、生後４カ月までのすべての乳児を対象に児童センターの職員あるいは民生・児童委員の方々のご協力をいただいて、全戸訪問を目指そうというものでございまして。","voiceIndex":140,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"全戸訪問ということですけれども、何％ぐらいできているかということと、虐待防止なんかのためでもあるんじゃないかなと思いますけれども、その辺の見解をお願いします。","respondent":"矢野品川保健センター所長","answer":"虐待防止のことに関しましては、区のこども家庭あんしんねっと協議会に心配な事例は上げて協力して対応しております。","voiceIndex":142,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"全戸訪問１００％にするのはなかなか難しいと思われますけれども、他区では突然訪問ということ、突撃訪問ですか、行っている区もあるそうですけれども、そのことをどのように思われるかということと、虐待の疑いが見られた場合の、そういうことが事例があったかということもお伺いしたいです。","respondent":"矢野品川保健センター所長","answer":"突撃訪問に関しては、なかなか難しいものですが、一応訪問してない家庭については、乳児健診が９６％ぐらいの受診率なので、そこで把握するようにはしておりますが、実際の家庭を訪問するということが大切ということで。","voiceIndex":144,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"１人で悩ませないためにも、それを目指して頑張っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-063"},{"speaker":"高橋委員","kind":"質問","question":"よろしくお願いします。歳入のときに少し触れたんですが、まず運営委託とそれから使用料収入との関係で、平成２０年度までと平成２１年度までとで大きく変わったんですが、運営委託料と利用料収入、その関係と、区が全体として幾ら支出することになり、運営主体の歳出歳入の利益というんでしょうか、その点と、あと区への還元。平成２２年でもそれは構わないんですけれども、すいません。","respondent":"小川健康課長","answer":"そういった関係で、平成２１年度に関しても還元金をいただきました。平成２２年度に関しても、さらに利用料金の収入のアップがありましたので、還元金が増えたというようなシステムになってあります。","voiceIndex":149,"id":"exchange-064"},{"speaker":"高橋委員","kind":"質問","question":"で、５,６００万円支出が減っているという形になるわけですね。そうすると、今お話あった何％還元というのは、これは大体１,５００万円を超えて１,０００万円ぐらいですので、２５％ぐらいですか、それぐらいの協定になっているんですが、それは事前に指定管理者と相談をして、決めて、それは毎年毎年変動するものなんでしょうか。","respondent":"小川健康課長","answer":"還元金のパーセンテージにつきましては、平成２２年度は２０％、平成２１年度も２０％でありました。年度ごとに協議をして、パーセンテージを決めていくというものです。","voiceIndex":151,"id":"exchange-065"},{"speaker":"高橋委員","kind":"質問","question":"利用する区民の方のサービスが向上できて、収入も増えたという形でいいんですが、前回歳入のときにお話をちょっとしたんですが、１回の利用料金が区外と区内の方が同一だということなんですが、ここの指定管理者である住友不動産エスフォルタでしょうか、ここはほかの自治体の委託も幾つかされているんでしょうか。そしてその使用料金の形態は品川区の委託と同じような形になっているんでしょうか。","respondent":"小川健康課長","answer":"こちらの住友不動産エスフォルタ・ＮＴＴファシリティーズ共同事業体ですが、他の自治体でも一部やっているということは伺っておりますが、具体的なやり方についてはこちらのほうは把握してはございません。","voiceIndex":153,"id":"exchange-066"},{"speaker":"高橋委員","kind":"質問","question":"とすると、ほかの自治体ではもしかしたら市以外は高くなっていて、市外とか区外の方が高くなっていて、市の方が安くなっている可能性もあるわけですよね。そういうことの情報を得ないでおいて、品川区は住友不動産エスフォルタと指定管理者の契約を結んだんでしょうか。","respondent":"小川健康課長","answer":"歳入のときにもご答弁申し上げましたとおり、指定管理者制度を導入する前の委託の方法でやっていたときからのワンコインという考え方がございまして、それに基づいて引き続きお気軽にワンコインということでやっているものです。","voiceIndex":155,"id":"exchange-067"},{"speaker":"高橋委員","kind":"質問","question":"ごめんなさい。話戻します。ですから、税外収入の確保の点から見て、前回別の課長がおっしゃったように、検討していくというお話ありましたけれども、そういった観点で、やはり何らかの違いを出すべきではないかと思いますが、それを踏まえて、健康センターの区外の方と区内の方の、５００円ということですかからどうかわかりませんが、それぞれの利用の人数の違いというのはおわかりになるでしょうか。","respondent":"小川健康課長","answer":"品川健康センターでは５００円、荏原では４００円ということでございまして、延べ利用数でいきますと、品川は年間６万５,１５０名、荏原では年間延べ２万４,６１８名の利用をいただいているところです。","voiceIndex":157,"id":"exchange-068"},{"speaker":"高橋委員","kind":"質問","question":"で、実は健康センターの会議室、ホールについては、区民の方以外の料金は高くなっているんです。それなのになぜこういう金額の差があるのかということなんですが、それでホームページには区民の方には割引料金にてご利用いただけますというふうに健康センターの会議室、ホールは書いてあるんですが、それとの関係はどのようになっているんでしょうか。","respondent":"小川健康課長","answer":"フリー利用料金のワンコインの考え方ですけれども、受付窓口等で区民か区民外かということをそれぞれ選別するということについてもなかなか難しい課題があろうかなというふうには考えてあります。","voiceIndex":159,"id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"国立感染症研究所感染症情報センターですか、このまとめによりますと、ＲＳウイルス感染症の小児科定点医療機関から全国約３,０００カ所の患者報告数が６月下旬から増加傾向が続いているという報告をもとに調査を開始したというふうにあるんですけれども、現状これはどのような状況で品川区は認識をしておりますでしょうか。","respondent":"伊津野保健予防課長","answer":"国の報告ならびに都の報告では、前年に比べましてかなり早い立ち上がりになっております。ただ、区内におきましては、それほど流行という感じでは今のところ至っていない段階であります。","voiceIndex":163,"id":"exchange-070"},{"speaker":"金野委員","kind":"質問","question":"区内ではそれほど流行の兆しはない。それほどということは、ごめんなさい、細かくて恐縮なんですが、数名発症しているということですね。流行はないけれども、多少発症があるということですか。","respondent":"伊津野保健予防課長","answer":"直近のデータで、区内、小児科定点８カ所ありますが、その中で３件の報告があります。","voiceIndex":165,"id":"exchange-071"},{"speaker":"金野委員","kind":"質問","question":"少ない数ではありますが、でも、冬場にやっぱり発生をする、流行するということが、今の時点でも発生をしているということなので、何らかの形で対応、対処していくことを考えていくことが大事かなと思うんですけれども、その点、このいわゆるＲＳウイルス、この症状、そして感染経路、こういったものをどのようにまず認識をされ、そしてこの対処法、あるいは予防法。","respondent":"伊津野保健予防課長","answer":"特に夜間の呼吸困難とかが起きた場合に、慌てずに救急車ですとか、そういうところできちんと対応してもらうようなことをふだんから気をつけていくぐらいしかないと思いますが、この流行状況につきましては、区としても、広報、ホームページとかを通じまして、広報に努めて。","voiceIndex":167,"id":"exchange-072"},{"speaker":"金野委員","kind":"質問","question":"それが見分けがつかない。こうしたことが非常にお母さんたちの中で、これはどうなんだろうというところで不安が募るのかなということもあると思うんですね。先ほどうちの会派からの阿久津委員からもありました。あわせて、マイコプラズマ肺炎というのも、何か報道によりますと、中学生の間で流行し始めているということですが、こちらのことに関してはいかがでしょうか。","respondent":"伊津野保健予防課長","answer":"東京都におきましても、直近のここ３週ほどで前年に比べてもかなり大きな流行となっておりますので、品川区としましても今後の流行を見守っていきたいと思います。","voiceIndex":169,"id":"exchange-073"},{"speaker":"金野委員","kind":"質問・要望","question":"こういうマイコプラズマ肺炎だとか、ＲＳウイルスだとかは本当に、そのほかさまざまなウイルスが飛び交って、本当にお母さんたちは、こういったことへの気苦労が絶えない、近年こういう状況でありますけれども、でも、正しい情報を皆さんが共有をし、そしてどういうふうに対処したらいいのかということが一番のお母さんたちのまず不安を少しでも取り除くというような対処になってくるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"がん検診なんですが、国のほうでは、１９８１年から死因の第１位ががんということで、またがんによる死亡者数も年々増加しているということで、平成１８年にがん対策基本法がつくられていますけれども、またそれに基づいて、国のほうでは平成１９年の６月にがん対策推進基本計画、またさらに東京都でもがん対策推進計画を策定して。","respondent":"小川健康課長","answer":"国や都の動きは委員ご指摘のとおりです。区としてそれに基づいて、例えば国が科学的に推奨するがん検診に関しましては確実に実施をしているです。","voiceIndex":173,"id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検診率のアップが課題だということなんですけれども、国も都もこの基本計画については５年間ということで、また５年が過ぎても継承して、それを継続発展させていくという、そういう方向でこれからも取り組まれていくんだろうと思うんですけれども、その東京都のこのがん対策推進計画の中では、市町村の役割というところで。","respondent":"小川健康課長","answer":"具体的な受診率の状況ですが、平成２２年度の胃がんについては３.８％、子宮頸がんにつきましては２４.８％、乳がんのマンモグラフィに特化しますが、２５.６％、肺がんについては５.８％、大腸がんについては２２％という状況です。","voiceIndex":175,"id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、５０％を国も都も目指しているわけですけれども、品川区もぜひ末端のところでやっぱり目標を決めて、そこのところをどういうふうに受診率を高めていくかということにしないと、東京都や国が幾ら５０％と決めても、それは本当に絵にかいたもちになってしまいますので、区としてもやっぱり目標を設定するということが必要なんじゃないかなと思うんですけれども、それで。","respondent":"小川健康課長","answer":"肺がん、胃がんにつきましては、現在、区におきましては、ともに両医師会のみの検診ということでございまして、こちらについては、同時受診ということはなかなか難しい状況ではありますが、こちらについては、医師会と今後話し合う中で。","voiceIndex":177,"id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つなんですけれども、前立腺がんなんですけれども、これは血液検査なので、特定健診とか後期高齢者の健診とあわせて項目を１つチェックするだけですぐにできるという検査なんですが、５００円かかるということで、じゃあ、いいよというふうに言う方が結構たくさんいらっしゃるということで医療機関からは聞いたんですが、そういう点では。","respondent":"小川健康課長","answer":"受けない方は、いくら低くても受けないし、受ける方は、どんなに高くても必要に応じて受けるということもありますので、特に前立腺がんを無料ということは今のところ考えてございません。","voiceIndex":179,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この子宮頸がんワクチンに関しては、平成２２年度から始まったと思うんですけれども、品川区は平成２２年度は中学１年から３年までということで、平成２３年度からは中学１年から、それと二十歳の方という方が対象になると思うんですが、高校生のお母さんからぜひ高校生も対象にして助成をしてほしいという要望をいただきまして、例えば渋谷区などでは中学１年から高校２年生までは３回とも全額無料で。","respondent":"伊津野保健予防課長","answer":"品川区では、昨年は中１から中３、さらに二十歳の年齢を押さえております。この二十歳の年齢を押さえることによって、現在高校生の方も二十歳になったときには受けられるという体制でやっていきたいと考えています。","voiceIndex":181,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは感染をする前に予防接種をするということに効果があると思いますので、そういう点で言えば、高校生のところが本当に必要な年齢だと思いますので、ぜひとも今後検討よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":183,"id":"exchange-080"},{"speaker":"大倉委員","kind":"質問","question":"なってきています。諸外国と比べてみても、非常に数としては多い。そういった中で、品川区でもこの１４年間で約１,０００人以上の方が自殺で亡くなっており、死亡原因の８位を占めるほどだということをお伺いしておりますが、その中でこの自殺予防講演会の開催があるのかなと思いますが、この事業内容と実績、どういうような告知方法で開催されたのか、お知らせください。","respondent":"福島荏原保健センター所長","answer":"それで、そこに書いてありますように、区民の皆様が８２名参加いただいたということです。そして、この前の９月１７日には鬱病対策の専門家である山口先生をお迎えをして講演会を開きました。そこで、１１２名の区民の方が参加していただいたということです。","voiceIndex":185,"id":"exchange-081"},{"speaker":"大倉委員","kind":"質問・要望","question":"私が知っているところで、区で自殺予防講演会のほかにも、ストレスチェックサービスというのをしていると伺いました。９月１日から始まっていると伺っております。","respondent":"福島荏原保健センター所長","answer":"９月の１カ月間で１万７,２２６件のアクセスがあったという報告を受けております。","voiceIndex":189,"id":"exchange-082"},{"speaker":"大倉委員","kind":"質問・要望","question":"大変に多いアクセス数だと思うんですが、今後こうしたストレスチェックなどを広めていくに当たってどのようにしていく必要があるのか、考えがあれば教えていただきたいと思います。","respondent":"福島荏原保健センター所長","answer":"高齢の方が多いのはもう日本全国ですが、特に品川についてはそういう若い世代の自殺が多いということで、我々としましては、そういう働き盛りの人々との連携、いわゆる産業部門との連携等が必要かと思って、来年度に向かって、いわゆる外部。","voiceIndex":191,"id":"exchange-083"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほども庁外、外部との連携が必要だということですが、あるところでは自殺予防対策として、個人の問題ではなく地域社会が取り組むべきだとして、自殺数を減らしている自治体、県もあるということにお伺いしておりますが、そうした中で、品川区で、そうした地域での見守り、ゲートキーパーというんでしたっけ、そういった制度を取り込んでいき。","respondent":"福島荏原保健センター所長","answer":"既に７月１５日には庁内の職員を対象にして実施してまいりました。今度の１１月には庁外、いわゆる地域の人、民生委員の人とかケアマネジャーとか、直接そういう方に働きかけて、ゲートキーパー研修を行っていく。","voiceIndex":193,"id":"exchange-084"},{"speaker":"大倉委員","kind":"質問","question":"最後に、自殺予防で、国では２０％削減目標が、平成２８年までで現在の２０％削減するという目標があると伺っておりますが、品川区でもそうした目標があるのか、お聞かせいただき、もう一度同じ質問になってしまいますが、それに向けてどういった取り組みをしていくのかをお聞かせください。","respondent":"福島荏原保健センター所長","answer":"それをするためには、我々は相談事業、それから、そういう鬱とか自殺をしようとなさっている方へのいわゆる支援というものが、周りの人の支援等が必要と考えて、それに向かっていろいろな施策をやっていくつもりでいます。","voiceIndex":195,"id":"exchange-085"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ、最初の目標は１９％と伺いましたが、ゼロを目指してこれからも頑張っていっていただきたいなと思います。次に移ります。この事業なんですが、この事業は１０分の１０、国から出ているかと思うんですが、ちょっと確認でそこを教えていただきたいのと、あとぜん息健康教室１６１人、水泳教室１１１人とありますが、これ、多分ぜん息のための水泳教室だと思うのですが、そこの辺をお聞かせください。","respondent":"小川健康課長","answer":"そちらから事業の内容に応じて、例えば医療費等ですとか、公害健康被害予防事業等、１０分の１０の補助が出ているものです。ぜん息健康教室、水泳教室ですが、こちらは公害健康被害の予防事業です。","voiceIndex":197,"id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと数的には少ないのかなと思うのですが、告知の方法と、あと箇所数、どこの水泳教室に通って、これを利用できるのかというのがわかれば教えていただきたいと思います。","respondent":"小川健康課長","answer":"水泳教室の場所は、荏原文化センターで、回数は全部で計６回で、参加者数は２７名で、延べ１１１人という状況です。ＰＲの仕方としましては、広報しながわを中心にＰＲをしておりまして、毎年多くの方に参加をしていただいているところです。","voiceIndex":199,"id":"exchange-087"},{"speaker":"大倉委員","kind":"意見","question":"そのために１１１人という少ない数なのかなというふうに思ったんですが、もう少し品川区として、荏原、大井、五反田とさまざまな水泳場があると思うんですが、そうしたところを利用しながらこうした予防政策をしていくお考えはあるのかな、１つお聞かせください。","respondent":"小川健康課長","answer":"こちらは会場を伊藤学園の温水プールとしておりますので、また、対象者については年齢が微妙に差がありますが、そういった意味では地域的にはバランスがとれていると考えておるところです。","voiceIndex":201,"id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は成果報告書１４６ページの食育推進事業、１４９ページのマイバッグ運動推進、この２点で伺います。それとあとケーブルテレビなどが有効な手段だと思われますが、どう活用されているのかをまず１点伺います。各事業を専門性を持った団体と協働で進められていると聞いています。そして、こういうふうに区民の団体と一緒に取り組むことでどのような効果が見られるのか、教えてください。","respondent":"小川健康課長","answer":"そのほかにも、材料購入ですとか、職員が実際にやるということを考えますと、やはりかなりいろいろな面で経費がかかるのではないかと。そういった面で、委託の中でかなり栄養士会に頑張っていただいているというふうに認識しています。","voiceIndex":204,"id":"exchange-089"},{"speaker":"渡辺委員","kind":"質問・要望","question":"食育のまさしく趣旨、目的が日常の中で生かされている視点を感じたものですから、伺ってみました。そういう中で、関心の高い食育に関して、私は信用ある情報、やはり区民の方が行政発信の情報というのは非常に求められていると思いますが、行政がやる意義、あるいは今後の展開、総論で伺えればと思います。","respondent":"小川健康課長","answer":"今後の展開ですが、毎年同じように綿々とやるということではなく、一緒に協働でやっております委託のほうとも話し合いながら、いろいろ工夫を重ねつつ、時代に応じた食育推進ということを進めていきたいと考えておるところです。","voiceIndex":206,"id":"exchange-090"},{"speaker":"渡辺委員","kind":"確認","question":"マイバッグ推進。この委員会等でも、各委員会でもいろいろな視点から取り上げられていると思いますが、もう一度ちょっと総論で伺いたいと思います。そして、今言った幾つかある中で、マイバッグというものが突出するのではなくて、そもそもマイバッグの総称であるこの事業全体の政策の目的、これをもう一度確認したいのと、対象はどうなのか、ここをお知らせください。","respondent":"野呂瀬環境課長","answer":"政策の目的といたしましては、区民と一緒になってマイバッグ運動という、この象徴的なレジ袋削減ということから、ごみの減量、資源の節約、ひいてはＣＯ２の削減にもつなげるということで取り組んできたものです。","voiceIndex":208,"id":"exchange-091"},{"speaker":"渡辺委員","kind":"質問","question":"そもそもの目的という中で、マイバッグというのは賛否あるかと思います。そういう中で、この取り組みというのは、もう平成１４年からですから、かなり長い期間、一定期間されてきて、行動が伴っているというのが１つポイントだと思います。やはり区民の方が単に意識するだけじゃなくて、行動すること。ここまでの目的達成に対する評価、そして今後はどういうふうに取り組んでいくのか、伺えればと思います。","respondent":"野呂瀬環境課長","answer":"あわせて、マイバッグ運動という名がありますけれども、当時空き缶の回収がなかなかなかったこともありまして、中身的には空き缶の回収とか、２年前まではマイはし運動とか、さまざまな取り組みを通じて、マイバッグ運動という名前はついておりますけれども。","voiceIndex":210,"id":"exchange-092"},{"speaker":"渡辺委員","kind":"確認","question":"当然いいんですね。かたく環境啓発だと言っても伝わらないですから、わかりやすさという点で、取り組んでいるものの具体例を挙げることは必要だと思います。ですから、この事業自体、全体は、事業規模の点からやはり今後も必要性が高いと思われますし、あとは方法は、いろんな工夫があるかと思いますので、その辺の展開のあり方と空き缶のところとはしのところを伺えればと思います。","respondent":"野呂瀬環境課長","answer":"今後の展開は、それをあわせまして、やはり区民と一緒になって環境に対する啓発というものはこれも必要ですので、行政評価を受けながら取り組んでまいりたいと思っているところです。","voiceIndex":212,"id":"exchange-093"},{"speaker":"浅野委員","kind":"質問","question":"先ほど他の委員から平成２２年度の各がん検診の受診率は伺ったので、ここでは質問はしませんが、こちらのもう一つの中で、がん対策基本計画、こちら、平成２３年度に５０％の目標ということで、こちらも５０％の目標を掲げているわけではないような、そういうような回答があって、非常に残念に思うわけですけれども、残念に思っていてもがんを撲滅することはできないわけで。","respondent":"小川健康課長","answer":"区として早期発見、早期治療に対しては、本当にとても重要なことだと考えておりまして、だからこそがん検診についてもしっかりとやっていくということで取り組んでいる次第です。","voiceIndex":215,"id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"さきの一般質問でも、大腸がん検診無料クーポン券の配布、この質問をさせていただきましたが、このようなやはり啓発ということも含めた施策をこれからも展開すべきであると思います。そして大腸がん検診にもピロリ菌検査も検討の対象に加えて、ぜひとも区民の命を守る、この取り組みをしていっていただければと思いますが、いかがでしょうか。","respondent":"小川健康課長","answer":"大腸がん検診につきまして、国のほうで、特に無料クーポン券ということで今年度から事業を進めたところですが、基本的に区の大腸がん検診、現在無料ということで、またここのところ受診率ががん検診の中でも大きくアップしているということも踏まえまして、今年度につきましては。","voiceIndex":217,"id":"exchange-095"},{"speaker":"浅野委員","kind":"質問・要望","question":"今ご答弁いただきましたけれども、大腸がん検診は平成２０年度、２０％前後だったと思いますが、平成２１年度で１回下がって、平成２２年度で上がっていると私は認識しております。次の質問に移ります。価格としては１,６８０万円かかっていますので、相当立派なものかと思いますので、どのような特筆すべき機能を持っているのか教えてください。","respondent":"野呂瀬環境課長","answer":"今のご質問です。月ごとに把握しておるところです。ただ、それが今までは各事業所ごとに届出は必要なかったものが、各事業所ごとに必要になったということで、区の施設、約２６０施設ぐらいありますけれども、その管理をするということで、経費がちょっと高くなったです。","voiceIndex":219,"id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"１,６８０万円、ぜひとも有効に使っていただきたいなと思いますが、地域推進計画、こちらは品川区全体の二酸化炭素の排出量を見ていくという計画でありますけれども、こちらのほうには何か対応するような内容が入っているのかどうかということを１つお伺いしたいのと、あと、実行計画の中で、平成２２年度の排出量の実績、まだ出てきてないんですが、大体例年ですと１２月ぐらいになっていると思います。","respondent":"野呂瀬環境課長","answer":"それと来年度につきましては、これは毎年１回ずつ、経済産業省とか環境省、あと東京都に提出する書類をつくるものでございまして、これについてはそれぞれの提出時期に合ったような形で提出していくと考えております。","voiceIndex":221,"id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"これは平成２２年度の排出量、ＣＯ２の排出量の電力排出係数は０.３８４を使うのか、それとも炭素クレジットを反映した０.３２４、どちらを使うのか、これを教えてください。そして、電力使用量、電力排出係数の件ですけれども、平成２２年度の報告は平成２１年度の電力排出係数を使うことになっておりますけれども、このような算出方法になっている件についても教えていただければと思います。","respondent":"野呂瀬環境課長","answer":"平成２１年度の実績ですが、区では、排出権取引などの複雑に加味した数値よりも実際に排出されるＣＯ２の量で表現するほうが明確で区民の方にわかりやすいと考え、実質排出係数を採用したものです。","voiceIndex":223,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"１４６ページの区民健康づくりプラン品川推進事業費に関連して、ちょっとこれは款別を越えるかもしれません。申しわけありません。次、もう一つは、１５４ページの中小企業対策費になるのか。今後ハローワークの設置をするというふうにお聞きしていますので、それについてお聞きいたします。今後どの目的でどの項目に入っていくのか。全くなく、新規というふうな考え方でやっていくのかについてお聞きします。","respondent":"小川健康課長、福島ものづくり・経営支援課長","answer":"区は区民健康づくりプラン品川というものを策定しています。その中の大きな柱としましては、１つには、地域での健康づくりを展開するということで、１３地区おります推進委員会の事業展開というものが１つあります。ハローワークの件ですけれども、確かに今ここには目的ですとかがございません。予算はございませんけれども、来年度につきましては、経済産業費には入るかと思いますけれども、どちらに入れるか、今後検討していきたいと思います。","voiceIndex":226,"id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"健康推進、まあ、わかります、健診もいろいろやっています。それから、健康の推進も、さまざまな区民の方に協力していただいてやっています。それはわかっているんですね。この２つをどういうふうにリンクをされているんですかということなんです。でいうならば、この業務内容というのはどの辺までカバーしたものが品川区で考えておられるのか、お聞きしたいと思います。","respondent":"榎本高齢者医療担当課長、福島ものづくり・経営支援課長","answer":"その指導のご案内の通知を差し上げた中で、約２割ほどの方が応募して、行いたいということで手を挙げられまして、その保健指導というものを行っております。一定程度の効果を上げているものです。ただ、企業側にとりましては、求人者に対する求人の取り次ぎ、そういったことも考えてありますし、また、４階に東京商工会議所品川支部等もありますので、そういった経済関係団体と連携した企業支援。","voiceIndex":229,"id":"exchange-100"},{"speaker":"西本委員","kind":"提案","question":"してほしいというふうな意見ですが、それに関してお聞きします。それからもう一つは、犯罪者に対する就労支援という形をぜひとも取り組んでいただきたいと考えています。品川区が安心・安全というふうになると、再犯を減らすということも絡めていくと、そういう特別な相談員というものを設置するというお考えを今後持っていただきたいという提案なんですけれども、それについてのお考えをお聞きいたします。","respondent":"榎本高齢者医療担当課長、福島ものづくり・経営支援課長","answer":"今後は、がん検診との協働で一緒に連携して進めていくというところも一層推進してやっていく所存ですので、医師会とも連携して、より一層区民の団体の方々と協力し合って事業を進めてまいりたいと考えています。ハローワークに関しましては、まずは区内の中小企業、産業振興ということで、こちらに持ってきますし、また、遠くなるということでいえば、求職者の利便性を図る、そういうところから始めていきたいと考えていますので。","voiceIndex":232,"id":"exchange-101"},{"speaker":"南委員","kind":"質問","question":"１４９ページの環境調査測定費にかかわって、放射線量の測定について、この１点で質問したいと思います。放射線の拡散で被曝の心配が子育て世代を中心に今すごく広がっていますよね。したがって、私はもっと測定箇所を増やすべきだ、こういうふうに思っているんですが、この認識、どういうふうに品川区としては考えておられるのか、まず伺いたいと思います。","respondent":"野呂瀬環境課長","answer":"どちらも空間線量基準は下回っておりまして、したがいまして、測定箇所を増やすようなことは今のところ考えてございません。","voiceIndex":236,"id":"exchange-102"},{"speaker":"南委員","kind":"質問","question":"今多くの科学者の方々がそういう立場を表明しているし、３月の時点で大量に放射性物質が拡散をした、そういうことで暫定基準というものを設けてはいるけれども、しかし、本当にそれ以下の被爆量なら安全というふうに言えるんでしょうか。その点をまずちょっと見解を伺いたいと思います。こういう原則に立たなきゃいけないと思っているんですけれども、そこについてもどういうふうに考えるか、伺います。","respondent":"野呂瀬環境課長","answer":"そうすると、結論からいいますと、年間１ミリシーベルトに対して今区内の放射線量は大体０.３ミリシーベルトというぐらいで、大体３割ぐらいの数値が出ているです。したがいまして、安心な数値でないかというふうに考えているところです。","voiceIndex":238,"id":"exchange-103"},{"speaker":"南委員","kind":"質問","question":"私は２５年前に起こったチェルノブイリ事故をやっぱりしっかりと学び直して、特に行政の方々には、そういう対策をとることが大事だと思うんですね。チェルノブイリ事故が発生して以降５年あたりから、５年経過するあたりからとりわけ甲状腺がんが子どもたちに発症してきた。１回引いたらなかなか治らない。ですから、閾値がない。こういうチェルノブイリの事故の実態をどのように検証しておられるんですか。","respondent":"野呂瀬環境課長","answer":"２５年前のチェルノブイリ事故に基づきまして、甲状腺がんが増加したというのは、当時すぐ避難勧告等がなかなか出されていなかったというふうに聞いています。ヨウ素１３１というものが甲状腺に広がるということで、初期対応ということが非常に重要であるです。","voiceIndex":242,"id":"exchange-104"},{"speaker":"南委員","kind":"質問","question":"私はやっぱりもっと区内の測定箇所を増やすべきだと思っているんですね。だから心配なんだということでね。こういう安心感を与えるのが行政の仕事じゃないんですか。とりわけ今マスコミでも言われているような雨どいの排水口のところだとか、滑り台の下だとか、そういうところも含めてしっかりやるべきだと思っていますけれども、それについていかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"一番大事なのは、定点において継続的に測定をするというのが一番大事で、この数値に大きな変化があったときにきちっと対応していくというのは行政として大切なことだということで今やっていることですので、この箇所を今の時点で。","voiceIndex":244,"id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"私は安全でない場所を知って、一刻も早く除染して危険を取り除く、こういうことをやることが行政の責任だと思うわけですね。昔からのどうのこうのって今長々と説明していただきましたけども、そういうことを区民に言うのではなくて、実際にはかって大丈夫なんだと、そこをきちんと検証して出すべきだと思うんです。ぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-106"},{"speaker":"山内委員","kind":"質問・要望","question":"１４３ページの感染症予防費。先ほどその委員から周知することで不安はあおるというような、少しそういったことも出ましたけれども、私は、今３件、この区内で発生をしているという報告があった中で、やっぱりしっかりと周知をしていただきたい。どういうものなのかといったことをしっかりと区民のそういった家族にしていただきたいという思いがいたしています。","respondent":"伊津野保健予防課長","answer":"そういう流れを受けまして、区としましても、特にことしはＲＳウイルスの立ち上がりが高いという情報もありますので、今後もＲＳウイルスについては周知を徹底していきたいと思います。","voiceIndex":248,"id":"exchange-107"},{"speaker":"山内委員","kind":"質問・要望","question":"そうしていただきたいです。それから、例えば広報しながわとか、そういったところにもこういったものが、感染が非常に危険ですよといったことを何か、何というんですかね、周知をするということも、もしできるのであれば、やっぱりそういったことでしていただければなと思います。ですから、もう一度なんですが、区としてどういった周知ができるのかということをお答えいただきたいと思います。","respondent":"伊津野保健予防課長","answer":"特に区として行っている事業としましては、乳幼児健診も行っておりますので、その際のＰＲというものを考えていきたいと思います。","voiceIndex":250,"id":"exchange-108"},{"speaker":"山内委員","kind":"質問","question":"よろしくお願いをいたします。伺いましたところ、週１で海外ビジネスの経験者、豊富な方から、海外に進出をしようという意欲のある会社にいろいろとアドバイスをしているというようなことで行われている事業と伺っていますけれども、その相談件数というんですか、週１やっているということなんですけれども、今そちらに参加されている企業とか、そういったもの、これが年々増えているのか。","respondent":"福島ものづくり・経営支援課長","answer":"支援講座などでは、同じ目的の、例えばタイの講座をやりますと、タイに進出したいという企業が集まってまいりますので、その企業間の交流ができたりだとか、そのような効果も上がっているというふうに考えてあります。","voiceIndex":252,"id":"exchange-109"},{"speaker":"山内委員","kind":"質問・要望","question":"そういった中で、今このビジネスサポートセンター、これは１社がそこに、何というんでしょうね、ビジネスを展開するまでの準備というか、そういった形でされている、その決算のあらましというか、そういったことでよろしいのでしょうか。それから、その１社といったものが、これはもちろん品川区の企業だと思うんですけれども、これがどのような形で契約をされているのかといったことを教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"中身につきましても、バンコクを中心にさまざまな現地の取引ですとか、あるいは実際に工場を建てたいですとか、そういう企業もございましたので、そこを足がかりにして現地視察をし、工場建設予定地を探しているというようなことを聞いてあります。","voiceIndex":254,"id":"exchange-110"},{"speaker":"山内委員","kind":"質問・要望","question":"今おっしゃったようなそういったことをアドバイスをするといったことで行われている。わかりました。私、前に本会議で質問させていただいたことがあろうかと思います。最後に、これはなかなか理解することが難しいのかなと。いや、違うんだよと。そういったことをどう払拭をしていいのか、私にはちょっとわからないんですよね。だから、その辺のアドバイスがあったら教えていただきたいんですけど。","respondent":"福島ものづくり・経営支援課長","answer":"そこが行われることによりまして、一企業が大きくなっていく、形態が大きくなっていくんだろうというふうに考えてあります。そうしたものの総体としまして、品川区の地域産業が貢献できる、地域の育成に貢献できるというふうに考えてあります。","voiceIndex":256,"id":"exchange-111"},{"speaker":"山内委員","kind":"質問","question":"今課長がおっしゃっていただいたようなことを私はもう少し、何といいますかね、雑に話をしちゃうからわからないと思うんですけど、でも、今聞いていると、すごくごもっともだと思うんです。それで、それを説明の仕方が悪いのかわからないんですけれども、なかなかそれが理解をしてもらえない方には、まあ、頭のかたいと言ったらいいんですかね、そういった方にはなかなかどうしても理解をしていただけない。","respondent":"福島ものづくり・経営支援課長","answer":"今回もタイに進出する企業６社がメタリックスで展示会を開きます。そこで実際の販路が見つかったですとか、あるいはタイに工場を持っていって、そこで事業拡大が行われただとか、そういった事例を１つでも増やしていきたいと考えています。","voiceIndex":258,"id":"exchange-112"},{"speaker":"山元委員","kind":"質問・要望","question":"私は１４２ページ、予防費の中の、１４３ページの子宮頸がんワクチン、同じく次のページの１４４ページの各種がん検診についてお伺いをさせていただきたいと思います。実際平成２２年度は中学校１、２、３年生と二十歳の方が対象。それに対して品川区はどのように対処して、またそういう受診する方に対してどのようなお知らせをしたのかも教えていただきたいと思います。","respondent":"伊津野保健予防課長","answer":"それを受けまして、３月８日に初回接種の差し控えと助成期間を６カ月延長するという通知を対象者に送付しております。８月になりましたら、大分在庫の状況もよくなりまして、接種者も増えている状況となっております。","voiceIndex":261,"id":"exchange-113"},{"speaker":"山元委員","kind":"質問・要望","question":"今お話があったように、６カ月間延長というお話がありました。実はこれはご存じのように、３回やらなければ効果がないわけですよね。実はあるご家庭ではお父さんの転勤で品川区を離れなければならない。そういう人たちに対して品川区としてはどのように対処というか、またどういうふうにしていこうかと思っていらっしゃるか、教えていただきたいと思います。","respondent":"伊津野保健予防課長","answer":"ただ、実施主体は区でありますので、区の住民の方に対して対象年齢の方に助成をするという形ですので、もし転勤されましたら、その自治体で同じような事業をやっていると思いますので、そちらで助成を受けるという形になると思います。","voiceIndex":263,"id":"exchange-114"},{"speaker":"山元委員","kind":"質問・要望","question":"確かに全部が全部やっていればいいんですけれども、１回８,０００円助成、品川区はしていただくわけですけれども、たまたまやってないところへ行ってしまった場合、１人が１万５,０００円とか２万円近く負担しなければならないということで、これは要望ではありますけれども、せっかくいい助成をしていただきましたので、何らかの形でその方たちに対して考えていただければと。","respondent":"小川健康課長","answer":"乳がん検診ですが、この平成２３年４月から一部検診内容が変更になりました。","voiceIndex":265,"id":"exchange-115"},{"speaker":"山元委員","kind":"質問・要望","question":"それから次に行きます。本当に子宮がんにしても、乳がんにしても、二十数％ということで、どんどん増えておりますけれども、今までいろんな努力なさったと思いますけれども、今まで周知方法というのはどのような周知方法、そして、それを考えるというか、いろんなお知らせですね、それはどなたたちが考えて送られているのか、その辺をちょっとお聞きさせていただきたいと思います。","respondent":"小川健康課長","answer":"ホームページ等がわかりづらいというご指摘につきましては、わかりやすい周知方法を今後も努めてまいりたいと考えています。","voiceIndex":267,"id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"実は若い子たちに子宮頸がんとか乳がんのお知らせ等が来ます。来ているのは知っていると言うんですね。でも、行かないという、そんな返事が来ました。目の視覚というか、来て、行きたくなるような、そういうものを考えていただきたい。もう１点、検診車ですが、例えば駅前にマンモグラフィの検診車ができればいいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-117"},{"speaker":"木村委員","kind":"質問","question":"１４８ページの温暖化対策事業、そして、時間がございましたら、１５０ページの街角花壇維持管理から質問いたします。は１４９ページの１行目の省エネルギー設備導入助成についてです。これはどのような事業なのか、簡単に教えてください。お願いします。","respondent":"野呂瀬環境課長","answer":"省エネルギー設備助成についてですが、これは家庭における温暖化対策ということで、平成２２年度から区民が個人の住宅に省エネルギー機器を導入する際の費用の一部を助成するものです。","voiceIndex":271,"id":"exchange-118"},{"speaker":"木村委員","kind":"質問","question":"むだなエネルギーを省き、効率のいい機種や商品、地球温暖化対策に対する助成だと思いますけれども、例えばＣＯ２冷媒ヒートポンプ、俗に言うエコキュートといいますか、またエコジョーズ、そしてエコウィル、それからエネファームという、合計４点の決算金額が８２６万円になっています。当初は、初めからこの８２６万円だったでしょうか。","respondent":"野呂瀬環境課長","answer":"当初の予算額は６９０万円です。","voiceIndex":273,"id":"exchange-119"},{"speaker":"木村委員","kind":"意見","question":"６９０万円ということで差し引きしますと、１３６万円ほどが足りなくなったと思いますけれども、これはどこから補てんをしましたか。そして、平成２３年度の予算が一気に１,３８０万円になりましたが、増えた理由とか、何が増えたのか、それも２つお答えください。","respondent":"野呂瀬環境課長","answer":"不足額の補てんについてですが、当初事業計画では定数を超えた場合は抽選という予定でございました。","voiceIndex":275,"id":"exchange-120"},{"speaker":"木村委員","kind":"意見","question":"この冬も相変わらずまた節電、節電ということを言われると思いますけれども、もちろん地球温暖化に歯どめをかけなければなりません。しかし、今は石油やガスよりも太陽光発電システムや太陽熱温水器、太陽ソーラーシステムのような自然エネルギー助成に重点を置くべきと考えますが、本区のお考えをお聞かせください。","respondent":"野呂瀬環境課長","answer":"区ではこれまで地球温暖化対策推進計画に基づきまして、太陽光発電システム等の導入促進に取り組んでまいりました。今後もますます自然エネルギーの重要性が増すと思われますので、引き続き充実を図ってまいりたい、このように考えているところです。","voiceIndex":277,"id":"exchange-121"},{"speaker":"木村委員","kind":"質問","question":"太陽光発電システムなんですけれども、平成２３年度の予算は１,０２０万円ということですが、今現在どのような執行状況であるのか。そして、太陽光発電システムは今後どのような伸びをするとお考えですか。そのことをお答えください。そして、本区として自然エネルギー、特に太陽エネルギーに対して今後どのように取り組むおつもりなのでしょうか。この３点をお聞かせください。","respondent":"野呂瀬環境課長","answer":"現在第２期分の受け付け中です。今後の伸びとしましては、１期分と同様、同程度のお申し込みがあると考えているところです。区の取り組みとしましては、今後も太陽エネルギーの活用について普及啓発に努めてまいりたい、このように考えているところです。","voiceIndex":279,"id":"exchange-122"},{"speaker":"木村委員","kind":"質問・要望","question":"そのことを踏まえまして、本区もお考えいただきたいと思います。これはまた要望としてお願いをいたします。街角というと、まちの片隅を何となく想像してしまいますけれども、実際はどのような場所に設置されている花壇なんでしょうか。それと、何となく小さくかわいらしい花壇のようですけれども、大きさはどのぐらいでしょうか。この２点をお答えください。","respondent":"藤田水とみどりの課長","answer":"ということで、本当にまちの角々にあるようなものです。それから大きさ的にも、大きいものは１０平米ほどありますけれども、小さいものについては１平米、２平米程度のものもあります。","voiceIndex":281,"id":"exchange-123"},{"speaker":"木村委員","kind":"質問","question":"それで年間に１カ所、大体１７万円弱ぐらいの経費がかかりますけれども、何にお金がそんなにかかっているのか。そしてまた、その場所代というのか、そういう地代といいますか、それは払っているでしょうか。そしてこの事業の目標というか、コンセプトというものは何でしょうか、お答えください。","respondent":"藤田水とみどりの課長","answer":"今１５％を超える緑被率がありますけれども、平成元年当時は、緑被率１０.９％と非常に低かったということもございまして、まちの少しの空間にもお花を植えていこうということでそもそも始めた事業です。","voiceIndex":283,"id":"exchange-124"},{"speaker":"木村委員","kind":"意見","question":"お話を聞いたところによりますと、一番大きな花壇で１６.７平米ぐらいですよね。一番小さいのが１平米。大体平均が３平米ということで、これからもっとこれを増やす計画はありますか。そして、これからも区の事業としてやっていくのでしょうけれども、将来的にはこの花壇をどのようにしたらいいか、したいか、お答えください。","respondent":"藤田水とみどりの課長","answer":"そういったような形で花植えをこれからも続けていきたいと考えています。街角花壇につきましても、この後ボランティアの人たちによる管理に移行していきたいと考えています。","voiceIndex":285,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"私は成果報告書１５４ページ、中小企業対策費の中で、またその融資あっせんと、それから海外進出推進費についてお聞きしたいと思います。区内の中小企業は、これにより救済される効果があらわれていると、品川区として支援を積極的に進めているわけですが、実際救済効果として、これは明確にあらわれているんでしょうか、お聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"少なかったというのは、対前年比少なくなっていたという、２３区の中の報道でございました。そのような形でも効果があったものと思います。それ以外にもさまざまな形でお金が回っているということで、経済波及効果は大きかったのではないかと考えています。","voiceIndex":289,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"返済猶予後の倒産件数は民間調査によると２０１１年１月から８月末までの合計は１年前の約２倍に増えている。そして今支援策の効果が減る傾向にあり、今後企業倒産の増加が予想されていると。こういうような記事が載っております。確かに品川区としてしっかり支援しているというのはわかるんですが、このことに対してきちっと把握しているんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"信用保証協会ですとか、あるいは信用金庫等に猶予するようにというお願いとか、そういうことも行っています。今後ですけれども、そういったことも予想されますので、さらに今後の経済状況をよく見ながら、来年度予算どうするか、よく検討していきたいと考えています。","voiceIndex":291,"id":"exchange-127"},{"speaker":"須貝委員","kind":"意見","question":"今、経済動向を見ながらというお話でしたが、実際この異常な円高、対ユーロ、対ドルに対しても、異常な円高の中で、国内の産業は空洞化の一途をたどっている。大手も堂々と、これから日本でやっている、世界全体でやっている４割から５割は海外で生産していかなきゃいけない。そうしなきゃ生き延びていけないということを発表している。","respondent":"福島ものづくり・経営支援課長","answer":"そういった事業も立ち上げまして、そこにつきましては好評なうち第１回目が終わりましたので、今後第２回目の商談に向けて今検討しています。","voiceIndex":293,"id":"exchange-128"},{"speaker":"須貝委員","kind":"意見","question":"でしたら、例えば、ワンフロア、どこか、もし買えたらですが、そういう建物の中で、ワンフロアの中で、同じ１階の中に工場、それぞれ経営者を集めて、特区申請というのは必要だと思うんですが、そうすると、電気代、光熱費、全部基本料金でいけるんじゃないかな。そうしたら、タイだけでやっているということも、私はおかしいかなと思うんですが、その辺についてちょっとご見解をお聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"そこについて、実際にすぐに支援するのかといいますと、確かに貴重な税金でもありますので、よく検討してからということで考えてあります。","voiceIndex":295,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり中小企業というのはお金がないです。人も人材も本当に足りないんです。その中で、その人たちと対面で、私は、しっかり聞いて、政策を考えていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-130"},{"speaker":"大西委員","kind":"質問","question":"各種がん検診のほうですけれども、これで一番発見される、この検診においてですけど、品川区でがんが発見される率が一番高いのはどういうがんになっているかということをお尋ねするのと、あと、狂犬病というのがありますけれども、この狂犬病というのは、日本では実際にこういう事故というんですか、そういう狂犬病でのものはあるのか、どうなのかというのをちょっとお尋ねします。","respondent":"小川健康課長、工藤生活衛生課長","answer":"平成２２年度の品川区におきますがん発見率ですが、一番高い発見率で前立腺がんの０.７２％、次に高いのが胃がんの０.２６％です。狂犬病につきましての日本についての発生等のお尋ねですけれども、日本ではいわゆる昭和３２年以来国内では狂犬病の発生はございません。","voiceIndex":299,"id":"exchange-131"},{"speaker":"大西委員","kind":"質問","question":"このがんが発見される確率がすごく少ないように感じるんですけどね。それと、狂犬病がほとんど発生しないのに狂犬病のことをずっとお金をとりながらやっていくということについてはどんな考え方をお持ちですか。","respondent":"小川健康課長、工藤生活衛生課長","answer":"がん発見率ですが、全国の基準値というものも設けてございまして、そちらと照らし合わせますと、区としましても若干増減はありますが、許容値の範囲内であったりとか、範囲より下回っているような状況でございまして。日本では、先ほど申し上げたように、昭和３２年以来発生してないわけですけれども、今でも世界で毎年５万人以上の人が亡くなっているというデータが報告されております。","voiceIndex":302,"id":"exchange-132"},{"speaker":"大西委員","kind":"質問","question":"今の狂犬病のほうからいくと、５０年日本では発生してないということですね、持ち込まれる以外は。よそでかかるということですね。それと、ここに咬傷犬被害件数というのが１５件ほどありますけれども、これは具体的にはどういう状態で、かみつかれたということだと思うんですけれども、これ、ちょっと具体的に教えていただけますか。","respondent":"工藤生活衛生課長","answer":"そうはいいましても、先ほど申し上げましたように、海外から帰国後に発症しているケースが昭和４５年に１名、平成１８年に２名発症されているという部分で、法律の中でやはりしっかりと対応をとらなければいけないというふうに。","voiceIndex":305,"id":"exchange-133"},{"speaker":"大西委員","kind":"質問","question":"ということは、かんだのはほとんど道端でかんだとか、そういうことじゃなしに、ドッグランか何かでそういう事件が発生しているということでいいんですか。","respondent":"工藤生活衛生課長","answer":"発生につきましては、ドッグランという報告はございませんで、いずれも公園、もしくは通常の道路の中での報告というふうになってあります。","voiceIndex":307,"id":"exchange-134"},{"speaker":"大西委員","kind":"質問","question":"そうすると、道路というのは、それは普通リードつけていると思うんですね。それと公園ということになった場合は、もしそれが区の中の公園ということになった場合には、どこかに責任問題が、場所において管理している側の責任もあろうかと思うんですけれども、その辺のところはどうですか。","respondent":"稲田道路公園課長","answer":"かみつかれた人とかみついた犬の持ち主というんですか、基本的には当事者同士の問題ということで考えております。","voiceIndex":309,"id":"exchange-135"},{"speaker":"大西委員","kind":"質問","question":"私が懸念するのは、区の管理している公園の中で、もしそういう表示がはっきりされてない状況の中でそういう事故が起こった場合に、区のほうに責任がかかるんじゃないかということを懸念しますが、その点はどうですか。","respondent":"稲田道路公園課長","answer":"私ども、基本的に公園は自由に使えるですので、区に責任があるというふうには考えておりません。","voiceIndex":311,"id":"exchange-136"},{"speaker":"本多委員","kind":"質問","question":"その一部事務組合から２３区への追加分というんでしょうか、平成２２年度中で見ても、平成２３年度で見ても、追加分というのがあったのか、教えてください。","respondent":"太田品川区清掃事務所長","answer":"この経費については、結論から申し上げますと、分担金の追加追徴ということはございません。既存の平成２２年度の清掃一組の清掃焼却施設管理費という項目の中で、既存経費の中で対応できたというふうに報告を受けているところです。","voiceIndex":314,"id":"exchange-137"},{"speaker":"本多委員","kind":"質問","question":"品川が停止をされてない。追加分がないということでお答えありがとうございました。それと、この原因ですね。水銀ごみの混入の原因を２３区の区長会にも一緒になって調査をしてほしいんだという要請があったかと思うんですが、その状況と会議の状況と調査がどのように進んだのか教えてください。","respondent":"太田品川区清掃事務所長","answer":"７月の千歳工場、それから杉並工場で、やはり水銀ごみが原因となる炉の停止のときには、炉が停止してから１週間以内に不適正防止検討委員会を開催をし、原因究明をし、それから同時に各区、都でやはり同様にホームページで広報を、啓発をやったです。","voiceIndex":316,"id":"exchange-138"},{"speaker":"本多委員","kind":"質問","question":"ただ、世田谷区の千歳では、残念ながら再発してしまって、再発防止をいろいろと試みても再発が起きている状況ですので、さらにこの原因を追及する方法がないものか、お尋ねしたいと思うんです。例えばごみを出す側の、まあ、特定はできなくても、絞り込みというのができていけないものなんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"大変ごみ量が多い中で、原因究明していくということで、大変難しい部分がありますけれども、今後については、やはり啓発を中心にしながら、都、それから特別区、清掃一組が連携をしながら対応していくことが求められていると考えているところです。","voiceIndex":318,"id":"exchange-139"},{"speaker":"本多委員","kind":"質問・要望","question":"さらに引き続きご努力をお願いしたいと思うんですが、ちょっとドイツの事例を１つ挙げしますと、ドイツで水銀を純粋に電化製品、まあ、電化製品、日本だと家電リサイクルでちょっと取り扱いが別なんですが、ドイツで水銀が含まれているもののごみに対しては、純粋に水銀を取り出しますよという受け皿がありますので、出すほうの受け皿もいろいろ考えていただきたいと思います。次の質問に移ります。","respondent":"矢野品川保健センター所長","answer":"私からは健康学習で若年層の部分の対応についてお答えします。委員ご指摘のように、出張型健康学習の中で、大学生、中学生、小学生などに必要な健康教育をしておりますが、もちろん学校保健の中でかなりされているという前提で行っております。","voiceIndex":320,"id":"exchange-140"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、いろいろと健康の、体力のことも含めてみますと、以前は健康優良児というものがありましたけれども、これはかなり前ですか、個人表彰は昭和５３年に廃止、学校単位では平成８年に廃止というふうになっておりますが、ただ、それぞれ学校で申請などあれば、歯の表彰があったり、いろいろ健康についての、子どもに対してもあると思うんですけれども。","respondent":"小川健康課長","answer":"お尋ねの健康優良児というような視点からの表彰というものは今行ってはございませんが、保健センターを中心に若年層の方々への健康づくりのアプローチもしていますし、健康センターという立派な施設もあることから。","voiceIndex":322,"id":"exchange-141"},{"speaker":"本多委員","kind":"質問","question":"すみません。ほかの質問に移ります。最後１点だけ聞きたいのがありまして、１４５ページの環境衛生費の公衆便所と産業経済費の中で、コンビニエンスストアというのが区内に約２００ぐらいあると思うんですが、私のちょっと認識なので、違っていたら、ちょっと誤差があるかもしれませんが、その関連で、非常時、平常時、提携ができないか、ちょっとお答えいただければと思います。","respondent":"稲田道路公園課長","answer":"現在公衆便所３８カ所、公園便所、児童遊園便所が１２３カ所、全部で１６１カ所ありますが、今後そういうコンビニ等、要望もございまして、検討に入りたいというふうには考えております。","voiceIndex":324,"id":"exchange-142"},{"speaker":"武内委員","kind":"質問","question":"１４７ページの不妊治療相談・助成事業ですね。それで１点、一昨年の決算特別委員会でもちょっとお聞きしたんですが、トータルで、わかる範囲で結構ですので、これまでこの助成事業、また相談を行って、妊娠されたという方の件数、おととし伺ったときには９９件というお答えいただいたんですが、その後現状でどれくらいになっているか教えてください。","respondent":"小川健康課長","answer":"平成２１年度で妊娠に至った数が９２件、平成２２年度では９９件です。","voiceIndex":327,"id":"exchange-143"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、累計で平成２２年度現在で９９件ということなんでしょうか。平成２１年の１０月６日の決算特別委員会で伺ったときに９９件というふうに伺ったんですけれども、その以降は、そうすると、妊娠された方はいないと、こういうことなんでしょうかね。","respondent":"小川健康課長","answer":"平成２０年度が純粋に９７件でございました。累計をいたしまして合計で平成２２年度末で２８８件の妊娠に至ったです。","voiceIndex":329,"id":"exchange-144"},{"speaker":"武内委員","kind":"提案","question":"直接これが出産にその後無事に結びつくかどうかはまた別だと思うんですが、せっかく非常にすばらしいことなので、そういう件数を載せていただいたらどうかなというご提案して、いろいろありますけど、検討しますという当時お答えいただいたんですけど、また改めてそういう形はどうかなと思うんですけど、いかがでしょうか。","respondent":"小川健康課長","answer":"こちらの件数なんですけれども、毎年度基本的に３月末までの申請ということで、年度ごとにお支払いをしております関係で、申請時に治療中の方も当然いらっしゃいます。","voiceIndex":331,"id":"exchange-145"},{"speaker":"武内委員","kind":"質問・要望","question":"まあ、おっしゃる趣旨は何となくわかります。要望しておきます。それで、また実はちょっとそれに関連しまして、こういう形でせっかくすばらしい区の事業で、妊娠に至った。すばらしいと思うんですね。年間毎年３万人から４万人、全国では１４０万人の患者がいると推計されていますということなんですね。これについての区の認識、もしくは見解を教えていただきたいと思います。","respondent":"矢野品川保健センター所長","answer":"個別の相談には丁寧にきめ細かく対応を心がけていきたいと考えております。","voiceIndex":333,"id":"exchange-146"},{"speaker":"武内委員","kind":"質問・要望","question":"やはりこれだけ全国で１４０万人ぐらいいらっしゃるんじゃないかと言われている中で、品川区でそれを何人いるかというのはわかりませんけども、非常に高い確率で、せっかく妊娠しても残念ながら流産を繰り返してしまう方っていらっしゃる。そういうところもご紹介できるんじゃないかと思うので、もう１回、この周知について、しっかりと取り組んでいただきたいと思いますけど、いかがでしょうか。","respondent":"矢野品川保健センター所長","answer":"今年度も女性の健康週間で取り上げする予定ですが、不育症については、もう少しそこに行き着く、アクセスがしやすいように検討してまいりたいと思います。","voiceIndex":335,"id":"exchange-147"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひよろしくお願いします。それで、この間の定例会のときにそれとあわせまして助成制度創設を求めました。今予定しているところも複数あるという中で、また相談体制も今専門の相談窓口を設けているところが全国で１０カ所超えていると。まだまだ低いわけですけれども、そうしたことも今後検討していただきたいと思うんですけど、その辺のご見解を教えてください。","respondent":"矢野品川保健センター所長","answer":"助成につきましては、不育症の原因がさまざまですし、検査や治療方法について今後の進展を注視しながら、また国の施策の動向を踏まえながら検討してまいりたいと考えております。","voiceIndex":337,"id":"exchange-148"},{"speaker":"武内委員","kind":"質問・要望","question":"国のほうでも、国会で我が党のほうからも、保険適用をとにかくやってくれということで、２年ぐらい前から求めていますけれども、なかなかちょっと進んでいかない状況もありまして、そういう中で自治体でやっているという状況がありますので、今、残念ながら２３区ではまだどこもやってないんですけれども、もう不妊治療も始め。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":339,"id":"exchange-149"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は成果報告書の１４２ページの保健衛生総務費と、それからその次の予防費、それと１４５ページの保健指導費についてお伺いしたいと思います。第１に、休日・応急診療費、成果報告書の１４２ページですが、これは１億１,９４０万円支出されております。現在は主に日曜日以外は、昭和大学病院の中央棟の４階の小児科ブースで診療が行われております。休日診療７２日間で、延べ受診者数が１万１,６３５人。","respondent":"小川健康課長","answer":"医師会、歯科医師会等とご協力をいただいて、休日や土日夜間等の対応をさせていただいているところでございまして、受診者数につきましても、ここのところほぼ横ばい傾向ということで、やはり医療不安に対してはそれなりの効果があると考えているところです。","voiceIndex":341,"id":"exchange-150"},{"speaker":"鈴木（博）委員","kind":"提案","question":"それで、先ほど阿久津委員のほうから電話相談なんかをうまく使ったらどうかというご提案もあったんですが、それもまた非常によい考えではないかと私も思いますが、さらに軽症な患者さんの受診の抑制ということに関しまして、保健センターで行っている子育て安心事業、子育て安心教室とか、子育て学習、あるいはすくすく赤ちゃん訪問事業、それとあと、款をまたいでしまうんですが。","respondent":"矢野品川保健センター所長","answer":"出張健康学習という形で、乳児期前期母親学級の後の自主グループなどで医療機関のかかり方などのお話をしております。今後そのようなパンフレット等の作成も検討してまいりたいとは思っております。","voiceIndex":343,"id":"exchange-151"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そして次に、１４２ページ、同じページの成果報告書の予防接種費についてお尋ねいたします。これは無料で接種できるので、基本的には勧奨だけということで、このうちの麻疹については後ほど改めてお伺いしたいと思います。このうち子宮頸がんワクチンに関しては、東京都子宮頸がん等ワクチン接種緊急促進事業の対象になりまして、７２１万円が支出されておりますので、これは別に後ほど改めて質問します。","respondent":"伊津野保健予防課長","answer":"ただ、現在のところ、２月から４月生まれのお子さん、８１６名に４月から７月にかけましてお知らせを発送しまして、そのうち４３７名の方が接種されております。今後また接種者も増えることとは思いますが、暫定的な受診率としましては５３.５％となっております。","voiceIndex":345,"id":"exchange-152"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"したがって、今後一層の啓発が必要だと考えられますので、これは要望ですが、さらに一層の取り組みをよろしくお願いいたします。経済的な格差なくすべてのお子様が確実にワクチンの接種ができるワクチンの無料化と、それから十分な保障のもとで行える定期接種化の実現のためにさらに強い働きかけが必要だと思いますが、区のご見解をお伺いしたいと思います。","respondent":"伊津野保健予防課長","answer":"この３種類のワクチンにつきましては、国の検討会でも定期化に向けまして進めているところでありますので、いましばらくこれについては様子を見ることが必要かと思います。","voiceIndex":347,"id":"exchange-153"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"それと次に参ります。昨秋から公費補助が始まったサーバリックスは、補助が始まった途端にワクチンの不足によって停止に追い込まれてしまいました。実際ワクチンは足りないわ、２つのちょっと性格が違うワクチンが出るわで、現場は非常に混乱しているんですが、この安定供給と、それからサーバリックス、ガーダシルのその使い分けに関しては、区の見解をちょっとお伺いしたいと思うんです。","respondent":"伊津野保健予防課長","answer":"ガーダシルというのは、良性の尖圭コンジローマに効くと言われております６、１１のタイプにそれが追加になっておりますので、そういう面では確かに混乱しやすいのかもしれませんが、本来の目的であります子宮頸がんの予防という面では、全く同じと考えておりますので。","voiceIndex":349,"id":"exchange-154"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"不慮の事故が非常に多いんですが、それが品川区は幸いなことにゼロになっているわけですが、子育て安心事業でも、健診でも、育児相談でも、私が見たところ、事故に対する項目がないんですが、乳児の事故というのは死に至らなくても、いろいろトラブル、私の診療所でも誤嚥だとか、けがをしたとか、随分来ますので、非常に事故対策というのは大切なことだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":351,"id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは１４４ページの成人歯科健診と１５４ページの中小企業活性化・住宅リフォーム助成事業についてお聞きしたいと思います。成人歯科健診ですけれども、この事務事業概要のほうを見ても、平成２０年、平成２１年、平成２２年と受診者数が広がっていない、伸びていないなというのがあるんですけれども、こういった結果を受けて、区のほうで広げていく対策などはおとりでしょうか。","respondent":"小川健康課長","answer":"歯科医師会とも相談しつつ、今年度成人歯科健診の案内のご通知を少し見やすく工夫をいたしました。そういった工夫をして、受診者の対象者には直接通知が行くようなシステムになってありますので、そちらのまた成果を来年度見てみたいと考えているところです。","voiceIndex":353,"id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"ので、この健診のお知らせが歯科にかかるきっかけになっているんだなというのは少なからずも実感してきました。事務事業概要のほうの歯科衛生士の活動というところで、この表に挙がって、いろいろ指導が、歯科指導などされているんですけれども、これを受ける、大体見ていますと、乳幼児や妊産婦、また高齢者あたりが中心に行われている指導状況なのかなと思うんですけれども、そこら辺はどうでしょうか。","respondent":"矢野品川保健センター所長","answer":"生活習慣病と歯周病という関係も最近は関心を持たれていまして、こういう部分でも健康教育、健康づくり推進委員の講演会などでは、高齢者だけじゃなくて、そういう部分でも健康教育を実施しております。","voiceIndex":355,"id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、やはり前にもほかの委員から質問ありましたけれども、２０代、３０代から健診、そしてきっかけをつくっていく。どうしても生活費のほうが大事だと。なかなか歯にはお金がかけられないんだというふうに、歯が後回しになってくる状況ですので、２０代、３０代、若い世代からきっかけづくりを始めていくという、ここはいかがでしょうか。","respondent":"小川健康課長","answer":"成人歯科健康診査につきましては、現在４０歳から７０歳までの５歳刻みということで、ご指摘の歯周病予防のための対策が特に必要な年代に絞って事業を実施させていただいているところです。","voiceIndex":357,"id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"対象年齢を広げていくというところでは、検討していないということですけれども、歯科でもやはり受診率を高めていくということで、健診に来ただけでも健診だけで済ませずに、ちゃんと口腔内を画面に写して見せるようにしたりとか、本当は治療が必要だよということを本人に動機づけとして工夫されているところもあるので、ぜひ歯周疾患。","respondent":"柏原住宅担当課長","answer":"今年度から実施しております住宅改善工事助成事業の実績です。直近の１０月６日現在です。申請件数２３件、助成額については４００万円を超えたところです。それから、対象の工事金額につきましては２,５００万円ほどです。","voiceIndex":359,"id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"申請件数のところで、エコのところのＬＥＤ設置工事は、２３件の中で何件でしょうか。","respondent":"柏原住宅担当課長","answer":"ＬＥＤの工事助成につきましては、現在までのところ、個人住宅、マンション管理組合等々含めまして、９件です。","voiceIndex":361,"id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問","question":"この昨年の住宅リフォーム助成制度でも、一般質問で答弁もあったんですが、助成額、約７０７万円、総事業費が２億５,０００万円、申請件数が１０８件と、３６.２倍もの効果があったと、経済効果があったというふうに評価しているということも答弁いただいているんですけれども、大分ここには、昨年の件数には満たないであろう今回の制度ですけれども、昨年とことしの要綱を見せていただいたんですけれども。","respondent":"柏原住宅担当課長","answer":"それにあわせまして、環境保全であるとか、バリアフリー化等々による住環境の整備、こういった目的を持っていまして、大きな２つの柱で始めたというものです。","voiceIndex":363,"id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問","question":"なのに、現場の声を聞いても、逆戻りしたというふうな声のほうが聞かれます。そういうもとでも、なぜ対象を狭めたのか。エコとバリアフリーというのも大事なんですけれども、昨年のリフォーム助成制度は、それに伴った工事、リフォーム工事、一般リフォームも含むというような形で行われていたためにこれだけの申請件数や実績になったと思うんですけれども、これ、なぜ狭めてしまったのか、お聞かせください。","respondent":"柏原住宅担当課長","answer":"こちらのほう、例えばバリアフリー化とか、環境対策、住宅リフォーム助成のほうにも入っておったんですけれども、件数が多いものを特に中心にということで、こちらの住宅改善工事助成事業に入れておりますので。","voiceIndex":365,"id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問","question":"あくまで目的は変わっていないということなんですけれども、じゃあ、なぜこんなに伸びていないのか。やはり昨年は緊急経済対策として始められたこの住宅リフォーム助成制度、建設業の実態はいまだ厳しい状況が続いているということも一般質問では答弁されています。そういう状況なのに、なぜ増えていないのか。どうして一般リフォームにまで伸ばせないのかということをお聞かせください。","respondent":"柏原住宅担当課長","answer":"繰り返しの答弁になってありますけれども、我々としては、狭めたという認識は持ってございませんで、必要な部分に対して必要な助成をやっていこうという考えに立ってあります。","voiceIndex":367,"id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区のほうの見解とやはり現場の声は全く違うものになっているんですね。すごく減っているんだと。もう全く泣かず飛ばすの状態にまた戻ってしまったという悲しい声が聞かれるんですね。ですので、やはり一般リフォームまで広げて、狭めてないと言うんですけれども、現場の声はもう狭まったと。ですので、やはり見直しと復活を進めていっていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":369,"id":"exchange-164"},{"speaker":"井上委員","kind":"質問","question":"１点目に健康センター事業費のことについて、健康センターの指定管理委託が利用収入制をとっていて、そのために使用料が収入に反映されていないということですが、予算書では利用料金収入見込額を示していますけれども、決算書ではなぜこういったものを示さないのか、お考えを伺います。","respondent":"小川健康課長","answer":"先ほどの利用料金収入見込というのは、先ほどもご答弁した１億５,４５０万円ちょっとの金額のことだと考えていますが、こちらについては、予算書の段階では利用料収入を見込んでマイナスというような形で予算書の記載をさせていただいたところだと思いますけれども。","voiceIndex":371,"id":"exchange-165"},{"speaker":"井上委員","kind":"質問・要望","question":"決算書への表記は予算書同様にすべきであると思います。行政側はそれは必要ないと言うかもしれませんけれども、そういった意味では、きちんと委託料の評価もこれでできるような仕組みが必要だと思いますので、来年度以降、そういった表記も検討していただきたいと思いますが、そういった考えがあるのか、お伺いをいたします。その理由を教えてください。","respondent":"榎本企画財政課長、小川健康課長","answer":"今の利用料金の収入の関係ですけれども、指定管理者の施設全体に関わることなので、その辺、どういうふうに一番表記したらいいかということを検討していきたいと思います。ところが、実際に契約等を行う段階になりまして、こちらの運営の委託ではなく、随意契約でやる契約がふさわしいという判断に至りまして、決算の中では事業委託等の中に組み込まれたということで。","voiceIndex":373,"id":"exchange-166"},{"speaker":"井上委員","kind":"質問・要望","question":"事業委託といえば、事業に対する委託というふうにこの決算書を私たちは読みますので、予算当初の考え方のほうが適切だというふうに思いますので、やはりそういったところは今後正確に表記をしていただきたいというふうに、予算書、決算書を見てわかるような、そういったところを工夫をしていただきたいとお願いをしていきたいと思います。","respondent":"小川健康課長、久保田行財政改革担当課長","answer":"私の部分ではあくまでも健康課、保健センター関係ということで、数のとり方につきましては、私のほうで把握しているのは１０個程度というふうに考えてあります。そうしたものすべてを健康づくりの数としてというのはちょっと、私どもでも数を数えて把握はしてございませんけども、それぞれの目的に応じた形で健康づくりについて目指して取り組んでいるです。","voiceIndex":376,"id":"exchange-167"},{"speaker":"井上委員","kind":"質問","question":"この計画はもう８年がたちます。これ、計画年度は１０年間を基本計画とし、品川区長期基本計画改定、あるいは区民の健康意識等、社会情勢の変化に応じてこの計画の内容を変更する必要が生じたときには見直しますとありますけれども、改定に向けたスケジュールをお伺いいたします。","respondent":"小川健康課長","answer":"ご指摘の区民健康づくりプラン品川ですが、こちらをつくるに当たって、多額の経費を用いたかなり完成度の高い計画だと認識しています。今のところ、特に改定するという予定はございません。","voiceIndex":379,"id":"exchange-168"},{"speaker":"井上委員","kind":"質問","question":"スポーツにかかわる健康増進、この長期基本計画の中では、スポーツが地域の活性化づくりというふうなとらえ方をしていますけれども、これはスポーツは健康づくりにほからならないと考えていますので、やっぱりそういうことも含めて、この計画については、お金をかけて十分なものというよりも、社会情勢に合っているのかということを踏まえて、やはり見直しをすることが適正ではないかと思いますが。","respondent":"小川健康課長","answer":"基本的な計画の体系については現行のままで特に問題はないと思ってありますが、個別の施策につきましては、やはりいろいろな部分で部をまたがっての調整ですとか、そういったことについては取り組んでまいりたいと考えています。","voiceIndex":381,"id":"exchange-169"},{"speaker":"井上委員","kind":"質問・要望","question":"横断的な検討をしていただきたいと思います。次に、こころの健康づくりなんですけれども、予算、決算で７７万円ほど差異がありますが、これはどういった要因なのかということと、２０１１年の予算では、２０１０年度よりも２００万円ほどの増額がされています。どんなところに力を入れようとした予算編成だったのか、お伺いいたします。","respondent":"福島荏原保健センター所長","answer":"この健康づくりの事業の大半を占めているのが一般賃金、医師、心理相談員への賃金費用としているのが一番多いと思われます。来年度の予算に対して増えているのは、さらに講演会等の講師の問題とか、それから、いろいろな物品を配る、その費用とかが入っていると思われます。","voiceIndex":383,"id":"exchange-170"},{"speaker":"井上委員","kind":"質問","question":"それで、児童思春期の心の健康相談が５０件から７５件というふうに増えておりますけれども、件数なのでこれは延べであろうというふうに推測をしますが、その中でどういった相談が多いのか、差し支えのない範囲でお伺いしたい。それから、相談者の本人と家族の割合がどういった状況か。相談を受ける方の資格と人数、１人当たりの相談時間がどのくらいあるのか、お伺いします。","respondent":"福島荏原保健センター所長","answer":"１人当たりの相談の時間としては、いろいろ多々あるので、一概には言えない状況だと思われます。","voiceIndex":385,"id":"exchange-171"},{"speaker":"井上委員","kind":"質問","question":"一生のうちに何らかの精神の障害を経験する割合は４人に１人というふうにも言われている中で、特別なそういった病ではないということを若いうちから知っていただくということが必要だと思っています。そういったことを踏まえると、思春期の心の相談事業の充実と学校教育の精神疾患についての正しく学ぶ機会が必要と思いますが、区の認識を伺います。","respondent":"福島荏原保健センター所長、冠木指導課長","answer":"我々としましては、そういう講演会、それから家族勉強会等を通じて、広く皆さんに周知していきたいと考えておりますし、現に今では我々としてできる範囲でやっておるつもりでいます。学校におきましても、保健の時間であるとか、市民課の時間で心の健康について学習しています。","voiceIndex":387,"id":"exchange-172"},{"speaker":"若林委員","kind":"質問・要望","question":"４点です。１４９ページの環境調査測定のほうです。それから、１５３ページの観光アクションプラン。これはなぜかといいますと、その理由はまた後にしましょう。それから、実施をされた後の、そういった評価をもとに、区はその商店街に、そこで補助金がスパーンと終わる、２年、３年で終わるわけですから、その後のフォローというのはどういうふうにされているのか、この点についてお聞きしたいと思います。","respondent":"野呂瀬環境課長、稲田道路公園課長","answer":"今、公園につきましては、公園の砂場、いわゆる子どもたちが遊ぶ場所ということで、砂場につきましては、今、サンプリングをして、週１回調査をしています。参考までに、今現在危険な数値等は出ておりません。そこでの放射能の件で販売をというような話なんですが、集めて腐葉土化して売られているという、ふれあいの事業でやっているですので、その辺の数値等の検証等はふれあいでやっていただいて、安全かどうか。","voiceIndex":391,"id":"exchange-173"},{"speaker":"若林委員","kind":"質問","question":"じゃあ、商品券だけになりますかね。現状、ことし平成２３年度も３億円、３億円、計６億円を出されておりまして、今この使い方は、いわゆる商店街、各商店の中ではこの５００円券が各個店に行っているわけですけれども、こういう統計というのはどういうふうにされているんでしょうか。やらない前後はこういうふうになったとかという、そういう比較調査、検討というのはされているんでしょうか。","respondent":"米田商業・観光課長","answer":"大型店の関係につきましては、また別の関係でのコラボレーションができるのではないかと、このように考えているところです。","voiceIndex":397,"id":"exchange-174"},{"speaker":"須藤委員","kind":"質問","question":"１４６ページ、きょうもいろいろ健康のことで出ていますので、健体康心と言っている私からも１つお願いがあるんですけれども、健康づくり、いろいろやっているけれども、この最終的な区民への考え方というのはどういうことでしょうか。というのは、元気で生活をしたい。","respondent":"小川健康課長","answer":"健康に対するご質問ですが、区としましては、できるだけ区民の方に要介護状態を予防し、寝たきりや認知症にならない状態で自立できる期間、いわゆる健康寿命の延伸を図っていくことが大きな課題であると考えておりまして。","voiceIndex":400,"id":"exchange-175"},{"speaker":"須藤委員","kind":"質問","question":"健康というのは、ともすれば、区民、いわゆる死亡の３大原因というのはがんである、心疾患である、あるいは脳血管であるとかという、そういう体の面から来る疾患に対しての対処というのがよく言われてくるんだけども、そのことに対してはどういうふうにお考えでしょうか。そのことに対してというのは、心の持ち方ということに対してはどういうふうに思っているのか、お聞かせください。","respondent":"福島荏原保健センター所長","answer":"心の健康も、これはもうＷＨＯの規約にありますように、心身ともに健康であるということが必要だと考えています。","voiceIndex":402,"id":"exchange-176"},{"speaker":"須藤委員","kind":"質問","question":"心疾患が１７.３％で、２３区平均が１５.６％ですから、１.７ポイント高い。ということは、老衰というのは、天寿を全うしたという、僕らはそういうふうな思いでいるんだけれども、そういった生き方が２３区の中で品川区が一番低いですよというような数字が、平成２３年３月の統計では出てきているんだけども、このことについてはどういうふうにお考えでしょうか。","respondent":"小川健康課長","answer":"そうした数字につきましては区としても課題があると考えています。","voiceIndex":404,"id":"exchange-177"},{"speaker":"須藤委員","kind":"質問・要望","question":"こういう高齢化社会になってきているときに、やはり在宅医療ということが今度も基本になってくるよというのが国のほうでも出ていますけれども、そういったときにこのかかりつけ医というものの仕組みをしっかりしておかないと、在宅医療との連携というのはなかなか難しいと思うんだけども、このあたりの応対件数８２６件というものはどういうことなのかというのと同時に、その進捗状況がどうなのか。","respondent":"伊津野保健予防課長、小川健康課長","answer":"難病の数ですが、平成２０年、２１年、２２年にかけまして、総数としましては２,６２２、２,６７６、２,９３２と、徐々に増加している傾向にあります。この件数につきましては、微減傾向にはありますが、引き続き医師会等と協力し、しっかりやっていきたいと考えています。","voiceIndex":406,"id":"exchange-178"},{"speaker":"須藤委員","kind":"質問・要望","question":"若いころは、３０代のときは一線会という名前でちょうどよかったんだけれども、そういう会自体がうんと高齢化しちゃっているというようなところになってきているのが、どこの商店街でもそういうものがあろうかと思うんだけども、そのあたりを小規模商店街だけでなくて、やはり全体の商店街の振興というものについてどういうふうにお考えになっているか、お聞かせください。","respondent":"米田商業・観光課長","answer":"そういった意味におきまして、次世代、次を担う若い世代が商店街の中に入ってくる。息子さん、娘さん等もいらっしゃるかもしれませんが、外部から入ってくる。あるいは、そういうような仕組みをつくっていくことが重要だろうと考えています。","voiceIndex":409,"id":"exchange-179"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区の商店街、非常に活性化しているというので、商店街の人たちも全国から逆に注目されて、全国行って、品川の仕組みはこうですよというようなお話をする勉強会に呼ばれたりというようなことがあろうかと思うので、そういった意味で、品川区の商店街が活性化することが、いつも区長が言っているように、区民がだんだん高齢化してきて、近所で買い物できるという仕組みがなければ。","respondent":"米田商業・観光課長","answer":"そういった方々をまたいかにご支援できるかというようなことについて、区も、またそういう方々、あるいは区商連等とも話し合いを重ねながら、今後の方策、検討してまいりたいと考えています。","voiceIndex":411,"id":"exchange-180"},{"speaker":"須藤委員","kind":"質問・要望","question":"産業のほうと一緒で、商店街のほうも品川区にある大学、あるいは高校、そういったところと連携をして、いろんな事業を立ち上げたり、あるいはまた地方の商業というか、いろんな産業が品川区の商店街と連携をしてというような話もいろいろ聞いています。そういった意味で、お互いが伸びていくような仕組みを上手にこれからもしていっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":413,"id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":117036,"voices":414}},{"id":"h23-20111012-4","meetingId":"h23-c-settlement","date":"2011年10月12日","dateIso":"2011-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２２年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"１６６ページの建築確認事務、それから１５７ページの駅周辺等放置自転車対策費、１６５ページの避難道路機能強化事業についてお伺いします。民間の建築確認の事業者と区の審査との違いはどうなっているのか。例えば、日数は今、大して変わらないと以前もお話がありましたけれども、日数が実際どれぐらい違って、費用の差はどれぐらいあるのかということをお伺いさせていただきたいと思います。","respondent":"中村建築課長","answer":"約２.７日の差があります。それと料金ですけれども、こちらは区の確認申請料が一番今安いという認識でおります。民間の確認検査機関は、その倍あるいは３倍近く設定されているところもあります。こういったことにつきまして、どう考えているかということ……。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"確認","question":"日数はほとんど民間と二、三日程度の違いということで、また費用は逆に２倍、３倍という大変差がある中で、区への確認申請は減っていて、一方で相談件数だけは増えているというのは、そういういろんな事情があると思うんですが、ちょっと疑問なところがあるんですけども、よく前から言われていますけれども、民間の検査機関の中には、マンションの建築主が株主だったり。","respondent":"山崎マスタープラン担当課長","answer":"ハード系の指導ということに加えまして、居住後のコミュニケーションを確保するというような、引っ越しをされてきた方が柔軟に住民の方と一定の良好なコミュニケーション、町会の加入でありますとか、先ほど申し上げた区としましては。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"建築確認のこういった申請の減少によって、区にいる専門の職員の方たちがいらっしゃると思うんですけれども、そういった方たちの技術的なレベルの低下というか、建築確認申請が減っていることによる低下というのもあるのかなと思うんですけども、こういったことについては、どういった対応、人数は結構いらっしゃるかもしれないんですが、そういった対応はどうされているのでしょうか。","respondent":"中村建築課長","answer":"今、相談件数が大分増えているという現象がございまして、建築基準法の中で、判断に苦慮する非常に難しいケースがたくさんあります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"あわせて、大変これは歩道にあって、結構そんなに広い歩道じゃないので、歩行者の安全対策ということもどうされているのかなというのが気になっていたのと、あと阪急の駐輪場と何か混乱されている方がいらして、そういうこともあったので、そういったことに対する対策はどのようになっているのかというのをお伺いさせていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"しかしながら、事故の可能性が全くないということではございませんので、区のほうで委託しております指導啓発要員などを配置するほか、あと阪急のと混同しないように看板を設置して、ここは阪急の駐輪場ではないということを明確にするような措置をとっているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"あそこはすごく人通りも多くて安全対策という意味で歩道も狭いので、ぜひ進めていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"現在も停電してしまった場合、一切非常電源のようなものをメーカーのほうで備えていないものばかりしかないということなので、この辺がネックとなっておりますので、この辺の問題がクリアされてから、機械の成熟を待ってから検討ということになると思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"１６５ページの避難道路機能強化事業、滝王子の避難道路の強化についてなんですけれども、何度かお伺いしているんですが、平成２１年から平成３０年までの事業期間ということで、７.３ｍの道を１０ｍということですけれども、改めてこの事業の意味と、実際に対象の物件や建物は何軒あるのかということをお伺いしたいんですけれども、お願いいたします。","respondent":"品川防災整備担当課長","answer":"現在平成２１年から事業を始めまして、平成３０年までということですが、拡幅に必要な棟数ですが、１３５棟となっております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"１３５棟ということで、この３年間で３件の物件の買収ですけども、あと８年間でどれだけできるのかなというのはすごい疑問なので、やるからにはちゃんとやっていただきたいと思うんですけど、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鶴委員","kind":"確認","question":"私のほうからは、成果報告書１６３ページの公園・児童遊園維持管理費、それから１６７ページの区営住宅管理費についてお尋ねをいたします。公園・児童遊園維持管理費について、確認ですが、公園、児童遊園また防災活動広場の現在数を教えてください。成果報告書の記載の数字と事務事業概要の数字は、タイムラグの関係かと思いますけれども、数字が違いますのでよろしくお願いいたします。","respondent":"稲田道路公園課長","answer":"現在の品川区の公園、児童遊園、防災活動広場等々の数です。公園は、現在１４２カ所、それから児童遊園が６７カ所です。それから、防災活動広場、水辺広場、開放広場とひとくくりになっておりますが、３６カ所です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鶴委員","kind":"確認","question":"かつて震災直後に問い合わせしたときに、結構、防災活動広場とか、要するに所管が違ったりして、教えていただいた数字が違ったということがかつてありましたので、改めて今確認をさせていただきました。それで、今ご報告いただいたうち電源引込盤、いわゆるイベント等で電源供給が可能なイベントコンセント、それが設置されている箇所は何カ所ぐらいありますでしょうか。","respondent":"稲田道路公園課長","answer":"私どもの公園の中で、外部でコンセントに差して電気が利用できるという公園ですが、４公園あります。しながわ中央公園、戸越公園、戸越公園はステージ周りですね。それから東品川海上公園、鮫洲運動公園の４カ所です。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"４カ所ということで報告をいただきました。そこで、提案ですけれども、先ほどご答弁いただいた４カ所以外、未整備の箇所、相当数になると思いますが、防災上の観点もあわせて、順次こうしたイベント時にもお使いいただけるように電源引込盤、イベントコンセントを整備されてはいかがでしょうか。既設の箇所で、これまでに地域のイベントなどで電源を利用された公園などがあれば、教えてください。","respondent":"稲田道路公園課長","answer":"一方で、仮設電源というのを引くというふうになりますと、１万円程度の引込料金に設備代等で六、七万円ではないかというふうに思われておりますが、地域の方の利用しやすい公園ということを目指しておりますので、今後ちょっとこの辺も研究していきたいなと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"今ご答弁いただいたようにランニングコストがそれぞれかかる面もありますけれども、要望の多い地域については、積極的な検討をお願いしたいと思います。次に、区営住宅管理費についてお尋ねをいたします。最初に、区営住宅１３団地、１６棟のうち、エレベータが設置されている棟を教えてください。こうした設置に当たっては、何か基準みたいなものがあるんでしょうか、教えてください。","respondent":"柏原住宅担当課長","answer":"こちらのほう、エレベータの設置ですが、品川区としましては、内規ではありますけれども、４階建て以上の建物で、それから設置をした際に法令等に違反をしない、それから、いろいろな施設が合同で入っているようなところには。","voiceIndex":26,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"西中延区営住宅の住民の方のお話によると、今現在入居している４７世帯のうち、８割近い方が６５歳以上の高齢者であるというふうに聞いております。こうした現状を受けて、この西中延区営住宅へのエレベータの設置について、平成２１年度の予算特別委員会における公明党の議員の質問に対して、容積率との関係で設置は難しい。","respondent":"柏原住宅担当課長","answer":"西中延の区営住宅のエレベータの件です。我々もこちらのほうの住宅は高齢者が多くなっているというのは認識しています。そういったところから、エレベータの設置については、さまざまな角度から検討してまいりました。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鶴委員","kind":"質問","question":"平成２３年度には、新規事業として区営住宅の長寿命化計画の策定に向けた住宅の現況調査等のための予算が計上され、執行されていると伺っております。平成２４年度には耐震補強改修工事が予定されていることも伺っております。そこでお尋ねいたしますが、西中延区営住宅に耐震補強改修工事をした場合、概算で結構ですので経費はどのくらいになるか教えてください。","respondent":"柏原住宅担当課長","answer":"まだ設計半ばですので、正確な数字というのは、なかなか申し上げづらいんですが、現在やっております例えば二葉一丁目であるとか、それから荏原七丁目等々の耐震化工事から申しますと、１億円から２億円以上はかかるんではないかというふうに考えてあります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"その上でお尋ねいたします。公営住宅法第３５条、ここには「地方公共団体は、公営住宅の整備を促進し、又は公営住宅の居住環境を整備するため必要があるときは、公営住宅建替事業を施行するように努めなければならない」とあります。西中延区営住宅は、この第３６条第２号でうたわれている耐用年数の２分の１を超えているか教えてください。","respondent":"柏原住宅担当課長","answer":"公営住宅法上、そのような規定になっており、委員ご指摘のとおりです。こちらのほうは、築年次が昭和４１年度ですので、一般的に申しますと、そういった時期に入っているというふうに考えられると思います。","voiceIndex":32,"id":"exchange-014"},{"speaker":"鶴委員","kind":"質問","question":"ということは、区営住宅の長寿命化計画とか、また先ほどお尋ねいたしました耐震補強改修工事、こうした関係で見ても、仮に建て替えをした場合の費用対効果、また耐用年数に関して、もちろんこの入居者の理解というのが前提であるというふうに考えますけれども、建て替えをしたほうがメリットが大きいのではないかなと思います。","respondent":"柏原住宅担当課長","answer":"建て替えというお話になりますと、居住者の方がいらっしゃいますので、こちらのほうの仮住まいであるとかというところも出てくると思います。工事期間につきましては、都営住宅の例を見ますと、２年近くはかかるんではないかというふうに考えてあります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問・要望","question":"時間がないので最後に要望ですけれども、先日特別養護老人ホームを含めた検討がございました。既存の建物の機能もしっかりと活かしていただきながら、複合施設も検討していただきたい、このように思いますので、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"１５９ページの涼のみち整備事業、そして１５７ページの交通安全啓発費、１６１ページの河川管理費の浄化対策についてご質問いたします。最初に、１５９ページの下から３行目の涼のみち整備事業についての質問です。涼のみち整備事業に、３,２３２万５,０６４円とありますが、この事業とはどういうことなんでしょうか、ご説明ください。","respondent":"稲田道路公園課長","answer":"品川区では、道路の保水性舗装、遮熱性舗装という種類の舗装をつくりまして、昼間の気温の上昇の抑制効果がある舗装を導入しまして、道路の温度を下げて、涼しさを感じる涼のみち整備事業として取り組んでいるものです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問","question":"この名のとおり涼のみちですから、道路の表面の温度を特殊な塗料を塗ることによって道路の表面温度を下げる事業ということがよくわかります。このやり方は１種類だけなんでしょうか、それとも何種類かあるのか。そして、その効果のほどを教えていただきます。お願いします。","respondent":"稲田道路公園課長","answer":"こちらの効果なんですが、遮熱性舗装、塗料を塗るほうはマイナス１１.７度の低減効果があったというふうに私どもの実験では効果を確認しております。保水性舗装におきましても、マイナス７.１度というような結果を得ております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"私たち大人は道路から離れているので、大分背丈がありますので何とかなるんですけれども、小さな子どもたちは大変路面に近いものですから５０度近い熱を感じているはずだと思います。水まきには、おふろの水でも十分だということで、残り湯の水で十分ということですけれども、水まきをする時間帯、これは午前がいいのか、それとも午後がいいのか、大体何時ごろがいいのかわかりましたら教えてください。","respondent":"稲田道路公園課長","answer":"１平米当たりの単価ということでお知らせしたいと思います。遮熱性舗装ですが、これは塗料を塗りますのに１平米１万２,０００円程度です。","voiceIndex":42,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"この事業は、平成１７年度から調査をし、平成１８年度から正式に事業化したわけですが、年間にどれぐらいの道路の舗装を実施するお考えですか。それには何か問題点や何らかの理由があるのでしょうか。都道は東京都がやるということ、そして区道は本区がやるということですが、区道をすべて終わらせるにはどれぐらいの年数がかかるか教えていただけたらうれしいです。","respondent":"稲田道路公園課長","answer":"平成２３年度は遮熱性舗装、塗料を塗るほうのみですが、西小山駅前広場、ロータリーのところを７３９m2既に実施しております。ということで、価格の違いなんですが、これは商店街等の保水性舗装を今年はちょっとやっていないというところで差が出てあります。","voiceIndex":44,"id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"真夏時には道路だけではなく、今度はビルや建物自体が熱を持ってきます。日中に建物の壁に照りつけた熱というんですかね、その熱が時間をかけてじわりじわりと内側に熱が伝わるということで、部屋の温度が夜でも日中と変わらないぐらいになるです。熱中症を防ぐためにも、建物の壁にそういう特殊塗装をする。現在そのような事例がこの品川区にはありますか。お願いします。","respondent":"中村建築課長","answer":"外壁の仕上げにつきましては、確認申請のときに仕様がそこに書かれておりますけれども、特に遮熱性能そのものが審査の基準になっておりませんので、現状では把握はしておりません。","voiceIndex":46,"id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"続きまして、先日歳入で質問いたしましたけれども、今度は１５７ページ、中段の少し下ですが、交通安全啓発費と駅周辺等放置自転車対策について質問いたします。普及啓発経費の主な使われ方についてご説明を願います。","respondent":"藤木交通安全担当課長","answer":"高齢者や自転車の交通安全教室の開催ですとか、あと広報関係では、広報紙の作成、また交通安全に関する資機材の購入ですとか、広報啓発看板の設置にかかる費用等です。","voiceIndex":48,"id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"ただいまのご説明の中に高齢者の交通安全教室とありましたが、具体的にはどのようなことを行っているのか、そしてその効果のほどはいかがですか。本区で年間高齢者が事故に遭う、また巻き込まれる件数や人数、また特別な例としては、死に至ってしまうケースなどもあると思いますけれども、おわかりになりましたらお願いいたします。","respondent":"藤木交通安全担当課長","answer":"参考までに、昨年の交通事故につきましては、全体で１,３０６件、平成２２年中に交通事故が発生しているんですが、そのうち高齢者の方が絡んだのが３５２件という統計が出ております。","voiceIndex":50,"id":"exchange-023"},{"speaker":"木村委員","kind":"質問・要望","question":"講習だけではなく自分で体験をしてもらうということ、これは交通安全に効果的だと思います。ぜひそのように進めていただきたいと思います。次に交通安全協会補助金４９０万円とありますが、交通安全協会とはどのような団体で、どのような活動をしているのか、わかっているようでなかなかよくわからないところがありますので、ご説明をいただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"交通安全協会についてですが、こちらの団体は地域の住民ですとか、地域の企業からなります任意の団体でございまして、法人格等はございません。ボランティアの団体です。おおむね警察署単位で設置されておりまして、品川、大崎、大井、荏原各警察署に交通安全協会があります。","voiceIndex":52,"id":"exchange-024"},{"speaker":"木村委員","kind":"質問","question":"時間が余りないので、今度は１６１ページの浄化対策、河川費についてです。我が区には２本の河川、立会川と目黒川がありますが、汚れた工業用水や家庭から出る汚水によって川自体が汚れがちになっていますが、現在の川の状況はいかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"しかしながら、まだまだ品川区内の河川の中には余り好ましくないにおいがしたり、あるいは白く濁ったりということで、まだまだそういうような状況もありますので、今後も河川の浄化対策については進めていく必要があるというふうに感じてあります。","voiceIndex":54,"id":"exchange-025"},{"speaker":"木村委員","kind":"質問","question":"私も二十数年前に立会川の近くに住んでいたんですが、きれいな川というよりは、水かさの少ない川というイメージでした。何年になるんでしょうか、一時ボラの大群が川いっぱいに来たことがありましたけれども、当時のテレビのニュースなどで取り上げられました。あの現象はどうして起こったのでしょうか。あれ以来、何かそういうような変わった出来事というのはありますか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"立会川のほうですけれども、平成７年だったと思うんですけれども、立会川のほうにはＪＲの東京駅等から水を引っ張ってきて、今そこの地下水を流しています。補足します。立会川だけではありませんで、東京湾の中小河川みんなに上ってきたんですね。","voiceIndex":56,"id":"exchange-026"},{"speaker":"木村委員","kind":"質問","question":"魚の勘違いなのか、自然現象ですね。どうも失礼をいたしました。これから作業をやるわけですけれども、一度の浄化作業で大体どれぐらいの期間もつのか。そして、１６１ページの下から４番、５番目ぐらいに水質改善実験費というのがありますが、浄化以外に何を実験しているのか、わかりやすく教えてください。","respondent":"藤田水とみどりの課長","answer":"その下の水質改善調査費ということで掲載していますのは、その実験で出てきたデータ、これをもとに机の上でいろいろデータの分析をするということで、平成２２年度については行ったものです。","voiceIndex":59,"id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"わかりました。先日台風１５号がもたらした雨量、これは立会川の警戒水域を超える警報が出された。水域を超えるというのか、警報が出されましたけれども、大きな被害には至りませんでしたが、最近の雨は広範囲に降るんではなくて、集中的に降る傾向があるというお話を聞きました。そのような傾向を実際に感じられますか。","respondent":"藤田水とみどりの課長","answer":"河川の状況を見ていますと、例えば立会川の現地で確認をしていると、実際にそこでは雨が降っていない、しかしながら、河川の水位が上昇してくるということで、上流のほうで雨が降るとその水が河川に流れ込んできて水位が上昇するという現象がやはり見られますので。","voiceIndex":61,"id":"exchange-028"},{"speaker":"木村委員","kind":"意見","question":"友人に立会川のそばに住んでいる人がいるんですけれども、その方から川からではなくて、川に注ぐ下水道から悪臭がするということを言われました。下水道の能力と川との関係、もし、もう時間がありませんね。ということで、終わりにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"成果報告書１６４ページの市街地整備事業費より、再開発事業について伺いたいと思います。区役所近くの一本橋の開発も次々とビルが高くなっておりますけれども、区内各地でこうした大型公共事業が進んでおります。伺いたいことは、平成２２年度末までに完成した地区、総住宅戸数、オフィスビルについて業務系のビルが何平米か、税金による補助支援が幾らか、それぞれ合計を伺いたいと思います。","respondent":"三宅都市開発課長","answer":"補助支援の額としましては、約５３０億円です。それから、今後の見込みですけれども、都市計画決定を経まして、計画中あるいは工事中のもの、現在４地区ございまして、そこでは約２,２００戸の住宅と約２７万m2の業務系の床を整備する予定です。","voiceIndex":65,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"西品川一丁目地区ですけれども、先日のアセスメントの資料を私も見させていただきましたが、そこでは住宅が４６０戸、業務系の床が２１万８,０００m2でした。伺いたいのは、こうした計画を一体いつまで続けるのか、どこまで続けるのか、今後の計画を伺いたいと思います。","respondent":"三宅都市開発課長","answer":"もう少し広く見ますと、再開発事業というのは、市街地整備基本方針で定めます都市活性化拠点や、地域生活拠点を中心に進められておりますけれども、これらの拠点はその周囲から多くの人々が集まる場所でございまして、それぞれの地域の牽引役。","voiceIndex":67,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"続く限りはこれからも進めていきたいと、そういうご説明だと思います。再開発マンションだけでもあわせると６,１６０戸、これは八潮の住宅戸数を大きく上回る、そういう状態です。業務系ビルだけでも１０８万m2、ざっと見たら東京ドームの２.３倍でした。ぜひここを伺いたいのと、そう考える理由もあわせてご説明いただきたいと思います。","respondent":"三宅都市開発課長","answer":"再開発事業につきましては、先ほどの答弁と少し重複しますけれども、やはり道路など、公開空地など、そうした整備を進めるものであるということと、市街地整備基本方針に基づいて、各地区の拠点となるような地域の整備の促進を図ることによって品川区の活性化を図っていくと。","voiceIndex":69,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"どうして再開発マンションばかりができるのかと、大体税金が使われる意味がわからない、そうした声をたくさん伺います。直近の品川区の世論調査を見ても、再開発による地域整備はわずかに４％です。これ以上の高層ビル、マンションはやめてほしい、これが率直な区民の思いだと思いますけれども、なぜ望んでもいない事業を進めるのか、逆にこれがなぜ望んでいると区は考えるのか、そこを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"基本的には市街地整備基本方針で位置づけております、その拠点というエリアを中心に進めていきたいと考えておりますので、低層住宅市街地などで、そのど真ん中で高層住宅ですとか、そういうオフィスビルを建てるというような考えは持ってございません。","voiceIndex":71,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"区民が望んでいるのかと伺うと、一生懸命必要性を説明するわけです。しかし、必要だというのであれば、では、どういう行政需要の見通しを持っているのか、そこを伺いたいと思います。品川区はこの行政需要が一体どこにあると考えているのか伺いたい。そして、このマンション建設やオフィスビル建設について、行政需要のピークというのは、一体いつだと考えているのか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"住宅やオフィスのニーズに関するお尋ねです。基本的に市街地整備基本方針で定めてあります都市活性化拠点など、交通の利便性の高い場所においては、社会情勢が変動いたしましても、特性によりまして、その住宅ですとかオフィスのニーズは基本的に高いと考えています。","voiceIndex":73,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"今日的に考えると、東日本大震災が起きました。こうした傾向については加味しないということなのか、行政需要にどういう影響を与えると考えているのか伺いたいと思います。結局は、どういう行政需要かはっきりしないのに、具体化しているのは計画だけ、これでは公共事業となぜ呼べるのか、そこにどうして税金を入れるのか、私はとても区民が望んでいないということだと思いますけれども、いかがでしょうか。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"今回の大震災では、超高層住宅自体の安全性に問題はありませんでしたけれども、居住性の面で改善の余地があるとは考えてあります。それぞれの地域の特性を踏まえて、それぞれのまちづくりの更新をしていくというのは当然の話だと考えています。","voiceIndex":75,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"まちが新陳代謝をするということはそのとおりだと思います。じゃあ、何で大きいビルになるのかと。しかも品川区民はそれを望んでいるのかと。私は望んでいないと思います。先ほど子育て世代の定住化というお話がありましたが、ならば、これまでにつくった３,５００戸の住宅、２,６００戸の住宅、これが完売する見通しがあると思っているのか最後に伺いたいと思います。","respondent":"三宅都市開発課長","answer":"多少時間はかかりましても、完売すると考えております。","voiceIndex":78,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"１５７ページ、交通安全啓発と駅周辺等放置自転車対策、１５８ページの補助２０５号線整備についてお伺いをします。交通安全のほうでお伺いしますが、交通安全担当課長は、警視庁から派遣をしていただいておりますが、改めて警視庁ではどんな仕事を担当していたか、具体的に教えてください。","respondent":"藤木交通安全担当課長","answer":"私はここの前は新宿警察署の交通課長をやっておりまして、その前は警視庁の交通部で主に自転車の交通安全対策などを担当しておりました。","voiceIndex":81,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"ものすごくモチベーション高く品川区に来て、品川区の自転車対策、安全も含めてやっていこうという熱き思いで品川区に来られたというふうに私は思っております。品川区内の自転車のマナーなんですけれども、余りいいとは言われていないんですが、その辺の苦労がどういうふうにあったかということを伺います。","respondent":"藤木交通安全担当課長","answer":"警視庁のときにも自転車のサイクリング協会ですとか、そういうところと一緒に安全教室をやりましたけど、そういう自転車の専門家みたいな人たち、そういう対策なんかも必要ではないかと考えております。","voiceIndex":83,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"そこで、改めてお伺いするんですけれども、そういう思いで課長は品川区に来たと思うんですね。自転車はいいですよという協会じゃないですか。そういう思いで品川区に来たら、品川区の基本方針を聞いて、ちょっと驚いちゃったと思うんですけれども、その辺についてはいかがでしょうか。","respondent":"藤木交通安全担当課長","answer":"委員おっしゃっている品川区の基本というのは、不要不急の場合の自転車の利用は自粛をしなさいと、このようなことだという認識の上で発言しますが、区内におきましては、特に狭い道路などが非常に多いと、また自転車、歩行者が交錯して、交通量が非常に多いということで。","voiceIndex":85,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"現実はそこなんですよね。駅の放置自転車対策とか安全対策とかを一生懸命やる。やっぱり、ここの基本的な、品川区は自転車を乗るのをやめましょうという基本的なところを変えないと、私はちょっと時代に合っていないんじゃないかと思うんですけれども、この辺については、担当課長、政策的には部長だと思うんですけれども、この辺で変えていかないといけないという思いがあるんですけど、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"自転車で行かなきゃいけないところは自転車を利用してもらうしか仕方がないんですけども、でもそのときは、きちっと道路交通法の車両に当たりますから、交通ルールをきちっと守っていただいて、安全に利用していただきたいというのが品川区の基本の考え方です。","voiceIndex":87,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"これはやりますが、一般の区民の方は、そういう説明ではわからないと思いますよ、やっぱり自転車は楽だから。次は補助２０５号線整備に行きますけれども、私はこれを何年もずっと追い続けていますが、例の私の近所の信号の件でお伺いしますが、今の状況をお知らせください。","respondent":"武藤都市整備下水道課長","answer":"補助２０５号線の交差点の信号機設置の改良のお尋ねですけれども、委員ご指摘のとおり、当該交差点につきましては現在信号がなく、自動車と歩行者、また自転車等の交通が入り乱れる形で危険な状態というふうには認識しております。","voiceIndex":89,"id":"exchange-041"},{"speaker":"藤原委員","kind":"意見","question":"毎回答弁が所轄の警察に上げているというんですけれども、もっと区でできる具体的な案というのがあると思うんですよ。警察に上げるだけじゃなくて、設計の問題とか、その辺については、区としてどういうふうに考えていますか。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり、所管の交通管理者との調整の中では、信号機設置につきまして、所管のほうでは交通量の問題から設置はなかなか厳しいかもしれないけれどもということが１点。","voiceIndex":91,"id":"exchange-042"},{"speaker":"藤原委員","kind":"質問・要望","question":"私が住んでいる町会の町会長からも区政協でこの信号機のことについては上げさせていただいたと思いますが、まだちょっと弱いんですよ、答弁が。ここまで来て、期は熟したという感じなんで、これはやるしかないと私は住んでいる地元議員として、どうしてもここで訴えをさせていただきたいもので、その辺を考慮して、ちょっと答弁をまたお願いいたします。","respondent":"武藤都市整備下水道課長","answer":"繰り返しで恐縮ですが、委員の強いご指摘のとおり、この交差点につきましては、我々としても信号機を設置してもらえるよう、先ほどの設計の配慮を引き続き行いまして、再度強く交通管理者に要望を行っていきたいと考えています。","voiceIndex":93,"id":"exchange-043"},{"speaker":"阿久津委員","kind":"確認","question":"１点目の八ツ山・元なぎさ通り整備基本設計委託なんですが、１６０ページによりますと、全長２.４kmあるんですけれども、１区間とあるんですが、その１区間、確認のため、どの部分か教えてください。","respondent":"武藤都市整備下水道課長","answer":"本事業につきましては、八ツ山通りおよび元なぎさ通りの全体の区間について検討を行っております。今お問い合わせのその１の設計の区間につきましては、その一番南側の区間、元なぎさ通りの一番南側の鮫洲運動公園の付近の設計の区間になっております。","voiceIndex":96,"id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問・要望","question":"我が会派では、平成６年から、直近では平成２２年の第２回定例会まで、この八ツ山・元なぎさ通りの整備事業について質問とご要望をしています。３点お伺いをします。１点目は、この新品川橋地域の整備基本設計というのは、いつごろ予定をされているんでしょうか。２点目に、この整備基本設計にこうした区民の要望とか安全に対する対策というのは反映をされるんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"１点目の新品川橋付近については、いつごろ具体的な設計に取り組むかというご質問についてですけれども、先ほど申しましたように、現時点では元なぎさ通りの一番南側から今設計をしておりまして、順次北側を検討していきたいと考えています。","voiceIndex":98,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問・要望","question":"何度もこれは要望させていただいているんですが、これも定例会でのご答弁、防災まちづくり事業部長のご答弁の中で、さらなる利便性の向上に向けて、引き続き鉄道事業者と協議を重ねていくというようなご答弁をいただいておりますけれども、今年の２月２５日のご答弁ということで、まだ８カ月しかたっておりませんが、８カ月たっているといえばたっておりますので。","respondent":"山崎マスタープラン担当課長","answer":"今回北口にバリアフリー新法によるワンルート確保の観点ということで設置をさせていただいたものですけれども、南口のエスカレーターについて、車いす対応型に改良する等々の、一定の利便性の改善をさせていただいてきているところです。","voiceIndex":100,"id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問・要望","question":"エスカレーターの設置、車いすに対応しているエスカレーターを設置していただいているということですけれども、これも地元の要望が強いので、鉄道事業者との協議をぜひお願いいたします。続きまして１６２ページ、まちづくりマスタープラン推進費、あと品川浦周辺地区まちづくり推進費に関しまして、ちょっとあれなんですが、総合特区について伺います。","respondent":"山崎マスタープラン担当課長","answer":"お尋ねの総合特別区域、特区の件です。品川駅周辺地域が羽田空港とリニア中央新幹線の結節線として今後重要な地域であるということで、エリア指定の予定になってあります。","voiceIndex":102,"id":"exchange-047"},{"speaker":"阿久津委員","kind":"提案","question":"この特区について、国への主な提案としてビジネス支援、例えば外国法律事務弁護士の規制緩和とか外国人留学生に対する就労ビザの緩和、これが今回品川のところに当たっているかどうかはちょっとわからないんですけれども、いろんな提案がされております。本区のマスタープラン、既存のマスタープラン、これからのマスタープランやまちづくり計画にどのように影響していくのか教えてください。","respondent":"山崎マスタープラン担当課長","answer":"東京都あるいは国のほうから先ほど申し上げた理由で、品川駅周辺の地域的なポテンシャルの高まりというようなことで認識しています。そうした観点は、品川区におきましても同様です。","voiceIndex":104,"id":"exchange-048"},{"speaker":"阿久津委員","kind":"提案","question":"非常にいいチャンスだと思います。この前、一般質問でもご提案させていただきましたけれども、特に品川浦地域、旧東海道地域、都市の景観と伝統的な街並みが非常にマッチした魅力的な地域でありますし、ぜひそういった玄関口として、こちらの旧東海道、品川区に人が流れるように、ぜひそういったご提案、またそういう働きかけをしていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"委員おっしゃるとおり、残念ながら利用件数０件ということで、執行がございません。","voiceIndex":106,"id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これはネットでもやっていましたし、私も報道で見ました。このシェルターの助成というのは、東京都の助成があって、なかなかこういったものに直接使うというのは難しいかもしれないんですけれども、本区は海に面しておりますので、ぜひこういったものを独自に研究されて、助成をしていただきたいと思うんですが、これについてのご見解を伺います。","respondent":"品川防災整備担当課長","answer":"それで、この津波のシェルターなんですが、耐震とまたどう絡むかとか、そういうところも非常に問題はあると思いますが、今回の３・１１で、津波がすごく注目の高いものとなっておりますので、こういうシェルターの購入状況。","voiceIndex":108,"id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"私は１５７ページの交通安全啓発費、同じく自転車を中心に伺っていこうと思います。やはり直接事故にならなくても、怖いねとか、いろんな話題を目にしたり、耳にしたりします。そういう中で、車の事故についてはいろんな資料を見ると減少傾向にある。そういう中で、今現在この品川区の交通安全の計画の中で重点政策は何かまず伺いたいと思います。","respondent":"藤木交通安全担当課長","answer":"委員おっしゃるとおり、自転車につきましても、当区でも重要な交通安全上の課題ということで認識しております。","voiceIndex":111,"id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問","question":"事故のイメージというと、やはり車がどうしても主体でとらえがちだったと思います。それを裏付けるようなデータ等があれば教えてください。それとあと、ごく最近ですが、やはりテレビなんかでもスポーツ型の自転車というんですか、ピストバイク等の取り締まりが強化されているという報道もありました。","respondent":"藤木交通安全担当課長","answer":"ピストバイクという、これも若者が乗っていたり、中年層が乗っていたり、いろいろな方が乗られていますけれど、もちろんこの自転車自体がブレーキがついていないことで、それだけで整備不良に当たりますし、最近流行してきているということで。","voiceIndex":113,"id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"聞こうと思っていた特にという年代のところ、２０代、３０代、４０代という中で、主に取り締まりはもちろん警察だと思います。そういう中で、やはり未然に防ぐ仕組みという点で、区がやるべきこと、あるいは区が警察と協力してやるという視点で、現在の自転車利用の対策の取り組みを教えてください。","respondent":"藤木交通安全担当課長","answer":"街頭で、これも警察と一緒なんですが、広報啓発のキャンペーンですとか、あるいは広報紙の発行、また区のほうで予算立ていたしまして、平成２１年からスタントマンによる交通事故再現を中心とする交通安全教育などを導入いたしまして、現在、事故防止対策を推進しています。","voiceIndex":115,"id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"そもそも自転車運転マナーはなぜよくないのかという中で、もちろん今だけの話ではないかと思うんですが、当然一部の人の話であって、多くの方は守られているかと思います。そういう中で、今考えられることとしたら、責任というのをキーワードに考えると、先ほどの質問でも答弁がありました。責任について軽い意識ではないかという指摘もあるかと思います。それと責任といっても幾つかあると思います。","respondent":"藤木交通安全担当課長","answer":"若干正確ではないところがあるんですが、これは神奈川県のほうの裁判例だったと思います。携帯電話をしながら夜間自転車に乗っていた女子高生が、前方を歩いていたたしか看護師の女性に衝突しまして、５,０００万円を超える損害賠償命令が出たというふうに記憶しております。","voiceIndex":117,"id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問","question":"そこで、ちょっと伺いたいんですが、法的な面もあるという中で、未然に防ぐということと、あと区のかかわりという中で、交通安全を目的としたカメラ、こういう考え方は定点で設置する場合もあるでしょうし、ぱっと浮かぶ中で、高速道路のスピードの取り締まりがあるように、同じく、仮の話なんですが、公的にはどうか伺いたいんですが、可能性があるのかどうか。","respondent":"藤木交通安全担当課長","answer":"ご質問の１点目の自転車の交通違反などを抑止するための監視カメラの設置ですけれども、防犯カメラというものが年々普及しておりますとおり、設置することによって一定の効果はあると考えます。","voiceIndex":119,"id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問","question":"あるいは、修理点検へ補助制度、まちの自転車屋なんかの協力を得た中で、そういう中で修理点検補助制度などの検討をしたり、保険加入の特典があったり、要はさっき言ったように、知ってもらう、事故防止のための重要性だとか、法的なルールの知識を知ってもらって広めるための手段として、こういう講習会をより一層グレードアップする手段として、こういったものはどうかなと思うんですが。","respondent":"藤木交通安全担当課長","answer":"そのような自治体の情報収集をいたしまして、いろいろ問題点等、課題等を明確にしていきまして、調査研究はしていきたいと考えています。","voiceIndex":121,"id":"exchange-056"},{"speaker":"渡辺委員","kind":"質問・要望","question":"本当に多岐にわたる交通安全の啓発というのは、非常にあると思います。最後に、実効性のある、やはり呼びかけだけではなくて、行動が伴うような点を踏まえて、品川区が将来的にこういったマナーに関する宣言などに進められたらいいと思うんですが、その辺、お考えはありますでしょうか。","respondent":"藤木交通安全担当課長","answer":"委員がおっしゃっているのは、自転車のいろんな交通安全利用宣言だとか、そのようなことかと認識しております。最近、近隣では世田谷区あたりもそのようなものを新たにつくったような事例がありますので、その辺を十分調査してまいりたいと考えております。","voiceIndex":123,"id":"exchange-057"},{"speaker":"向委員","kind":"質問","question":"私からは、成果報告書のページ数で申し上げますと１６２ページの都市景観形成事業、そして続いて１６５ページの都市防災まちづくり事業、特に密集住宅市街地整備促進事業についてと、時間があれば、１６３ページに戻りまして、子ども達のアイディアを活かした公園整備についてお尋ねします。一つ目、都市景観形成事業についてお尋ねします。","respondent":"藤田水とみどりの課長","answer":"品川区景観計画のほうですが、この４月１日より運用を開始をしたところです。景観計画は品川区のまちづくりと密接な関係を持ってございまして、その中でいろんな動きがあった際には、この景観計画も見直しながら進めていくべきというふうに考えてあります。","voiceIndex":126,"id":"exchange-058"},{"speaker":"向委員","kind":"質問","question":"こういった計画が整って、まちづくり、街並みを特に旧東海道のあたりとか、古い街並みを整えていこうというお考えで計画を進められていると思うんですけれども、このあたりにある公共の建物とか、交番であったりとか、住民の皆さんの安全性とかを補助するために、機能を損なわないためにという、ある程度こういった計画と住民の方の安全とか。","respondent":"藤田水とみどりの課長","answer":"品川区における旧東海道のまちづくり、これにつきましては、区がいろいろ取り組む前から地域の方々が一生懸命取り組んでいるまちです。","voiceIndex":128,"id":"exchange-059"},{"speaker":"向委員","kind":"質問","question":"わかりました。私、つい先日ですけれども、全国都市問題会議に参加、出席させていただきました。宮崎県の飫肥地区に関しては、こういった条例を制定して、建て替えるたびにさらにまちが本当に整っていく、古い街並みが蘇っていくとか、そういったお話を伺ってきました。","respondent":"藤田水とみどりの課長","answer":"私どもの景観計画の中で、今重点地区は１カ所ということになっておりますが、こうした地区を自分たちの地域でも、景観重点地区にしてもらいたいんだというような話があれば、その方々とはいろんなお話をする中で。","voiceIndex":130,"id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"わかりました。成果報告書、１点だけちょっと実際の金額のところでお伺いしたいんですが、景観計画書印刷等ということで、１６５万５,５５０円計上されていますが、予算のほうの項目には、品川区景観計画書等印刷ということで、若干項目名が違うというか、これは同じものということで考えてもよろしいでしょうか。","respondent":"藤田水とみどりの課長","answer":"今回の景観計画の冊子をつくるための経費でございまして、同じものです。","voiceIndex":132,"id":"exchange-061"},{"speaker":"向委員","kind":"質問","question":"失礼しました。６０万円ですね。では、続きまして、都市防災まちづくり事業の密集住宅市街地整備促進事業についてお尋ねします。こちらは、幾つか事務事業概要も見まして、既に終了した戸越一丁目・二丁目地区とか荏原北地区もあれば、まだ今引き続き促進事業が続いていて、私も昨年度ですかね、東中延の同潤会地区の勉強会に数回ちょっと参加する機会を得ました。","respondent":"品川防災整備担当課長","answer":"状況ですが、平成１９年６月から約８回にわたり懇談会のほうを行いまして、その後平成２２年７月に１０名の発起人の方に協力いただきまして、平成２２年１２月から検討会を立ち上げております。この検討会の中に委員のほうも何回かご参加いただいたという状況です。","voiceIndex":136,"id":"exchange-062"},{"speaker":"向委員","kind":"質問","question":"わかりました。大分人数も増えてきているのではないかなと思います。今後温度差のみが原因になるとは思いませんけれども、こういった地域の方からいろんな意見が出てきて、事業期間が、今決まっている１０年ぐらいと決まっていると思うんですが、この期間が延びたり変動してくる可能性があるんでしょうか。","respondent":"品川防災整備担当課長","answer":"この旧同潤会地区で建て替えのほうが反対とか、そういった場合が出たらどうかということですが、まず今勉強会でやっている中で、こういう木造住宅が密集した地域、この地域の防災性を高めるためにはどうしようかということを、共同建て替え、それからいろいろ地区整備とか。","voiceIndex":138,"id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"あわせて補助２０５号線も完成をするということでちょっとご質問させていただきたいと思います。渋滞予測をどうされているのか。あの辺も地域の方からあと１０cmでいいから右側に、いわゆる東方向に向かう車、広げてもらえれば右折と直進ですか、並べて行けるようになるのにというようなことをずっと言われているんですけれども、その辺の改良等を含めてお教えください。","respondent":"武藤都市整備下水道課長","answer":"あわせまして、補助２０５号線につきましては、震災の影響で、一部工事に影響が出ましたけれど、現在進めている２期区間と呼ばれる大井三叉交差点の側の約５５０ｍの区間につきまして、来年度に向けて完成で、今事業を進めている予定です。","voiceIndex":142,"id":"exchange-064"},{"speaker":"渡部委員","kind":"質問・要望","question":"確かに走りづらいなと思う反面、台風のときですから、９月十何日でしたでしょうか、タクシーがそこに思いっ切り突っ込んで大破するような事故が実際に起こっていて、そのガードレールは撤去されていますが、あそこというのは、結局補助２０５号線の工事をしていく途中で、早急に何とか中央分離帯はここですよ、ここからここは歩道ですよとわかるように、実は急ぎでやっていただきたいと思うんですけど。","respondent":"武藤都市整備下水道課長","answer":"委員の今のお問い合わせは、補助２０５号線の今整備を進めている２期区間と言われます小野学園と東京浴場前の約１６０ｍの区間の整備についてのご質問ですけれども、委員ご指摘のとおり昨年度一方通行だったものを、早期に事業効果を発揮するために暫定的に整備を行いまして。","voiceIndex":144,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"ちょっと時間がなくなったので１件だけ先に行きます。１５８ページ、街路灯について伺います。１点だけ。子どもたちが動く時間もあるので、先ほど聞いたらセンサーでつく、つかないというような仕組みだということなんですけれど、できれば街路灯はつけておいてほしいなと思うんですが、冬場にもし同じような対策をとらなければならなくなったときに、どのようにされる予定なのかだけお伺いしたいと思います。","respondent":"稲田道路公園課長","answer":"それで、冬場なんですが、まだ正式なというか、詳しい情報が私どものほうにも入ってきておりませんで、今後情報をより早く正確にとりながら、またやり方、その他考えていきたいと考えています。","voiceIndex":146,"id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"ともかく日が短くて、活動する時間が長くなっています。子どもたちが普通にすまいるスクールが終わって帰る時間帯でも、もう真っ暗になっている時間帯ですので、なるべくつけられるところはつけておいていただきたい、そのように思っておりますので、よろしくお願いいたします。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-067"},{"speaker":"金野委員","kind":"質問","question":"よろしくお願いします。私のほうからは、１６６ページ、分譲マンションの管理支援についてまずお伺いします。この支援の予算額に対して、決算額は多少減という形になっておりますけれども、まずこの事業内容と、そして減の要因をまずご説明をお願いします。","respondent":"柏原住宅担当課長","answer":"こちらのマンション管理の部分ですけれども、こちらの事業のほうは三つございまして、まずはマンションの管理相談ということで、毎月第二・第四水曜日の午後に実施しております。本日も今やっている最中です。","voiceIndex":150,"id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"そうすると、例えばセミナー、相談、こうしたところでの、セミナーは講師を派遣して、このマンションの管理に当たるいろいろなノウハウ、こうしたところをセミナーをされているんだろうというふうに思うんですけれども、また、相談は個別のいわゆる管理に当たって相談を受けると、こうしたものだと思うんですが、主にそのセミナーの内容と、あと相談で受けている内容というんでしょうか。","respondent":"柏原住宅担当課長","answer":"こちらのセミナーのほうは、毎年、テーマを決めて行っておりまして、９月に行った分につきましては、大規模修繕、こちらのほうをテーマにして講演を行いました。こちらのほうは参加の方は５９名の方が参加しております。","voiceIndex":152,"id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"そうした中で、どういった業者を選んだらいいのか、あるいはどういったところをポイントとして修繕をしていったらいいのか、そんなことが多く相談の内容としてというか、私もお聞きしたことがあるんですけれども、そういったことが多いかと思いますが、そういったことも含めて、派遣をされながらここはこうしたほうがいい、ああしたほうがいいというノウハウをされているかと思うんですけれども。","respondent":"柏原住宅担当課長","answer":"例えば、管理組合をつくっていますけれども、管理会社に委託をしている部分であるとか、自前で全部管理をしているとか、いろいろなご事情がありますので、そういった中で、その管理組合に合わせた形での修繕の方法であるとか計画。","voiceIndex":154,"id":"exchange-070"},{"speaker":"金野委員","kind":"質問","question":"区としては、確かに自主管理のところもあれば、管理組合にお願いをするところもあればということなので、区としてはこれという一つの方向性ということではないのは理解できます。そこで、マンション管理士ですけれども、マンション管理士の方というのは、いろいろといるという話を聞きます。その中で、区はどのようなポイントでマンション管理士の選定をされているのでしょうか。","respondent":"柏原住宅担当課長","answer":"品川区のマンション管理士会のほうに我々のほうはお願いをしているわけですけれども、ご相談の内容は、マンション管理士会のほうにお話をしまして、得意分野等々、例えば実務経験が長い方、それから建築士の資格を持っている方、それから弁護士の資格を持っている方。","voiceIndex":156,"id":"exchange-071"},{"speaker":"金野委員","kind":"質問","question":"そこで、マンション管理士を派遣し、そして大規模修繕でいろいろと選定をした業者とうまくいく仕事もあれば、そうじゃなくて、いろんな遺恨を残してしまうようなケースもあればということですけれども、この支援をしてうまくいった、大規模修繕でマンションがうまくいくケース、そういう結果が出たという、支援の効果というのはどのぐらいありますでしょうか。","respondent":"柏原住宅担当課長","answer":"こちらのほう、その派遣をした後にアンケートといいますか、感想を聞いている部分がございまして、なかなかやはり修繕に関してはお住まいになっている方々、プロではない方がほとんどですので、マンション管理士の支援をいただいて、わからないことがわかってきたということで。","voiceIndex":158,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"区内に一つしかない老人保健施設ですから、利用する方もたくさんいるんですけれども、そういう中で、入所される際の手続とか利用されている家族の洗濯物を届けたり、引き取ったりと、長居はしないけれども、少しの間とめておきたいというときに、駐車場がないんだということで、そもそもこのさくら会には、利用者の家族が使える駐車場はあるんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみませんでした。それで、駐車場をつくってほしいということで、さくら会の正面玄関のところの道路に白枠で囲ったような路上駐車場なんかをつくれないものなのかという声もあるんですけれども、その辺は可能性としてはいかがでしょうか。","respondent":"藤木交通安全担当課長","answer":"周辺に一般的な交通規制の一つでありますパーキングメーターのようなものだったら設置してあると認識しております。","voiceIndex":165,"id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"近くにあるパーキングなども空いていない、時によっては空いていない、いつも空いているという状況ではないという声も聞かれますので、さくら会用の駐車場として道路のところに設置はできないんでしょうか。","respondent":"藤木交通安全担当課長","answer":"あくまで道路上ということでございましたら、道路にはそういう私権のようなものは設定できませんので、そのような交通規制の一つであります短時間のパーキングメーターのようなものに限定されるものですので、設置は不可能です。","voiceIndex":167,"id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現にそこにとめておいて駐車禁止の切符を切られたという利用者の家族の方もいましたので、またそのたびにタクシーで来るというのも、お金もかかって大変だという声も聞かれますので、この実態をちょっとどうにか解決していただきたいなと思うんです。この道路のところで何とか改善というか、改めて検討していただきたいなと思うんですけれども、工夫の余地はあるでしょうか。","respondent":"松代都市計画課長","answer":"今委員からのご質問は、例えばお見舞いに来たとか、そういうときの車というふうに考えられますので、それは周辺の有料駐車場等をご利用いただければというふうに思います。","voiceIndex":169,"id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問","question":"でしたら、路上駐車場というのは、どうしたらできるんでしょう。どうやったらつくれるんでしょうか。路上駐車場をどうやったらつくれるのか。","respondent":"岩田都市環境事業部長","answer":"担当課長がお答えしましたように、道路交通法で道路の駐車場の設置権限は、東京都公安委員会のみが持っておりますので、現実には設置不可能です。","voiceIndex":171,"id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問","question":"そしたら、東京都のほうが認めるというのは不可能なんですかね。それを認めてもらうような交渉なり、こちらからの申し入れというのはできないんでしょうか。","respondent":"岩田都市環境事業部長","answer":"道路交通法で認められておりますのは、緊急患者用の表示、既に設置されていると思うんですけれども、そういった救急病院のみでございまして、その他のものは一切例外なく認められません。","voiceIndex":173,"id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コミュニティバスについてですけれども、以前も請願が幾つも出されて議論をされていると思うんですけれども、区民の要望とコストと、こういうところの狭間に行政がいるわけですけれども、こういったところの整合性はどのようにしてとられているのか教えてください。","respondent":"松代都市計画課長","answer":"すべて不採択という形の結果になってありますけれども、その間、いろいろと質問を受け、お答えをしてまいりました。私どもの基本的な姿勢としましては、やはり今委員からもありましたように、経済性です。２３区のうち、今１８区が運行しておりますが、すべて赤字です。","voiceIndex":175,"id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問","question":"請願等でも、答弁の中でも今これに踏み込むべきではないときで、当面少し見送るという状況にあるということもおっしゃっていましたけれども、どういった状況になれば踏み込む状況になるんでしょうか。","respondent":"松代都市計画課長","answer":"そういった形の整備をまず進めていこうと、このように考えてあります。","voiceIndex":177,"id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"赤字なんだけれども、区民要望にしっかりとこたえて頑張っている自治体がこれだけあるということは、しっかりと区民の思いに応えて、やさしいまちづくりとして進めていけば、そういう視点に立って進めていけばできることなんではないかなと思うんです。でも、確かにこの都の補助金が少ないのは確かだと思います。都からの補助が増えたら、可能性はあるのかお聞かせください。","respondent":"松代都市計画課長","answer":"残念ながら、今のところ補助等があっても、区がそのことに踏み込むつもりはございません。","voiceIndex":179,"id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、やはりこういった方々を、せめて生活の買い物にまちに出てもらうとか、こういった自立をしてもらうという、自立を進めていくという上でも、品川区は、今、介護予防なんかもすごく進めていると思うんですけれども、こういった点でもすごく予防になるし、孤独をなくすという意味でも、やさしいまちづくりというところにかかってくるんではないかなと思うので。","respondent":"岩田都市環境事業部長","answer":"今後、都市計画道路ができるのを待って、そういう道路にも路線バス網を増やしていく、まずそれが最優先だということで、福祉関係の問題については、別途視点を変えて検討すべき問題だろうと考えております。","voiceIndex":181,"id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり先ほどもお話ししましたけれども、さくら会までの交通網がなかなかないんだと。ですので、これから特別養護老人ホームもさらにできてくるという状況で、高齢化も進んでいくというのは、区のほうでもご存じのことだと思いますので、こういったところにしっかりと公助として手を差し伸べていく、援助をしていくということが今必要なのではないかなと思うんですけれども、いかがでしょうか。","respondent":"松代都市計画課長","answer":"例えば福祉タクシーを今やっておりますが、そういった形で対応するとか、コミュニティバスですべて満足すると、そういった形には環境的にはないというふうに考えているところです。","voiceIndex":183,"id":"exchange-083"},{"speaker":"原委員","kind":"質問・要望","question":"私は成果報告書の１６１ページ、目黒川水質改善、それから同じく成果報告書の１６２ページ、都市景観形成事業、それから１６７ページの区民住宅費等についてお伺いします。ですから、木村委員の質問とダブらないように他区とか、それから東京都、その辺との調整関係、具体的に言うと今後どうなる、どうなっていくのという、そこを教えていただきたい。それについてお教えください。","respondent":"藤田水とみどりの課長、柏原住宅担当課長","answer":"今後は、東京都の重い腰を上げるために働きかけを行っていきたい、東京都みずから取り組んでもらえないかということをお願いしてまいりたいというふうに考えてあります。それから区民住宅のほうです。平成２２年度につきましては、４,０１５万９,３８３円、平成２１年度につきましては、３,６７６万６,５９３円です。","voiceIndex":186,"id":"exchange-084"},{"speaker":"原委員","kind":"質問・要望","question":"その次の段階、３番目の住宅の未収部分なんですけれども、何でこういう言い方を申し上げてしまうかというと、確かに専門家、宅建協会ですとか弁護士をお使いになるのも当然のことかと思うんですけれども、まず取れないとか払わないのに出ないとか、いろいろな問題はあろうかと思うんですけれども、だったらば、その前にそういう状況にならない方法がないんだろうかと、その辺についてお考えがあれば。","respondent":"柏原住宅担当課長","answer":"一月滞納してしまうとその金額、さらに二月となると１０万円、２０万円、３０万円という形になりまして、そこからなかなか厳しい状況になるということがありますので、我々としましては。","voiceIndex":189,"id":"exchange-085"},{"speaker":"原委員","kind":"質問","question":"それからあと、民間の今賃貸状況なんかを見ますと、居住が今、敷金・礼金、ゼロ・ゼロというのがはやっていたり、３カ月ただにしますよという大家さんがいたり、それこそ事務所系なんかであれば、１年がただじゃなくて、今１５カ月ただですよと、そういうような住宅関係の展開になっているんですけれども、ですから、私は何を申し上げたいかというと、保証人、それから保証会社をもっと活用できないか。","respondent":"柏原住宅担当課長","answer":"未収につきましては、いろいろなところを研究しながら、特に保証人についても、今までは４カ月たたないとお話ししなかったのを、１カ月、２カ月ですぐご連絡するとかというふうに運用上変えてきている部分もあります。","voiceIndex":191,"id":"exchange-086"},{"speaker":"原委員","kind":"質問","question":"ですから、しっかり同じような形で、そして時期をずらさないで、これは金額だけの問題じゃなくて、督促等はタイミングというのもあろうかと思います。ですから、その辺も考えてお願いをできればと思います。時間があともう少しあるようですので、ページは戻りまして、１６１ページの橋梁、歩道橋なんですね。全体の幅を言いますと、３分の２が階段になっております。これは区ではなくて都なのかもしれない。","respondent":"松代都市計画課長","answer":"将来的には、やはりユニバーサルデザイン、やさしいまちづくりで、そういった障害者等にも対応できるような歩道橋をというのが国の政策でありますし、東京都もそういった方向で考えてありますので、しかるべき時期にはそういった計画が出せるものと。","voiceIndex":193,"id":"exchange-087"},{"speaker":"原委員","kind":"質問","question":"実際にいつスタートするかわかりませんけれども、ＪＲが五反田駅、いろんな考え方をお持ちになり出してきたというような話もちまたには伺いますので、うわさかもしれませんけれども、もしそういったことが出てきましたらば、ぜひとも東京都に対して歩道橋に関しては改善、改善というか改良していただけるように、もう一度そこのところをお聞かせいただければと思います。","respondent":"松代都市計画課長","answer":"したがいまして、ＪＲも含めて、東京都も含めまして、品川区もしっかりと周辺等々、皆様と一緒にまちづくりを考えていきたいと、このように思っているところです。","voiceIndex":195,"id":"exchange-088"},{"speaker":"吉田委員","kind":"質問","question":"街路樹等維持管理費ですが、道路環境の整備と、まちの緑化を推進するために区道に街路樹の植栽や植樹帯を設置し、定期的に剪定し、そして除草、支柱取り替えおよび害虫防除等を行っていらっしゃるということですけれど、ここでちょっとお伺いしたいのは、平成２１年度は成果報告書に剪定数が記載されておりますが、平成２２年度は載っておりませんので剪定数を教えてください。","respondent":"稲田道路公園課長","answer":"それから基本剪定、これは冬場に行うものでございまして、木の骨格的な形をつくってやる剪定というのが１,４４０本行いました。中木刈り込みが７４８本、あと除草が５万３,２３５m2、低木刈り込みが２万６,１０５m2というふうな実績です。","voiceIndex":198,"id":"exchange-089"},{"speaker":"吉田委員","kind":"意見","question":"ここで台風についてちょっとお話ししたいんですけれど、２００９年に発生数は２２個で接近は８個、２０１０年は発生数は１４個で接近は７個でした。今年ですが、台風１５号の上陸に伴い、区道・公園等で被害の報告がありましたが、その状態を統計数値でお願いいたします。","respondent":"稲田道路公園課長","answer":"９月２１日の台風です。このときの倒木数なんですけれども、全体で、私どもの施設以外で６５カ所の倒木等あったんですが、区の道路・公園でいきますと、合計で４４本の倒木、枝折れ等があった本数を確認しました。","voiceIndex":200,"id":"exchange-090"},{"speaker":"吉田委員","kind":"質問","question":"そのうちで、倒木が車にぶつかり、事故発生ということをお聞きしましたが、けが人等がなくてよかったと考えています。私が一番心配しておりますのは、こういう街路樹等の老朽化なんですけれど、台風などに備える意味でもありますが、老朽化対策はどのようになっているのでしょうか。専門家の判断基準などがございましたら、お教えください。","respondent":"稲田道路公園課長","answer":"年に１回程度全体的な街路樹等の点検も行っております。そして、台風が近づくときにおきましては、また強化して点検を行っているです。その中での点検基準というものなんですが、基本的には外観の点検を行うのが常です。","voiceIndex":202,"id":"exchange-091"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから一つつけ加えしますが、これは要望なんですけれど、街路樹を支える添え木というんですかね、こういう二股になっているんですけれど、それが老朽化しまして、百反坂のほうでは針金等だけになっている、また外れているところがまだまだ見られますので、点検等もよろしくお願いいたします。本区の公園全部を完全にバリアフリー化するのか、その辺をちょっとお伺いしたいと思います。","respondent":"稲田道路公園課長","answer":"この公園バリアフリーなんですが、公園２４５カ所ある中で、まずは入り口の段差をなくしたり、まずはそういうところから始めていくということで、順次１カ所ずつ進めていると。","voiceIndex":204,"id":"exchange-092"},{"speaker":"吉田委員","kind":"質問","question":"もうちょっと具体的に計画的に、例えば何年までにこうするみたいなことはありますでしょうか。","respondent":"稲田道路公園課長","answer":"２４５カ所のうち、１５８カ所が整備済みです。その中の段差を解消するというのも、４９％は終わっているというところでございまして、未整備があと８９カ所、これは順次行っていきたいというふうに考えております。","voiceIndex":206,"id":"exchange-093"},{"speaker":"吉田委員","kind":"質問・要望","question":"順次行っていっていただきたいと思います。ここで一つ、雨の日なんですけれど、坂の下の公園など、細めタイプの横断側溝なんですが、滑って危ないと。転んじゃったよという話もお聞きしたんですけれども、この細めの横断側溝で、そういうお話は聞いたことがありますか。","respondent":"稲田道路公園課長","answer":"といいますのは、滑りにくく改良したといいますのは、細い鉄のバーが通っているんですが、最近のものはそこにぎざぎざがつくようになっております。そういうものに変えていきながら、またそういう坂道等ではそういう滑りどめのものを使っていきたいというふうに考えております。","voiceIndex":208,"id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"最初に、放置自転車の件ですけれども、旗の台駅南口、何回も質問していますけれども、東急電鉄が南口に住宅を建てるときに、駐輪場とか駐車場、オートバイですね、建設をすると約束をしていたけれども、結局できたのはバイク用の駐車場だけだったということで、この件については、これからどのような形でやっていくのかなということですが、自転車法では、鉄道事業者が駐輪場を設置しない場合は。","respondent":"藤木交通安全担当課長","answer":"最近の情報ですと、再度具体的に検討しておりまして、できましたら年度内にはどうにかしたいような、そのような情報を聞いております。","voiceIndex":212,"id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"私道整備事業につきましては、９７％を超える執行率だったと私の計算によるとなっているんですけれども、平成２２年度内に申請された件数と工事が完了した件数、そしてまた平成２２年度に完成したけれども、前年度以前に申請されて完成した件数、また平成２２年に申請をしたけれども、残念ながら平成２３年度以降に持ち越しになった件数、こちらのほうをお伺いしたいと思います。","respondent":"中村建築課長","answer":"申請いただきましてから、着工するまでの期間ですけれども、こちらは通常の場合ですと申請いただいて、申請者の方にお話を聞きに行きまして、設計の内容を十分吟味した上で設計を行い、そして工事の発注、着工というところまで、通常は３カ月を要します。","voiceIndex":214,"id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"最近、この申請につきましても、私も聞いたところによりますと、年度当初、結構年度の早いうちに申し込みをしても、完成は翌年度ですと言われるケースも、私も２年続けて区民の方から伺ったことがありますので、ぜひとも何とか早くしていただければと思うんですけれども、例えば予算、補正予算もかなり毎年のようにとっているかと思うんですけれども、一度大きく予算をつけて。","respondent":"中村建築課長","answer":"今後、また状況を見まして、どのように待ち時間を短縮していくかどうか、この辺を設計の努力とあわせて、ほかに方法があるかどうかを検討してまいりたいというふうに考えております。","voiceIndex":216,"id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"土地の所有者に責任があるということですので、長い間穴があいたまま放置ということもできないので、ここら辺も含めてなるべく早く対応していただければと思います。次に、耐震診断助成ですけれども、こちらは予算の１割にも満たない状況かと思います。例えば、３階以上、また１,０００m2以上を対象としている助成制度を何とかもう少し条件をつけながら下げていくという考えはあるのかどうかお伺いします。","respondent":"品川防災整備担当課長","answer":"それからマンションのほうですが、基本的には大規模マンションということで、１,０００m2３階建て以上ということで、事業のほうを展開しておりますが、それ以下のマンションにつきましては、他区の動向も踏まえて考えていきたいというふうに思います。","voiceIndex":218,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問・要望","question":"目黒川の水質改善は、ほかの委員からも質問があったので、私としては、品川区行政評価委員会の評価結果でも、水質浄化の抜本的な取り組みは、河川管理の主体である東京都の責任において行うべきであり、引き続き東京都へ働きかけること、区が行うべき事業の内容を具体的に検討することということで、区がこれまで行ってきたことを評価しつつも。","respondent":"武藤都市整備下水道課長、藤田水とみどりの課長","answer":"もう１点、鮫洲運動公園の改修工事につきまして、子どものアイディアを活かした整備を平成２２年度から、一部震災の絡みもございまして、平成２３年度に一部事業を実施しておりますけれども、その成果についての区の考え。河川の関係の浄化の部分ですけれども、都からの補助金等が入っているかですが、立会川、目黒川の浄化とはちょっと違うんですが、清掃委託、それから汚泥浚渫委託ということで、これらのものについては。","voiceIndex":221,"id":"exchange-099"},{"speaker":"高橋委員","kind":"質問・要望","question":"それが一つ。事務事業概要によると、城南河川清流復活事業負担金を４６０万円、１０年間支払っています。それを全額都に負担するように求めている、おそらく平成１３年から求めていると思うんですが、十数年たっています。それをほかの区、つまり、品川区以外のところでこのようなことが行われているのか、それならばなぜ、獲得して品川区がそれだけのことができるのかということをお尋ねします。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"城南河川の清流復活の関係ですが、もともと東京都が城南河川の６区に対して、都の事業として行うということでスタートしたものでございまして、その後東京都のほうが財政状態が厳しいということで。下水道局と品川区の関係ですけれども、これは大分昔になるんですが、この受委託関係というのは、昭和５６年から始まっております。","voiceIndex":224,"id":"exchange-100"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、過去にこのような大きな形で受託事業は、どのようなものがあったかということ、それから事業を行う際に、区の職員の方のいわゆる事務費というんでしょうか、人件費がかかると思うんですが、その点については受託費の中に含まれているんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"受託の過去の状況ですけれども、特に目黒川につきまして浸水被害がひどい状況がございまして、目黒川の左岸および右岸、両側に大規模な下水道の浸水対策用の管渠の工事を受託して、昭和６１年度から最近までずっと事業を進めておりました。","voiceIndex":227,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問・要望","question":"とすると、言い方はあれですけども、持ち出しなしでこの事業、下水道管耐震化推進事業を行われているというふうなことでよろしいでしょうか。ということは、事務事業評価でも、拡充ということの事業でありますし、区民の方々のサービスに直結する事業なので、さらなる拡充を目指していっていただきたいと思います。","respondent":"稲田道路公園課長","answer":"ただ、分煙化というところなんですが、一応１,５００m2という公園の面積で、分煙化にするか、禁煙にするかというふうな考えを区のほうでは持っておりまして、分煙化する公園は１,５００m2以上の公園、禁煙化は１,５００m2以下の公園ということで考えております。","voiceIndex":229,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"今のようなお話の形で進め、ＪＴさんの協力も必要だと思いますので、ぜひ推進していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も私道の整備の工事に関しては、本当に申請をしてから長い時間がかかるということで、これが何とかもっとスムーズにできないものかなと思って質問をするんですけど、先ほどもほかの委員からも質問があったんですけど、改めてちょっと平成２２年度と今年度、平成２３年度の申請件数と工事件数、それとその工事件数の中で、前の年か前々年度か。","respondent":"中村建築課長","answer":"それと今年度、平成２３年度ですが、現在までに２５件の申請をいただいております。そして、同じく９月いっぱいまでに工事をした件数が１５件です。それと、持ち越した件ですが、これは先ほど申し上げましたが、平成２２年度から平成２３年度に持ち越したのが３１件です。","voiceIndex":233,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当に１年から１年半くらいかかるのが当たり前という状況で、この私道の場合は、合意をとるのにも結構時間がかかりますので、何とかしたいというふうに思って合意をとって申請をして、工事が終わるまでに本当に１年半とか２年とか、本当に長い間かかってしまうわけなんですけど、少なくとも申請してからなぜこんなに時間がかかるのかといえば、それは予算の問題ということになるんでしょうか。","respondent":"中村建築課長","answer":"緊急性、先ほども申しましたが、緊急性だとか、その辺を勘案して、危険を最小限あるいは安全な状態を保持できるように、そういった配慮をしながら計画的に進めていきたいというふうに考えております。","voiceIndex":235,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大体私道の整備をしてほしいということで相談に行くときには、本当にでこぼこがあって、転んでけがをしたとか、そういう整備をしてほしいという状況があって、大体相談に行くんですよね。それからかなりの時間が余りにもかかり過ぎるということで、何とか予算をつけて増額して、翌年度までに持ち越さないという感じで増額していただきたいと思うんですが、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"ただ、区のほうとしては、円滑に工事が進むようにきちっと必要な予算についは調整を行っていきたいと考えていますし、合意形成に向けてもそういう対応を行っていきたいと考えています。そのような状況です。","voiceIndex":237,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、かなり本当に公道から公道に通じているような道路でも、２.５ｍ以下ということで１割負担があるとなると、なかなか合意形成がとれなくて、本当にでこぼこで危ないような道路でも、そのまま何年間にもなってしまうという状況になっていると思うんですけど、そこのところを何とか全額区の負担になるような方向にしていただきたいなと思って質問したいと思っているんですが。","respondent":"中村建築課長","answer":"過去１０年間ですけれども、私道の整備の制度が始まりまして、１５１件が工事の件数です。そのうち９割助成、１割を申請者様に負担していただいた件数、これが８０件です。","voiceIndex":239,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９割助成が８０件ということで、私はなかなかこの１割負担があるために合意がとれないという相談を何件か受けていましたので、こんなにたくさんあったということはちょっと意外だったんですけど、それにしても１割負担があるために合意がとれないで、でこぼこの道路がそのままになっているという状況がずっと続いているというところが何件かありますので、そこのところはぜひとも１割負担をなくして。","respondent":"中村建築課長","answer":"今私道といいますと、それぞれ権利者様の合意が得られなければ着工ができないという私有財産です。ですので、この私有財産にさらに手を加えるということになりますと、一定程度のやはり負担はやむを得ないというふうに考えております。","voiceIndex":241,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区では、この公共性に着目して、区民福祉の増進を目的に生活環境の改善、安全で快適なまちづくりに努めていますということで、こういう形で拡大をしたわけなんですが、区としても本当にだんだん増やしてきていただいて、２.５ｍ以上は全額助成ということで拡大されているということはよくわかるんですが、さらにもう一歩２.５ｍ以下の道路に関しても全額助成ということでご検討いただきますように。","respondent":"品川防災整備担当課長","answer":"平成２３年のまず耐震診断につきましては、９月末現在で１５５件、それから耐震改修につきましては２件、耐震建て替えにつきましては２０件という状況になっております。","voiceIndex":243,"id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この９,８００棟で、そしてまた年間１,１００棟という目標からすると、まだまだ遠いんじゃないかなというふうに思うんですけど、それでも今年度は耐震診断が急激に伸びていると思うんですね。それと、耐震診断の体制は現在何人でされているのか、それは今回の急激にこの耐震診断の申請が増える中で、強化されたのかどうかについてもお聞かせいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"それから体制ですが、こちらはちょっと職員のほうか、また建築士のほうかわかりませんが、職員のほうに関しましては、やはり窓口の申請がかなり多いですので。","voiceIndex":245,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"私は１５７ページ、交通安全啓発費に関連して、それから１６１ページ、立会川浄化対策、１６３ページ、しながわ水族館に関連して質問いたします。結果として渋滞が起きました。つまり、車列が行くわけですよね。激励に行く。だから、啓発に行きながら、そういう事態を引き起こしたのは、どうも余り格好よくないと思いますので、まして、警察の方々が乗っているわけですから、交通安全のプロなわけですよ。","respondent":"藤木交通安全担当課長","answer":"警察のほうで交通安全運動期間中にテントのほうを激励に参りまして、結果的にそのような交通渋滞を招いてしまったとなりますと、まさに本末転倒ですので、その辺、駐車場所の事前の十分な徹底ですとか、その辺につきましては。","voiceIndex":248,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"確認","question":"大体場所が、テントがあるところは限られているでしょうから、例えばそこに行ったら、ほんの少し手前といいましょうか、あいたところに車を置いて、そこまで歩いてもらうとか、それからどうしてもの場合にはまさに警察官が同行されているわけでしょうから、後続の車をうまく誘導していただくとか、そうすればこの問題は解決すると思いますので。","respondent":"藤田水とみどりの課長","answer":"それで、現在行われている立会川の高濃度酸素溶解水の機械ですが、５年で一応リース切れになりますが、通常であれば七、八年使えるですので、何とかもう少し頑張っていただいて、それまでの間いけば、その後については汚れたものが流れてこなくなれば川自体はきれいになる。","voiceIndex":250,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"確認","question":"それをつまり抑えるためにいろんなことをやっているということを聞いたんだけれども、それがもう少し時間がかかることは確かなことで、その間のある意味つなぎとして、こういう高濃度酸素溶解水の導入があったということを聞いているんだけれども、今のお話を聞いていて、もう少し確認したいのは、やっぱり５年ということだけど、あと二、三年頑張るということだけれども。","respondent":"岩田都市環境事業部長","answer":"先ほど水とみどりの課長が申し上げましたように、今でいきますと、平成二十七、八年で下水道局の工事が終わる予定ですので、２年から３年ぐらいリース切れですけれども、一部部品の交換をしながら、それまで活動してもらう。","voiceIndex":252,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"提案","question":"違う方向で提案するんであれば、またそれは相当な覚悟をしなきゃいけないと思う。つまり、それぐらいの思いと、それから民間の観点を入れていかないと、しながわ水族館の将来に大きな禍根を残すと思いますので、確認したいのが、区内で検討するのはもちろん正しいことなんだけれども、それに加えて多くの民間の視点といったらいいのかな、民間の導入は考えていらっしゃるでしょうか。お願いします。","respondent":"藤田水とみどりの課長","answer":"そうした中で、本年あり方検討ということで行ってありますが、このあり方検討を、例えば区の内部だけで行う、それから水族館の運営事業者の中だけで行うということになると、やはりどうしてもひいき目に水族館を見る中でのあり方の検討になってしまうということで。","voiceIndex":254,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"難しいんですよね。遊園地でも水族館でも何でも、同じものをずっと展示し続けていけば、やがてあきられる。だからこそリニューアルが必要だということで質問するわけでありますけれども、ここはぜひ品川区の中心的な施設ですから、濱野区長の水族館にかける思いをお聞かせください。お願いいたします。","respondent":"濱野区長","answer":"その検討を待って、今後の推移を考えたいというふうに思っております。","voiceIndex":256,"id":"exchange-115"},{"speaker":"山元委員","kind":"質問・要望","question":"よろしくお願いします。私は１５７ページの土木総務費の中の道路・公園等の監察、占用許可、それからその後は、１６３ページの、先ほども出ましたけれども、公園新設改良費の中の子ども達のアイディアを活かした公園整備、こちらのほうをお聞きしたいと思います。具体的にどういうものを取り締まったのか教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"この総件数の内訳ですが、まず一番多いのが商品の道路へのせり出し、これの指導が１,０４９件、それから路上生活者もあります。これが２３件。不法占拠処理９件、それから放置屋台というものもございまして１件あります。その他もろもろ１３１件という内訳です。","voiceIndex":260,"id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"公の道路をそのようにいろんなせり出しとか今ご案内いただきましたけれども、それに対して区としてはどのような対応をなさっているのか、具体的に教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"対応としましては、大きく二通りございまして、一つは警察、道路交通法の問題もありますので、無断道路使用ということでは交通管理者という機関と連携いたしまして、年間の合同パトロールということで実施しています。","voiceIndex":262,"id":"exchange-117"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に小さなお子さんがいらっしゃる、ベビーカーを押したりとか、またご高齢の方のシルバーカー、そこにまた自転車が通るとその商店の看板とかいろんなものが出ているものですから、本当に危ない思いを、冷や冷やする思いをする方がたくさんいて、私のところにも、「あそこの店、どうにかならない」とか、いろんなふうにあります。これはどういうことなのか教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"商品のせり出しにつきましては、町会あるいは商店街の方とも連携いたしまして、２０回余りの年間の、平成２２年度の警察との合同パトロールの中では、４回については地元の商店街あるいは飲食店組合の方、あるいは町会の方と連携して、合同して行っていくということで。","voiceIndex":264,"id":"exchange-118"},{"speaker":"山元委員","kind":"質問・要望","question":"どうかよろしくお願いします。では、１６３ページの子ども達のアイディアを活かした公園整備についてお伺いいたします。ところが、ベンチとかがあるんですが、その上には何もないものですから、炎天下の中で食事をしているということで、その辺何か日陰になるようなものができないものなんだろうかというお話を伺いました。実はそれは漢字で書いてあるものですから、小さいお子さんにはちょっとわかりません。","respondent":"武藤都市整備下水道課長、稲田道路公園課長","answer":"この差についてご説明します。１点は、工事を起工して、契約したときの落札の差で約１,１００万円程度、それと震災の影響によりまして、平成２３年度に工事を繰り越した関係で１億４,０００万円程度というものになっております。倒木の跡の穴ぼこ、それからベンチの上の日陰等、それからトイレのボタンに絵をつけるというところですが、直ちにやりたいと思います。","voiceIndex":266,"id":"exchange-119"},{"speaker":"西本委員","kind":"質問・要望","question":"自転車対策です。これは先ほどほかの委員も言っていましたけれども、自転車を使うと、利用するという前提で政策を考えたらどうかということがありました。それで、先ほど違いますよと、そういうことではありませんよというお話を受けましたが、その辺、もう一度お考えいただきたいんですが、いかがですか。","respondent":"藤木交通安全担当課長","answer":"区の基本方針ですけど、先ほど申し上げたとおりでございまして、自転車の利用は自粛をしていただきたいということで進めております。","voiceIndex":272,"id":"exchange-120"},{"speaker":"西本委員","kind":"意見","question":"総務費のところでもお話をさせていただきましたが、例はあまり出したくはないんですけれども、伊藤学園の話です。一般開放をするよという中で、いろいろ建築をしている。しかし、あそこの駐輪場は、学校側に言わせると、これは学校のものであって、一般開放するものではないと。そうすると、あそこには駐輪場がないという形になりますが、それはどういうふうにお考えになりますか。","respondent":"石田（秀）委員長","answer":"駐車場、さっきは、それで道路に設けてくれというから少し許したけれども、まさに学校の中で駐輪場だけとなると、学校施設の問題になるから、それはそれ以上続けると注意せざるを得なくなっちゃうので考えてください。","voiceIndex":274,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"質問を変えます。学校施設、明日もありますので追求しますけれども、ただこの要因は、学校開放に限らず、区の政策として先ほどの答弁のように区民の自転車を使用するということに対して、啓発はしなければいけないと思います。その中で、やはり自転車は使用するという前提でさまざまな政策を立てていかなければならないのではないかと思いますが、いかがですか。","respondent":"岩田都市環境事業部長","answer":"特定の施設は別にいたしまして、公共施設におきましても、必要最小限のそういったサービス施設は設けておりますけれども、それをあふれるものについてはやっぱり自粛をお願いせざるを得ないという実情をご理解いただきたいと思います。","voiceIndex":276,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"ただ、区の政策の中で、やはり自転車を使う区民の方が多いということは、やはり認識をした形でのさまざまな政策づくりをしていくべきではないでしょうかということを言っているので、それに対してのお考えと、それから商店街についても同じことが言えるんじゃないかと思うんですね。それから、料金の見直しをするということも図るということもお聞きしていますが、その進捗状況もお聞きします。","respondent":"藤木交通安全担当課長","answer":"ご質問の３点目、駐輪場における電子マネーの関係ですけれども、それは今具体的に指定管理者などとこのような導入ができないかということで、また区内部でもいろいろ調整を今進めているところです。","voiceIndex":278,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひちょっと区の考えを変えていくべき時期に来ているのではないかというふうに思っておりますので、ご検討していただきたいと思います。次に行きます。１６２ページの景観形成、それからあと二つは関連してなんですけれども、１０月２日の景観まちづくりシンポジウムに参加させていただきました。これらはまだまだ改善すべきところがあるのかなというふうに思いますので、そのお考えをお聞きいたします。","respondent":"藤田水とみどりの課長","answer":"そういうような人たちの力も活用しながら、まだ１カ所しかない重点地区、これを複数の箇所に広げられるように、私たちもいろんな方と連携しながら進めていきたいと考えています。","voiceIndex":280,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"キーパーソンとなる方たちというのは非常に大切だなというふうに思っております。コーディネーターというのがどういう意味でここの中で整理されているのか、これももしかしたら、地域をつくっていくためにも有効活用できるのかなというふうに考えるんですが、それらの考え方についてお聞きします。","respondent":"藤田水とみどりの課長、山崎マスタープラン担当課長、三宅都市開発課長","answer":"そういう面では、まちづくりの支援事業、このほうを活用するほうが、地域の人たちを主体にまちづくりが進められるというふうに考えてございまして。区民の自主的なまちづくりの支援ということで、まちづくりにつきましては、ある意味区民の方がまちづくりにきっちり関与して。都市再生総合整備事業におきますコーディネート業務ですけれども、大崎駅周辺地域では、幾つもの地区で再開発事業が行われている関係で。","voiceIndex":282,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、ばらばらに行動することではなくて、しっかりと協力しながら、補い合いながら推進していっていただきたいというふうに思っています。この遊具は、選定はどのような基準なのか、例えば幼児用、２歳から１２歳とか、大きいんですよね。広いんです。それらをすると、どうしてもけがとかをしやすいということになりますので、具体的な基準と、それから今後の進め方についてお聞きしたいと思います。","respondent":"武藤都市整備下水道課長","answer":"具体的には公園のそれぞれの遊具について、メーカーが定めるいろんな基準等がございまして、その辺を見ながら設置を検討しております。","voiceIndex":286,"id":"exchange-126"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１６３ページの公園管理費と１６４ページの公園バリアフリーについてお伺いさせていただきたいと思います。先ほどもほかの委員からもご質問がありましたが、１５８カ所現在終了していて、これからもこうしたバリアフリー化を進めていくというお話でした。失礼しました。最後の部分は抜かしていただいて、予算で８カ所となっているところが、１１カ所に増えた理由を教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"予算では８カ所というふうになっておりますが、実績は１１カ所というところです。これは公園８カ所、それに公園の中のトイレの手すり等も設置したほうがいいんではないかというところで、トイレ工事を３カ所つけ加えまして、１１カ所の実績となった次第です。","voiceIndex":290,"id":"exchange-127"},{"speaker":"大倉委員","kind":"質問","question":"予算では、バリアフリー化が６カ所、安全・安心の公園づくりが２カ所と書いてあったんですが、手すりを増やしただけではなく、バリアフリー化を増やしたのも２カ所あるということでよろしいでしょうか。","respondent":"稲田道路公園課長","answer":"バリアフリー化と安全・安心の公園づくりで、見通しをよくするというのが安全・安心の今回やったところなんですが、鎗ケ崎公園、谷垂公園等を、見通しをよくした安全・安心ということで、全部含めて公園関係８カ所、トイレ３カ所、全１１カ所です。","voiceIndex":292,"id":"exchange-128"},{"speaker":"大倉委員","kind":"質問・要望","question":"この公園バリアフリー化がいつから始まっているのか、これを教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"公園バリアフリー化の事業ですが、平成１８年からやっております。平成１８年からです。","voiceIndex":294,"id":"exchange-129"},{"speaker":"大倉委員","kind":"質問・要望","question":"平成１８年からということでしたが、前年度６カ所で、今年度が１１カ所ということで、あと事業が残っている公園が８７カ所近くあると思うんですが、毎年このぐらいの箇所数でいくと８年ぐらいかかってしまうと思うんですが、早急にバリアフリー化したほうがいいと考えているんですが、もちろん災害時とか公園等が一時避難場所になり得るのかなという思いの中で早い整備が必要だと思っているんですが。","respondent":"稲田道路公園課長","answer":"私ども計画を立てておりまして、予算等もありますので、年間８カ所程度前後というところで、現地の優先順位等も考えながら約１０年近くはかかるとは思うんですけれども、やっていきたいと考えております。","voiceIndex":296,"id":"exchange-130"},{"speaker":"大倉委員","kind":"意見","question":"優先順位を決めてということでしたが、その優先順位というのはどういった優先順位、例えば利用が多いとか、そういったところをちょっとお願いいたします。","respondent":"稲田道路公園課長","answer":"施設の老朽度、それから委員おっしゃられました利用の頻度、それは現場を見て、私どもの担当者が判断して次年度はここをやっていこうというふうに予算等で計上しているものです。","voiceIndex":298,"id":"exchange-131"},{"speaker":"大倉委員","kind":"質問・要望","question":"公園管理費についてお伺いをさせていただきたいと思います。２３６カ所ありますが、前年度も２３６カ所ということで、前年度に比べて決算ベースで金額が減っているのですが、その理由と、先ほどちょっと間違ってしまいましたが、平成２２年度の予算では２,０００万円比べて上がっているんですが、その上がった理由もお知らせください。","respondent":"稲田道路公園課長","answer":"公園・児童遊園維持管理費です。７億９,８４７万９,５８６円と平成２２年度はなっております。こちらと平成２１年度の比較ということでご説明いたしますと、約３,０００万円ちょっと、平成２２年度は決算が下がっているという状況です。","voiceIndex":300,"id":"exchange-132"},{"speaker":"大倉委員","kind":"質問","question":"公園の管理なんですが、地域を回っている中で、新しくできた公園は当然新しくて、バリアフリー化もできておりますし、大変すばらしいと思うんですが、昔から親しまれている公園というところで、もともと公園に植えてある植栽というか低い木のものであったり、公園の中で抜け落ちていたり、かなり煩雑な感じになっているところで、ほかにも雑草がコンクリートのところから生えていたり。","respondent":"稲田道路公園課長","answer":"委員ご指摘の、そのような植栽が抜けていたり、また雑草が生えていたりですが、私ども巡回点検作業等で日々回っているんですけれども、より一層その辺のきめ細かな維持管理というのを心がけて、公園の利用者にも喜んでいただけるようにやっていきたいと思います。","voiceIndex":302,"id":"exchange-133"},{"speaker":"大倉委員","kind":"質問・要望","question":"２４５カ所中の２３６カ所を維持管理でやっているということなので、ぜひそうした公園が利用者にとって安心して利用できる公園にしていっていただきたいなという思いがありますので、ぜひともそれに取り組んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-134"},{"speaker":"本多委員","kind":"質問","question":"成果報告書の１５８ページ、道路維持費、路面維持管理費についてと、１６４ページの百反歩道橋架替関連整備実施設計委託。それと、同じく１５８ページ、その下の安全施設整備で交差点改良、こちらも予算が２０カ所のうち、決算１４カ所、スクールゾーンカラー標示、予算１５０m2、決算４３m2、その予算執行についてあらましで結構ですので教えてください。","respondent":"稲田道路公園課長","answer":"それを現地調査の上やりまして、当初の予定とは若干少なくなったんですが、１４カ所という実績です。それから、スクールゾーンですが、スクールゾーンにおきましても、現地の調査の結果というところで減っております。","voiceIndex":306,"id":"exchange-135"},{"speaker":"本多委員","kind":"質問・要望","question":"プレス発表で、２３区初で、要するに平日しかやっていなかった巡回サービスを、土日でもやる、祝日でもやる、これはやはり区民から見て期待する部分で、すごく多分成果があったと思うので、多分すごくいいことだったと思うので、成果報告書に１行堂々とあればよかったなと、そんな思いで、素朴にちょっと聞いたまでで、要するに台風の話とかもいろいろ出ていて。","respondent":"稲田道路公園課長、岩田都市環境事業部長、藤木交通安全担当課長","answer":"スクールゾーンの全体で何カ所ぐらいあるかというところですが、７０３カ所あるです。区では、その隅切った後の管理、これは従来はその土地の所有者が管理をしているわけですけれども、そこに石を置かれたり。そういうような実態がもしＰＴＡですとか学校とかからありましたら。","voiceIndex":308,"id":"exchange-136"},{"speaker":"本多委員","kind":"質問・要望","question":"３月１１日より以前から起きておりまして、当然区のほうも十分連絡が入って対応していただいていると聞くんですけれども、場所によっては３０cmぐらい地盤沈下が起きていて、ビルは杭を打っているからみんな現状なんですが、道路を中心にすごい勢いで陥没をしておりまして、こういうのはやはり巡回して見つけて対応するのにはかなり時間がかかるのはしようがないと思うんですけれども。","respondent":"稲田道路公園課長","answer":"ただ、それが何が原因かというところで、まず空洞ができるということは、水道とか下水、水関係がその中で流れているんではないかというふうに私どもは考えまして、それが一般的な考え方なんですけれども、東京都下水道局、水道局に調査を依頼しまして、東五反田一丁目７番、８番。","voiceIndex":312,"id":"exchange-137"},{"speaker":"本多委員","kind":"質問・要望","question":"この地盤については、本当に注視して取り組んでいっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":314,"id":"exchange-138"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、建設委員会に私は所属していまして、その中でも質問させていただいたんですが、また来年、再来年、今後何年続くかわかりませんが、この節電の関係で、また特に夏ですね、同じようなことをやらなきゃいけない状況が続く可能性が高いということで、１本１本やるんじゃなくて、遠隔で何か操作できるような、そういう街路灯がないんでしょうかということを建設委員会で聞きましたところ。","respondent":"稲田道路公園課長、品川防災整備担当課長","answer":"今後このような新しいシステムやＬＥＤ等も検討しながら、ご提案等のものも含めまして、街路灯の明るさ、その辺を品川区に合った明るさに設定していくというふうに考えております。今後、またこの対象地区で品川区がなった場合は、当然密集事業を進めている地区ですので、積極的に協力していきたいというふうに考えております。","voiceIndex":316,"id":"exchange-139"},{"speaker":"武内委員","kind":"質問・要望","question":"街路灯につきましては、まだ新聞発表段階ですので、私も全然詳しいことはわからないんですけど、こういうものがこれからどんどん出てくると思うので、来年度以降１本１本やるというのをお聞きして、本当に大変だなと思いましたので、こういうものが費用対効果を見ながら、もし取り入れられるならぜひ研究していただきたいなというふうに要望します。","respondent":"品川防災整備担当課長","answer":"空き家の件ですが、こちらについては、なかなか区としてもどういうふうに進めていったらいいかということをいろいろ検討している状況です。空き家が解消されない一番の要因としては、やはり固定資産税の関係が考えられると思います。","voiceIndex":319,"id":"exchange-140"},{"speaker":"須貝委員","kind":"確認","question":"私は１６６ページの建築確認事務についてお聞かせ願いたいと思います。先ほどもほかの委員からありましたが、建築確認事務は品川区でやっている事務と、それから民間でも実施していると。それで、実際数字を見ても品川区でやっている建築確認事務が減って、民間のほうは増えている。ところで、確認事務の前の事前相談が、これだけ増えてきている。平成１８年と比較すると、約４割も増えている。","respondent":"中村建築課長","answer":"所要時間としましては、道路などの種別をお聞きになる方は５分ぐらいで終わってしまう場合もあります。設計の詳細に入る場合は１時間ぐらいかかる場合もあります。５分から１時間ぐらい、平均すると大体２０分から３０分ほどと思います。","voiceIndex":322,"id":"exchange-141"},{"speaker":"須貝委員","kind":"確認","question":"事前相談というのは任意という話ですが、円滑に建築確認事務を行うためにかなりの方が、ほとんどの方が利用されていると思うんですが、これだけの件数が増えて、１日６０件から８０件、そして、やはり法律、法令の相談ですよね、建築基準法を含めて。そうすると、そこでお聞きしたいんですが、この相談に応じる職員の方は、１級建築士などの資格を持っているんでしょうか。","respondent":"中村建築課長","answer":"建築士の資格につきましては、全員が持っているわけではございません。一部の人間です。今、数については確認をしておりますけれども、全員ではございません。","voiceIndex":324,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"全員では仮にないということで、じゃあその中で今相当の件数の方が来庁されて相談をされている。そうすると、この方たちは全員が資格を持っていないということですから、意匠、構造、設備に対してもその方たちが、資格を持っていない方たちが対応されているということですか。","respondent":"中村建築課長","answer":"図面を審査することにつきましては、建築士であることは非常に好ましい、あるべきだと思いますが、現在、実情としましては、資格のない職員もあわせて図面を見たり、あるいは窓口で相談に応じているというのが実情です。","voiceIndex":326,"id":"exchange-143"},{"speaker":"須貝委員","kind":"確認","question":"そうすると、皆さんやはり、より正確な、やはりしっかり対応できる、職員の方はもちろん教育を受けているわけですから、それはそれでわかりますが、私は品川区、公で、公のところが許可をしているわけですよね、建築確認ということで。そうすると、安心して品川区に家を建てて住んでいける、そういう安心感を私は持つんじゃないかと思うんですが、その辺についてご見解をお聞かせください。","respondent":"中村建築課長","answer":"今、建築課でも資格を持った人間、１級建築士が９名、２級が３名、建築技術職が約２０名ほどおりますので、半数ぐらいということになりますが、今後も資格の取得に向けて進めてまいりたいと思います。","voiceIndex":328,"id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"その方たちもいて、相談に応じる方もいる、それでちょっと私もあれですが、いっとき聞いた中では、建築課はその人数を減らしているという話を聞いたような覚えがあるんですが、私はこれだけ相談件数が増えて、多くの区民の方が安心して建物を建てられて住んでいくということならば、逆に私は区民サービスも含めて、安心感も含めて増員するというのが必要じゃないかなと思うんですが。","respondent":"片田防災まちづくり事業部長","answer":"ただ、一応そういう相談についても、資格を持っていない者が担当したとしても、やはり明らかに言えるものは担当者で対応しますけれども、必ず係長あるいは私のほうにきちっと上がってきますので、適正な審査ができるような体制で現在組んでいるような状況ですし。","voiceIndex":330,"id":"exchange-145"},{"speaker":"須貝委員","kind":"確認","question":"ちょっと私はね、どうなんですか、これだけ相談件数が増えているんだから、逆に私は人数を増強して、いなければいいです、相談件数といっても、事前相談といっても、事前審査みたいなものですよね、今ね。その中で何かやりくりしているというのは、まして、これだけ相談件数が増えているというのは、私はちょっと区としても考えていく方向じゃないかなと思いますので、一言ありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":332,"id":"exchange-146"},{"speaker":"宮崎委員","kind":"質問","question":"初めに聞きたいんですけれども、このビジョンをざっと見ますと、ゆうぽうとと、そしてＴＯＣにどうやって客を誘導するか、そういう計画になっているかというふうに思うんですけれども、なぜこの時期の計画なのかということをちょっと伺いたいと思います。ちなみにこのビジョンを見ますと、いつ時点の、日付がこのビジョンにはないんですけれども、なぜこの時期なのかというのを聞きたいと思います。","respondent":"三宅都市開発課長","answer":"それ以上の具体的な計画はございませんでしたけれども、こちらの地域は、区画整理などが実施されてから４０年ほど経過しているということ、あとＴＯＣをはじめとしまして、この地域の建物の更新が必要な時期に差しかかっている。","voiceIndex":334,"id":"exchange-147"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やっぱり今このタイミングを聞いていたので、これはちゃんと的確に答えていただきたいんですよ。ＴＯＣまでの道路と低層階への店舗の配置、誘導ということを言っていますけれども、これは具体的にどういうふうに進めていくのかということを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"具体的な方法としましては、開発の機会をとらえながらそういうものを誘導していくということでございまして、何か強制力を持った形で直ちにどうするというものではございませんが、そういう開発の機会あるいは地区計画といった手法なども視野に入れて整備を働きかける。","voiceIndex":336,"id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問","question":"具体的に誘導というふうになると、今の要するに建て替え等にあわせてやっていくんだというのが中心で、法的な拘束力はないというふうに言うんですけれども、そうすると、誘導ということは具体的に何かどういうふうに進めていくのかということを伺いたいと思います。例えば、補助金をどのぐらい入れていくとか、そういう計画があるのかないのか、そこも伺いたいと思います。","respondent":"三宅都市開発課長","answer":"１点目ですが、地区計画というのはもちろんそれが成立すれば強制力を持ってくるわけですけれども、それは最終的にそういうこともあり得るということであって、地区計画をつくるまでにもちろん合意形成という前のプロセスがありますので。","voiceIndex":338,"id":"exchange-149"},{"speaker":"宮崎委員","kind":"質問","question":"今、いわゆるハードの点はまだはっきりしたものはない。もしかしたら、これからつくるかもしれない。特に低層部に商店を入れるとか、これは本当に生半可な計画じゃないと思うんですけれども、現時点でどういうふうな合意になっているのか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"ちょっと繰り返しになって申しわけございませんが、こちらはあくまでも市街地整備基本方針で設定されたにぎわいゾーンのもう少し詳細な計画というレベルのものでございまして、地区計画の直前の計画というような具体性。","voiceIndex":340,"id":"exchange-150"},{"speaker":"宮崎委員","kind":"質問","question":"そこでちょっと伺いたいんですけれども、ＴＯＣは、実際に先日の請願審査のときのお話では、１００ｍよりも低くなるだろうというお話ですけれども、具体的にどういうふうに伺っていますか。請願審査のときには、かなり緊密に連携をとって連絡をとってやっていると言っていますけれども、このまちづくりビジョンの一番肝心なＴＯＣの計画は今どうなっているか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"都市計画的な手法の活用も含めて何案か比較検討している状況です。したがいまして、幾つも案がありまして、高さ、どうこう、そこら辺はまだ公にご説明できる状況ではございません。","voiceIndex":342,"id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問","question":"これは税金を使ってビジョンをつくってきたやつですね。それで、ＴＯＣにお客を誘導する計画です。今幾つかの案があると言いましたけれども、その主な内容をちょっと伺いたいと思うんですが、よろしくお願いします。","respondent":"三宅都市開発課長","answer":"すみません、先ほどと同じ答弁になりますが、今内部検討を主にやっておりまして、まだ公にできる状況ではございません。ちょっとこちらのビジョンの内容ですが、このＴＯＣのほうにお客さんを誘導することを主目的にしているわけではございません。","voiceIndex":344,"id":"exchange-152"},{"speaker":"宮崎委員","kind":"質問","question":"私は、やっぱり税金でつくってきた計画ですから、これは今具体的にどういうふうに検討しているのか、そこのところはしっかり言うべきだと思います。具体的な計画が言えないのであれば、具体的に今のところでは、現状のテナントの数を維持するのか、それとも減る可能性もあるのか、そういうところはどういうふうに考えているんでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"一定の方向性を決めた中で、そういう大きな方針に基づいて指導していくといったような観点からつくったものですので、そういう方向で理解していただければと思います。","voiceIndex":346,"id":"exchange-153"},{"speaker":"宮崎委員","kind":"意見","question":"今まちづくり協議会の話もありました。でも、このビジョンを見ますと、まちづくり協議会とはと説明があるんですけれども、具体的にだれが、どういうメンバーがやっているのか、本当にこの地域を、本当に代表できる、そういうメンバーなのかどうなのか、それもわからないんですよね。この点も指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":348,"id":"exchange-154"},{"speaker":"井上委員","kind":"質問","question":"私からは、１５８ページの道路維持費、１６２ページの都市計画費の区民の自主的なまちづくりへの支援、１６２ページ、まちづくりマスタープラン推進費についてお伺いをいたします。区民の自主的なまちづくりへの支援についてお伺いをいたします。２０１０年度は、実績は専門家派遣団体が１件、専門家派遣が６件で、先ほどの団体だけが専門家の派遣を利用したというものです。","respondent":"山崎マスタープラン担当課長","answer":"それで、この事業につきましては、先ほども申し上げましたとおり区民が主体的なまちづくりに関与していくために区が必要な支援を行うという非常に根幹な仕組みですので、有効に今後活用できるよう、いろんな意味で改善等々検討してまいりたいというふうに考えてあります。","voiceIndex":350,"id":"exchange-155"},{"speaker":"井上委員","kind":"質問","question":"今、地域のまちづくりの熟度だというふうに、区民側の責任であるような発言だったんですけれども、周知とかいろんな部分で改善をする必要があるのかなというふうに思っているんですけれども、まずこの制度を申請するのに提出書類がたくさんあるかと思いますが、申請書が何号まであるのか、そういった煩雑さが活用を躊躇させるのではないかというふうに思うんですが、区の見解を伺います。","respondent":"山崎マスタープラン担当課長","answer":"所要の書式が要綱に定められておりまして、いろいろ変更等々の様式も含めまして、第１５号様式までというようなことで規定しているものです。","voiceIndex":352,"id":"exchange-156"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、一度登録したら、相手方から取り消しを求めなければずっとそのままになっているのではないかというふうに思うんですけれども、３年とか５年とか、期限を切って登録の意思確認をするなど、活用を推進しようという意識を持った対応をすべきというふうに思うんですけれども、現状はどのようになっているのでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"まちづくり専門家の登録の状況です。現在登録をいただいております団体は５３団体です。","voiceIndex":354,"id":"exchange-157"},{"speaker":"井上委員","kind":"質問・要望","question":"これを簡略化するということとか、あるいは１回１回、団体が登録、派遣をするのに書類を書かなければいけないとか、そういった問題もあるかというふうに思うので、団体が計画するまちづくりの企画や学習会など、パッケージで派遣を依頼できる、そういうふうにするとか、運用を工夫したことで、もっともっとＰＲも可能になるだろうというふうに思うんですが。","respondent":"山崎マスタープラン担当課長","answer":"ただ、公金を支出する際の確認書類として、必要な部分もありますので、いろいろ委員ご指摘の意味も勘案して手続を簡素化できるところはそうした観点で改善に努めてまいりたいというふうに考えてあります。","voiceIndex":356,"id":"exchange-158"},{"speaker":"井上委員","kind":"質問・要望","question":"それから次は道路維持費なんですけれども、２０１０年に２３区初の新規事業で、閉庁時のパトロールが始まりまして、昨年の予算特別委員会では既に平日民間事業委託をしているということでしたので、この事業が含まれている清掃等委託の中で、平日の委託料と休日の委託料の決算額をお伺いいたします。そして、これは委託先はどこなのか教えてください。","respondent":"稲田道路公園課長","answer":"閉庁時道路巡回点検委託の決算額は、８６３万３,９４０円です。それから平日のほうですが、道路巡回点検委託という名称でございまして、６,４０７万９,１００円です。こちらの業者ですが、平成２２年度は区内の道路業者です。","voiceIndex":358,"id":"exchange-159"},{"speaker":"井上委員","kind":"質問","question":"初めて、２３区初で、休日の緊急対応に備えるということだったんですが、その問題意識の前提で、休日の緊急対応が必要な件数が民間委託前の５年間ぐらいでどのぐらい年度にあったのか教えてください。","respondent":"稲田道路公園課長","answer":"委託前と委託後の土日、休日の緊急委託の件数ですが、正しい把握はしておりませんけれども、基本的には変わらないです。","voiceIndex":360,"id":"exchange-160"},{"speaker":"井上委員","kind":"質問・要望","question":"一番言いたいことは、震災対策特別委員会で、災害時など被害調査班が町中に出て調査をしていただいたということを説明を受けまして、日頃から民間任せではなくて、区の職員の方々がまちのことを知っていただいているということは、震災に対して本当に区民にとって安心感があるということで、本当は実績を伺ってから、必要がないのではないでしょうかと言いたかったんですけれども。","respondent":"山崎マスタープラン担当課長","answer":"市民参加ということの観点では、基本的にはマスタープランの策定の状況は、ホームページ等々で公表するようなこと、それからパブリックコメントをするというような基本的なことから、広報のほうのさまざまなツールを使いまして。","voiceIndex":364,"id":"exchange-161"},{"speaker":"井上委員","kind":"意見","question":"本来マスタープランの策定というのは、前回のマスタープラン作成にも市民参加を保証するということが定義づけられていたかと思います。今回計画についてパブリックコメントという中ではなくて、計画策定時に参加をしていくことでないと、パブリックコメントはなかなか難しいと……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":366,"id":"exchange-162"},{"speaker":"若林委員","kind":"確認","question":"１５８ページの街路樹等維持管理費から１６３ページの公園管理費に入ると思います。街路樹のほうは、今回９月２１日、先ほどもお話が出ておりまして、区で区有の樹木というんでしょうか、４４本が倒木をしたというふうなことでございました。その事実関係を確認するのが一つと、正しいとすれば、いずれにしても流された原因というのはどういうところにあるのかというのを一つお聞きをしておきたいと思います。","respondent":"稲田道路公園課長、藤田水とみどりの課長","answer":"そういうことで、今後より一層の点検、それから対応をしていきたいと思うんですが、専門家等も入れながら考えていきたいと、一部やっていきたいと考えています。２月に流出をしまして、その後腐食により流れてしまったということで、港湾局のほうで今後の維持管理をしっかりできるような維持管理の計画書を提出しなさいということが今求められておりまして。","voiceIndex":368,"id":"exchange-163"},{"speaker":"若林委員","kind":"提案","question":"私、款別かなんかのずっと前ですけども、こういう専門家、樹木医の紹介をしながらご提案をさせていただいたことがありますので、これからそういう樹木医等の専門家を交えて今後の対策を立てていくということでよろしいか、一つ確認をさせていただきたいのと、木が倒れるというのは、ちょうど今だんだん秋になってきましたけども。","respondent":"岩田都市環境事業部長、藤田水とみどりの課長","answer":"委員ご指摘のように普通は台風以前に夏季剪定、特に覆い繁るような樹木等については、夏季剪定で葉っぱをかなり落として風速に耐えられるような形状に整えてはおりますけれども。その辺を含めまして、防災面、それからにぎわい、そういった面の活用を広げていきたいというふうに考えてあります。船を持つことにつきましては、さまざまな面から検討させていただきたいと思います。","voiceIndex":371,"id":"exchange-164"},{"speaker":"松澤委員","kind":"質問","question":"自分の質問に入ります前に、先ほど倒木、木が倒れちゃった後どうするの。特にあそこの鮫洲運動公園は、子どもたちの意を取り入れてつくった公園ですから、それとの整合性も図らなくちゃいけないかなというふうに考えたときに、すぐやりますという答弁はちょっと安易過ぎたかなということで苦言を呈しておきます。成果報告書の１６０ページ、踏切改良事業４３８万円、この事業内容についてお知らせください。","respondent":"武藤都市整備下水道課長","answer":"踏切改良事業についてのご質問ですけれども、道路幅員の狭い踏切道におきまして、踏切内の拡幅を行うほか、交通安全の観点から当該部分をカラー化して、車の運転手に歩行者の通行帯を認識させるなどの事業です。","voiceIndex":375,"id":"exchange-165"},{"speaker":"松澤委員","kind":"質問","question":"簡単にお答えをいただきました。これはたしか３カ所の改良工事で、最後かな、苗木原踏切あるいは下神明１号踏切、戸越銀座の駅の南側ですかね、これの最後の工事かなということで、やっと終わったなというような感じで質問させていただきました。","respondent":"山崎マスタープラン担当課長","answer":"大井町線は５両編成でございまして、現在大井町から下神明側に向かって下神明２号踏切を車両が２両ふさぐ形で停車をするということで、５両編成に必要なホームの長さが戸越公園の場合は得られていない状況だということで、大井町側から向かいまして。","voiceIndex":377,"id":"exchange-166"},{"speaker":"松澤委員","kind":"質問","question":"ただ、区にするとメリットよりもデメリット、区道を整備しなくちゃいけない、見守らなくちゃいけないという負担が多いように感じるんですけれども、そのメリット、デメリットを考えたときに、品川区はどのように東急電鉄側に、今地域貢献施設ということで、いろいろこういうふうにしなさい、先ほども旗の台駅の南口でしょうかね、駐輪場をつくる約束なのにつくっていないという話がありましたけれども。","respondent":"山崎マスタープラン担当課長","answer":"今回のドアの開閉を解消するというところで、戸越公園利用者の利便性の向上、それから何にも増して、車両が踏切をまたぐ形でとまっているということで、１時間に４０分以上踏切がしまっているような状態、いわゆるボトルネック踏切というような表現をしておりますけれども。","voiceIndex":379,"id":"exchange-167"},{"speaker":"松澤委員","kind":"質問","question":"そういうことで地元でも運動しているんですけれども、東急電鉄側としてはこの国土交通省からいわれていた踏切の解消をしてしまうと、いや、まだまだ先でもいいじゃないかと先延ばしになるんじゃないかというふうに私は思っているんですけれども、この辺、東急電鉄側から高架化について地元と話をしていますけれども、しっかりと進めていきますよというしっかりとしたコメントはとっているんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"東急電鉄のほうは、今回のホームドアの件の解消が図られた後も連立化の検討に向けて区あるいは地元のほうと協議は進めていくということで聞いております。","voiceIndex":381,"id":"exchange-168"},{"speaker":"松澤委員","kind":"質問・要望","question":"よくわかりました。次の質問ということで、同じく１６０ページの排水施設建設事業、出水対策・立坑原状回復工事費、これが上げられていますけれども、これは戸越幹線ができたんだけども、原因不明の出水があったということで、今それが直されて、今現在は公園もでき上がっていますけれども、この原因というものがはっきりわかったんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"これにつきましては、東京都も含めて検討の調査委員会を立ち上げまして、原因について究明をしましたが、水が出てきている状況は把握できたんですけれども、その根本的な原因については究明ができなかったというものです。","voiceIndex":383,"id":"exchange-169"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。それで了としておきます。１時間換算で４８mm、品川区は５０mm対応ですから、それで水が出なかったのかなとは思いますけれども、床上・床下浸水はありませんでした。このときに目黒川の雨水貯留池、あるいは西品川の貯留池、戸越幹線の今言いました地下の貯留管、あるいは第二立会川幹線、これがどのような働きをしたのかということを教えていただきたいと思います。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり品川区内につきましては、１時間５０mmに対応できる下水道の整備を進めているところですけれども、さまざまな今ご指摘のような貯留管が整備されまして、当日９月のときの雨の状況なんですけれども、河川の調節池については流入はございませんでしたが。","voiceIndex":385,"id":"exchange-170"},{"speaker":"松澤委員","kind":"確認","question":"そうしますと、目黒川の貯留池には入ったけども、第二立会川幹線とか戸越の幹線は水を入れるに至らなかったということなんでしょうか、確認したいと思います。","respondent":"武藤都市整備下水道課長","answer":"もう１回確認しますが、河川の目黒川の調節池には流入はございませんでした。その他下水道の調整池、区内に何カ所か、約８カ所程度ありますけれども、そのうち約５カ所の調整池において流入が確認されております。","voiceIndex":387,"id":"exchange-171"},{"speaker":"松澤委員","kind":"確認","question":"そうしますと、調整池が十分に働いたということで、現状５０mm対応ができましたよということですけれども、実際にそれができたということで、今後ともまだ余裕があるということでよろしいですよね。その確認だけして質問を終わりたいと思います。","respondent":"武藤都市整備下水道課長","answer":"実際降る雨につきましては、さまざまな降り方がありますので、一概に余裕があるという形にはなかなか申し上げられないんですけれども、今の設計上の考えであれば、１時間５０mmに近い雨に対応できるという考え方で今整備ができているという状況です。","voiceIndex":389,"id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":111070,"voices":391}}]);
